INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('54c98e05-9b52-4c9d-b8d0-ae6e9eff99ad', '54857970-6269-4f19-a601-6e6f2834a769', 'Permohonan Sangat Sopan di Kantor', 'Kuasai pola ～ていただけませんか untuk meminta bantuan, penjelasan ulang, dan koreksi kepada atasan, klien, maupun staf layanan secara santun.', 'curriculum', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('67151752-a47e-4d19-9978-facd0fb040c0', '54857970-6269-4f19-a601-6e6f2834a769', 'Keadaan Hasil Aksi Disengaja', 'Gunakan pola ～てあります untuk melaporkan persiapan ruang rapat, catatan yang sudah ditulis, dan pengumuman yang sengaja dipasang.', 'curriculum', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('1b703ae6-c69c-412d-83b6-ffcde17f525c', '54857970-6269-4f19-a601-6e6f2834a769', 'Bentuk Keharusan & Aturan Kerja', 'Kuasai pola ～なければなりません untuk memahami dan menyampaikan kewajiban, prosedur keselamatan kerja, serta tenggat waktu.', 'curriculum', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('82525659-1381-4a78-b047-84d1cd7bf52b', '54857970-6269-4f19-a601-6e6f2834a769', 'Bentuk Potensial: Kemampuan & Fasilitas', 'Pelajari bentuk potensial (～られる / ～える) untuk menjelaskan keahlian kerja, bahasa yang dikuasai, dan fasilitas yang tersedia.', 'curriculum', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('80840d2b-a999-4766-acb8-6295a6789efe', '54857970-6269-4f19-a601-6e6f2834a769', 'Memberi & Menerima Bantuan', 'Pahami perspektif pemberi dan penerima bantuan dengan ～てあげる, ～てくれる, dan ～てもらう dalam kerja sama tim dan pertemanan.', 'curriculum', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('c57ac57e-69c0-4248-ac67-b5b56cac0960', '54857970-6269-4f19-a601-6e6f2834a769', 'Saran Sebaiknya: Kesehatan & Harian', 'Gunakan pola ～たほうがいい dan ～ないほうがいい untuk memberikan nasihat yang jelas terkait kesehatan, klinik, dan kehidupan sehari-hari.', 'curriculum', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('3defef9f-7fde-463d-b078-b848830856d6', '54857970-6269-4f19-a601-6e6f2834a769', 'Menyatakan Alasan Halus & Izin Sopan', 'Gunakan konjungsi ～ので untuk menyampaikan alasan secara objektif dan sopan saat meminta izin, menjelaskan keterlambatan, atau memberi informasi.', 'curriculum', 7, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('5fa26d4e-392a-4072-a9ca-fdaccefee4b9', '54857970-6269-4f19-a601-6e6f2834a769', 'Syarat & Pengandaian (～たら)', 'Kuasai pola ～たら untuk menyatakan syarat ''jika/kalau'' maupun urutan waktu ''setelah selesai'' dalam rencana akhir pekan, cuaca, dan prosedur kerja.', 'curriculum', 8, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('345bacc0-28a3-42be-aae9-cde05f19a823', '54857970-6269-4f19-a601-6e6f2834a769', 'Persiapan Sebelumnya (～ておく)', 'Gunakan pola ～ておきます untuk menyatakan tindakan persiapan terlebih dahulu sebelum rapat, perjalanan, atau kegiatan rumah tangga.', 'curriculum', 9, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('d2bf18f3-2e0c-487d-8283-43e0ceb4a8bb', '54857970-6269-4f19-a601-6e6f2834a769', 'Kenjougo Dasar & Kesiapan JLPT N4', 'Kuasai bentuk sopan merendah (Kenjougo dasar: お～します, まいります, いたします, 申します) untuk melayani tamu, etika bisnis, dan kesiapan ujian N4.', 'curriculum', 10, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
