INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d48d576-7813-44c6-ae2e-37e0f6125bf0', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang berarti ''memesan terlebih dahulu'': 出張の前に、新幹線とホテルを___しておきます。', '{"options":["予約","見学","遅刻","質問"],"translation":"Sebelum perjalanan dinas, saya memesan Shinkansen dan hotel lebih dulu.","sentence_template":"出張の前に、新幹線とホテルを[blank]しておきます。"}'::jsonb, '{"selected":"予約"}'::jsonb, NULL, NULL, '予約する (yoyaku suru) berarti membuat reservasi/pemesanan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f1b509d-18e8-4856-8c58-9876dc7b27a3', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata persiapan pelajaran/rapat: 明日の授業のために、新しい単語を___しておきます。', '{"options":["洗濯","予習","散歩","買い物"],"translation":"Untuk kelas besok, saya mempelajari kosakata baru terlebih dahulu.","sentence_template":"明日の授業のために、新しい単語を[blank]しておきます。"}'::jsonb, '{"selected":"予習"}'::jsonb, NULL, NULL, '予習 (yoshuu) berarti belajar pendahuluan sebelum pelajaran dimulai (lawan dari 復習 = mengulang).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ee172b23-8597-4354-bd2a-8e3864c5e9d8', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan persiapan perjalanan ini. Apa yang sudah diperiksa?', '{"options":[{"id":"opt_1","text":"Harga suvenir di bandara"},{"id":"opt_2","text":"Cuaca minggu depan"},{"id":"opt_3","text":"Menu sarapan di hotel"},{"id":"opt_4","text":"Waktu transit kereta sebelum berangkat besok"}],"audio_text":"明日の出発前に、電車の乗り換え時間を調べておきました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '乗り換え時間 (norikae jikan) adalah waktu pindah/transit kereta; 調べておきました berarti sudah dicari tahu sebelumnya.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('62de5903-fc40-4438-8363-2ea42c90bfa7', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rumah tangga ini. Apa yang akan dilakukan sebelum tamu tiba?', '{"options":[{"id":"opt_1","text":"Menyiapkan teh dingin sebelum tamu datang"},{"id":"opt_2","text":"Memesan makanan dari luar"},{"id":"opt_3","text":"Mematikan lampu ruang tamu"},{"id":"opt_4","text":"Pergi berbelanja ke supermarket"}],"audio_text":"お客様が来る前に、冷たいお茶を用意しておきますね。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '用意しておきます berarti akan menyiapkan terlebih dahulu untuk kedatangan tamu.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('daf702cb-9c52-4d3a-ad68-77372741497e', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum rapat dimulai, saya memfotokopi materi terlebih dahulu."', '{"romaji":"Kaigi no mae ni, shiryou o kopii shite okimasu.","tokens":["コピーして","おきます。","資料を","会議の前に、","コピーします。","あります。"],"target_translation":"Sebelum rapat dimulai, saya memfotokopi materi terlebih dahulu."}'::jsonb, '["会議の前に、","資料を","コピーして","おきます。"]'::jsonb, NULL, NULL, 'コピーしておきます menyatakan tindakan aktif menyiapkan fotokopi sebelum rapat.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9ced0e04-2842-42eb-848e-cc7a61029af5', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan mengecas ponsel sebelum tidur malam ini."', '{"romaji":"Konya neru mae ni, sumaho o juuden shite okimasu.","display_text":"今夜寝る前に、スマホを充電しておきます。","phonetic_breakdown":["kon-ya","ne-ru","ma-e","ni","su-ma-ho","o","ju-u-den","shi-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"今夜寝る前に、スマホを充電しておきます。"}'::jsonb, NULL, NULL, '充電する (juuden suru) berarti mengisi daya baterai; ～ておきます menekankan persiapan untuk besok.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0bbf59a4-1603-49eb-aae1-50450dcbcec7', '0433cfee-b60c-4987-b456-60d1c60f829c', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: プレゼンの前に、プロジェクターの動作を___しておきます。', '{"options":["点検","欠席","散歩","卒業"],"translation":"Sebelum presentasi, saya akan memeriksa fungsi proyektor terlebih dahulu.","sentence_template":"プレゼンの前に、プロジェクターの動作を[blank]しておきます。"}'::jsonb, '{"selected":"点検"}'::jsonb, NULL, NULL, '点検する (tenken suru) berarti mengecek atau menginspeksi kelayakan alat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('10a33fc6-ed29-456e-84f8-0128384bece8', '0433cfee-b60c-4987-b456-60d1c60f829c', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan ajakan rekan kerja berikut. Apa yang akan dilakukan sebelum tamu datang?', '{"options":[{"id":"opt_1","text":"Mengajak menyiapkan teh dingin di ruang rapat sebelum tamu datang"},{"id":"opt_2","text":"Mengajak minum teh bersama setelah tamu pulang"},{"id":"opt_3","text":"Mengatakan bahwa teh di ruang rapat sudah habis"},{"id":"opt_4","text":"Meminta tamu membawa minuman sendiri"}],"audio_text":"お客さんが来る前に、会議室に冷たいお茶を用意しておきましょう。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '用意しておきましょう berarti ''mari kita siapkan terlebih dahulu''.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fab11ad7-3ad7-4c8d-9b93-1ac8224510c0', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Apa yang diminta senior sebelum rapat jam dua?', '{"options":[{"id":"opt_1","text":"Membuat kopi untuk sepuluh orang"},{"id":"opt_2","text":"Membersihkan papan tulis sebelum rapat jam dua"},{"id":"opt_3","text":"Mengirim undangan rapat baru"},{"id":"opt_4","text":"Mematikan proyektor ruang rapat"}],"audio_text":"二時から会議ですから、ホワイトボードをきれいにしておいてくれますか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'ホワイトボードをきれいにしておいてくれますか meminta membersihkan papan tulis sebelumnya.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('024870a8-f84f-419f-88e6-1c03a683fc2b', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan tentang penggunaan alat. Apa arti kalimat ''そのままにしておいてください''?', '{"options":[{"id":"opt_1","text":"Tolong buang dokumen itu sekarang juga"},{"id":"opt_2","text":"Tolong fotokopi dokumen itu dua kali"},{"id":"opt_3","text":"Tolong biarkan dokumen itu apa adanya di atas meja karena masih dipakai"},{"id":"opt_4","text":"Tolong simpan dokumen itu di gudang"}],"audio_text":"その資料はまだ使いますから、机の上にそのままにしておいてください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'そのままにしておく adalah penggunaan penting ～ておく yang berarti ''membiarkan dalam kondisi seperti itu''.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d0f5515-143a-4b9e-9ff1-61a4c250a0d7', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan persiapan sebelum pulang kampung. Apa yang sudah dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Ia baru akan membeli oleh-oleh di bandara"},{"id":"opt_2","text":"Ia membatalkan kepulangannya minggu depan"},{"id":"opt_3","text":"Ia lupa membeli oleh-oleh"},{"id":"opt_4","text":"Ia sudah membeli oleh-oleh untuk teman sebelumnya"}],"audio_text":"来週帰国するので、友達へのお土産をもう買っておきました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'お土産をもう買っておきました berarti sudah membeli oleh-oleh sebelumnya.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8cb7920e-4221-4b85-91ff-adb11ac93b56', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Pilih bentuk TE yang tepat untuk 調べます (mencari tahu): 面接の前に、会社のことをよく___おいたほうがいいです。', '{"options":["調べいて","調べて","調べって","調べんで"],"translation":"Sebelum wawancara, sebaiknya mencari tahu tentang perusahaan itu dengan baik lebih dulu.","sentence_template":"面接の前に、会社のことをよく[blank]おいたほうがいいです。"}'::jsonb, '{"selected":"調べて"}'::jsonb, NULL, NULL, '調べます (Grup 2) -> Bentuk TE: 調べて + おいたほうがいいです.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51a84d57-f3f3-4476-9a11-942dc07251a4', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat membiarkan jendela tetap terbuka: 少し暑いので、窓を開けて___いいですか。', '{"options":["おきますも","おいたも","おいても","おかないも"],"translation":"Karena agak panas, bolehkah jendela dibiarkan tetap terbuka?","sentence_template":"少し暑いので、窓を開けて[blank]いいですか。"}'::jsonb, '{"selected":"おいても"}'::jsonb, NULL, NULL, '開けておいてもいいですか berarti ''bolehkah dibiarkan terbuka?''.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b94c8d2-733d-493f-938d-f231e8ed5695', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat menyimpan uang demi masa depan: 将来のために、毎月少しずつ貯金して___。', '{"options":["いきますか","きますか","あります","おきます"],"translation":"Demi masa depan, saya menabung sedikit demi sedikit setiap bulan.","sentence_template":"将来のために、毎月少しずつ貯金して[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, NULL, NULL, '貯金しておきます menekankan menabung sebagai persiapan masa depan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('363e3b5d-ecfa-45d8-bc6b-9512f9b54560', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan laporan persiapan berikut. Apa yang sudah dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Rekan kerja diminta memfotokopi 20 rangkap besok pagi"},{"id":"opt_2","text":"Materi yang akan dipakai besok sudah difotokopi 20 rangkap terlebih dahulu sekarang"},{"id":"opt_3","text":"Mesin fotokopi rusak saat mencetak 20 rangkap"},{"id":"opt_4","text":"Materi untuk besok belum sempat difotokopi"}],"audio_text":"明日使う資料は、今のうちに二十部コピーしておきましたよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'コピーしておきました menyatakan tindakan persiapan yang sudah diselesaikan lebih awal.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('77fdf7f9-c220-4247-9615-59d86580dadd', '05c6edd0-d6cb-4785-86a5-60a4fe3aab6b', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 忘れないように、大事な予定はスマホのカレンダーに___おきます。', '{"options":["入れる","入れた","入れて","入れ"],"translation":"Supaya tidak lupa, saya akan memasukkan jadwal penting ke kalender ponsel terlebih dahulu.","sentence_template":"忘れないように、大事な予定はスマホのカレンダーに[blank]おきます。"}'::jsonb, '{"selected":"入れて"}'::jsonb, NULL, NULL, '入れる -> 入れて + おきます.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a3d4d23-338d-4faa-b27d-505193595d42', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'reading', 'fill_blank', 'Pilih benda yang biasa ditempel pengumuman di pabrik/kantor: 新しいシフト表が___に貼ってあります。', '{"options":["傘立て","洗濯機","掲示板","冷蔵庫"],"translation":"Jadwal shift baru sudah ditempel di papan pengumuman.","sentence_template":"新しいシフト表が[blank]に貼ってあります。"}'::jsonb, '{"selected":"掲示板"}'::jsonb, NULL, NULL, '掲示板 (keijiban) berarti papan pengumuman, tempat menempel jadwal atau informasi kerja.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bfbe1842-5e54-48e4-a48e-d1e192b52973', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata perlengkapan ruang rapat: 会議室の___の上に飲み物が並べてあります。', '{"options":["切符","ポケット","エレベーター","テーブル"],"translation":"Di atas meja ruang rapat, minuman sudah ditata rapi.","sentence_template":"会議室の[blank]の上に飲み物が並べてあります。"}'::jsonb, '{"selected":"テーブル"}'::jsonb, NULL, NULL, 'テーブル (teeburu) berarti meja. 並べてあります berarti sudah ditata dengan sengaja.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dc812ae2-541b-47e2-8ba3-871f7e47cd13', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'listening', 'listening_choice', 'Dengarkan informasi staf berikut. Di mana kunci gudang disimpan?', '{"options":[{"id":"opt_1","text":"Di dalam laci meja resepsionis"},{"id":"opt_2","text":"Di saku baju manajer"},{"id":"opt_3","text":"Di atas rak buku ruang istirahat"},{"id":"opt_4","text":"Di dekat pintu gerbang depan"}],"audio_text":"倉庫の鍵は、受付の引き出しの中に入れてあります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '引き出しの中 (hikidashi no naka) berarti di dalam laci.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a31b05dd-0853-4b49-be71-68d5ac34d364', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan ini. Apa yang terpasang di dinding?', '{"options":[{"id":"opt_1","text":"Peta jalur kereta bawah tanah"},{"id":"opt_2","text":"Poster aturan keselamatan"},{"id":"opt_3","text":"Foto karyawan teladan"},{"id":"opt_4","text":"Kalender hari libur nasional"}],"audio_text":"壁に安全ルールのポスターが貼ってあります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '安全ルールのポスター (anzen ruuru no posutaa) berarti poster aturan keselamatan.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac20e81e-fa07-45f2-995e-75c3d01117c1', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Di papan tulis sudah tertulis jadwal hari ini."', '{"romaji":"Howaitoboodo ni kyou no yotei ga kaite arimasu.","tokens":["書きます","予定が","今日の","予定を","ホワイトボードに","あります。","書いて"],"target_translation":"Di papan tulis sudah tertulis jadwal hari ini."}'::jsonb, '["ホワイトボードに","今日の","予定が","書いて","あります。"]'::jsonb, NULL, NULL, 'Pada pola ～てあります, objek yang mengalami keadaan ditandai partikel が (予定が書いてあります).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4e723e2-6935-4205-b637-e44cd68a0fb6', '07df9785-1ad9-431e-a512-08bc0be9776f', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Persiapan ruang rapat sudah selesai."', '{"romaji":"Kaigishitsu no junbi wa mou shite arimasu.","display_text":"会議室の準備はもうしてあります。","phonetic_breakdown":["ka-i-gi-shi-tsu","no","jun-bi","wa","mo-u","shi-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"会議室の準備はもうしてあります。"}'::jsonb, NULL, NULL, '準備 (junbi) berarti persiapan; もうしてあります menekankan persiapan sudah dilakukan sebelumnya.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0aeb3d2d-c1ec-4e9e-b83c-da6b31790c3c', '07df9785-1ad9-431e-a512-08bc0be9776f', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 受付の机の上に、来客用の名札が___あります。', '{"options":["並べて","並んだ","並べる","並び"],"translation":"Di atas meja resepsionis, kartu nama tamu sudah ditata rapi.","sentence_template":"受付の机の上に、来客用の名札が[blank]あります。"}'::jsonb, '{"selected":"並べて"}'::jsonb, NULL, NULL, '並べてあります memakai kata kerja transitif 並べる dalam bentuk て untuk menunjukkan hasil penataan yang disengaja.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d358c28-8571-4bc6-8f80-11870a511644', '07df9785-1ad9-431e-a512-08bc0be9776f', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan ucapan tuan rumah berikut. Informasi apa yang disampaikan?', '{"options":[{"id":"opt_1","text":"Teh dingin sedang dibuat di dapur"},{"id":"opt_2","text":"Kulkas sedang rusak sehingga tidak ada teh"},{"id":"opt_3","text":"Teh dingin sudah sengaja disiapkan di dalam kulkas untuk diminum"},{"id":"opt_4","text":"Pembicara meminta tamu membeli teh di minimarket"}],"audio_text":"冷蔵庫の中に冷たいお茶が入れてありますから、ご自由にどうぞ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '入れてあります menyatakan bahwa seseorang sudah memasukkan teh dengan sengaja untuk tamu.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('183aa0d8-4b1f-45fd-84af-c88a420cc9d1', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran sebelum keluar rumah berikut. Apa yang dianjurkan?', '{"options":[{"id":"opt_1","text":"Di luar sudah sangat dingin, jadi sebaiknya memakai mantel saat keluar"},{"id":"opt_2","text":"Di luar sangat panas sehingga tidak perlu membawa mantel"},{"id":"opt_3","text":"Pembicara meminta lawan bicara mencuci mantel"},{"id":"opt_4","text":"Suhu di luar tidak berubah sejak siang tadi"}],"audio_text":"外はかなり冷え込んできましたよ。コートを着て出かけたほうがいいと思います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'コートを着て出かけたほうがいい menyarankan memakai mantel sebelum berangkat.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c969dc2-697d-4129-87b6-3fd4983bd181', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau stres menumpuk, sebaiknya beristirahat sebentar."', '{"romaji":"Sutoresu ga tamattara, sukoshi yasunda hou ga ii desu yo.","display_text":"ストレスがたまったら、少し休んだほうがいいですよ。","phonetic_breakdown":["su-to-re-su-ga","ta-mat-ta-ra","su-ko-shi","ya-sun-da","hou-ga","ii-de-su-yo"]}'::jsonb, '{"expected_transcript":"ストレスがたまったら、少し休んだほうがいいですよ。"}'::jsonb, NULL, NULL, '休む -> 休んだほうがいい.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3fef638a-48d5-4ac4-ba66-cb6a3fc9b5a7', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Email penting sebaiknya dibaca ulang sebelum dikirim."', '{"romaji":"Taisetsu na meeru wa okuru mae ni yominaoshita hou ga ii desu.","tokens":["大切な","いいです。","ほうが","へ","読み直す","送る前に","メールは","読み直した"],"target_translation":"Email penting sebaiknya dibaca ulang sebelum dikirim."}'::jsonb, '["大切な","メールは","送る前に","読み直した","ほうが","いいです。"]'::jsonb, NULL, NULL, '読み直す (yominaosu, membaca ulang) -> 読み直したほうがいい.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2953d86a-4032-4f37-981f-9b408abe2f9d', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 約束の時間に遅れそうなら、早めに電話を___ほうがいいですよ。', '{"options":["かけた","かけない","かけて","かける"],"translation":"Kalau tampaknya akan terlambat dari waktu janji, sebaiknya segera menelepon.","sentence_template":"約束の時間に遅れそうなら、早めに電話を[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"かけた"}'::jsonb, NULL, NULL, '電話をかける -> 電話をかけたほうがいい.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7231653a-9828-45b0-ac1d-b52ec27943fb', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran di gudang berikut. Mengapa pembicara menyarankan mengangkat berdua?', '{"options":[{"id":"opt_1","text":"Pembicara sedang sakit pinggang sehingga tidak bisa membantu"},{"id":"opt_2","text":"Sebaiknya mengangkat kotak berat itu berdua agar tidak mencederai pinggang"},{"id":"opt_3","text":"Kotak itu tidak perlu dipindahkan hari ini"},{"id":"opt_4","text":"Kotak itu ringan sehingga cukup diangkat satu orang"}],"audio_text":"その重い箱を一人で持つと腰を痛めますよ。二人で運んだほうがいいです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '腰を痛める berarti mencederai pinggang; 二人で運んだほうがいい menyarankan diangkat berdua.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('495f1c47-cadb-45cb-a93b-75d696f6b427', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum tidur sebaiknya tidak melihat ponsel pintar."', '{"romaji":"Neru mae ni sumaatofon o minai hou ga ii desu.","display_text":"寝る前にスマートフォンを見ないほうがいいです。","phonetic_breakdown":["ne-ru-ma-e-ni","su-maa-to-fon-o","mi-nai","hou-ga","ii-de-su"]}'::jsonb, '{"expected_transcript":"寝る前にスマートフォンを見ないほうがいいです。"}'::jsonb, NULL, NULL, '見ないほうがいい adalah saran kebiasaan tidur sehat.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1889c19e-8c66-4371-9128-fbb8ba5fd411', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Makanan yang tinggi garam sebaiknya tidak dimakan berlebihan."', '{"romaji":"Enbun no ooi ryouri wa tabesuginai hou ga ii desu yo.","tokens":["食べすぎない","いいですよ。","と","料理は","ほうが","多い","食べすぎた","塩分の"],"target_translation":"Makanan yang tinggi garam sebaiknya tidak dimakan berlebihan."}'::jsonb, '["塩分の","多い","料理は","食べすぎない","ほうが","いいですよ。"]'::jsonb, NULL, NULL, '食べすぎる -> 食べすぎないほうがいい.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6d88cb67-7cf6-495f-9b56-48d2f212fbf8', '0b77eafb-99f5-4544-b1b7-ef62132f5292', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 面接の前に会社のホームページをよく___ほうがいいです。', '{"options":["調べない","調べて","調べる","調べた"],"translation":"Sebelum wawancara, sebaiknya mempelajari situs web perusahaan dengan baik.","sentence_template":"面接の前に会社のホームページをよく[blank]ほうがいいです。"}'::jsonb, '{"selected":"調べた"}'::jsonb, NULL, NULL, '調べる -> 調べたほうがいい.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9bf39611-a9f7-4327-ac03-044fedf30020', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''batas waktu / tenggat'': このレポートの___は今週の金曜日です。', '{"options":["締め切り","お祝い","乗り換え","思い出"],"translation":"Tenggat waktu laporan ini adalah hari Jumat minggu ini.","sentence_template":"このレポートの[blank]は今週の金曜日です。"}'::jsonb, '{"selected":"締め切り"}'::jsonb, NULL, NULL, '締め切り (shimekiri) berarti batas waktu atau deadline pengumpulan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5da6002c-aa37-4c7f-b295-a611214f7ad6', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata perlengkapan keselamatan kerja: 工場に入る前に、必ず___をかぶります。', '{"options":["サングラス","ヘルメット","スリッパ","ネクタイ"],"translation":"Sebelum masuk pabrik, wajib mengenakan helm pengaman.","sentence_template":"工場に入る前に、必ず[blank]をかぶります。"}'::jsonb, '{"selected":"ヘルメット"}'::jsonb, NULL, NULL, 'ヘルメットをかぶります berarti memakai helm (kata kerja untuk penutup kepala adalah かぶる).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8dd25a1a-4cbb-4560-9dd7-f823765a845c', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'listening', 'listening_choice', 'Dengarkan aturan kantor berikut. Apa yang harus dilakukan saat terlambat?', '{"options":[{"id":"opt_1","text":"Langsung pulang ke rumah"},{"id":"opt_2","text":"Menunggu sampai jam istirahat"},{"id":"opt_3","text":"Menghubungi atasan sebelum jam kerja dimulai"},{"id":"opt_4","text":"Mengirim surat ke bagian keuangan"}],"audio_text":"遅刻するときは、必ず開始前に上司へ連絡してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '遅刻するとき (saat terlambat) + 上司へ連絡 (menghubungi atasan).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7bc7520f-b7a5-4fb9-85e6-69ce8eef2316', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di klinik. Apa yang harus dibawa pasien?', '{"options":[{"id":"opt_1","text":"Kartu perpustakaan"},{"id":"opt_2","text":"Buku tabungan bank"},{"id":"opt_3","text":"Kartu pelajar"},{"id":"opt_4","text":"Kartu asuransi kesehatan"}],"audio_text":"病院へ行くときは、健康保険証を忘れないでください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '健康保険証 (kenkou hokenshou) adalah kartu asuransi kesehatan di Jepang.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('28ea1038-6653-495c-982c-703602d80e27', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum bekerja, saya memeriksa kondisi mesin."', '{"romaji":"Sagyou no mae ni, kikai no joutai o kakunin shimasu.","tokens":["状態を","忘れます。","確認します。","作業の前に、","機械の","機械が"],"target_translation":"Sebelum bekerja, saya memeriksa kondisi mesin."}'::jsonb, '["作業の前に、","機械の","状態を","確認します。"]'::jsonb, NULL, NULL, '作業 (sagyou) berarti pekerjaan/operasi lapangan; 状態 (joutai) berarti kondisi.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('da825831-c4b1-4b5f-a851-75eea405eefb', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Aturan keselamatan harus selalu dipatuhi."', '{"romaji":"Anzen ruuru wa kanarazu mamorimasu.","display_text":"安全ルールは必ず守ります。","phonetic_breakdown":["an-zen","ru-u-ru","wa","ka-na-ra-zu","ma-mo-ri-ma-su"]}'::jsonb, '{"expected_transcript":"安全ルールは必ず守ります。"}'::jsonb, NULL, NULL, '必ず (kanarazu) berarti pasti/wajib, dan ルールを守る berarti mematuhi aturan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('154ad5e0-5ab4-40e2-89ca-9a15da066814', '119ea6f5-61a2-4a6c-8571-d37f851a514a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 工場に入るときは、必ずヘルメットを___しなければなりません。', '{"options":["配達","着用","注文","散歩"],"translation":"Saat masuk ke pabrik, wajib mengenakan helm pengaman.","sentence_template":"工場に入るときは、必ずヘルメットを[blank]しなければなりません。"}'::jsonb, '{"selected":"着用"}'::jsonb, NULL, NULL, '着用 (chakuyou) adalah istilah resmi untuk mengenakan perlengkapan keselamatan atau seragam.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('35c40f1e-61b6-4f3e-a965-5184f41e2675', '119ea6f5-61a2-4a6c-8571-d37f851a514a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan aturan kantor berikut. Kapan batas akhir pengumpulan?', '{"options":[{"id":"opt_1","text":"Dokumen harus dikumpulkan paling lambat hari Jumat pukul 5 sore"},{"id":"opt_2","text":"Hari Jumat pukul 5 sore ada rapat evaluasi dokumen"},{"id":"opt_3","text":"Tenggat pengumpulan dokumen diperpanjang sampai Senin"},{"id":"opt_4","text":"Dokumen baru boleh dikumpulkan setelah hari Jumat pukul 5 sore"}],"audio_text":"提出期限は金曜日の午後五時ですので、それまでに提出しなければなりません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '提出期限 (teishutsu kigen) berarti batas waktu pengumpulan; それまでに berarti paling lambat sebelum waktu itu.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ccc3fe1-67ac-48f6-8ed4-83d6e325c17d', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Sambungkan Nomina 雨 (hujan) dengan ので secara tepat: 今日は___ので、屋外の作業は中止です。', '{"options":["雨の","雨い","雨な","雨だ"],"translation":"Karena hari ini hujan, pekerjaan di luar ruangan dibatalkan.","sentence_template":"今日は[blank]ので、屋外の作業は中止です。"}'::jsonb, '{"selected":"雨な"}'::jsonb, NULL, NULL, 'Aturan penting N4: Nomina dan Adjektiva-NA wajib memakai な sebelum ので -> 雨なので (bukan 雨だので).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3761e506-5480-435e-8744-b1ae6c1f9d5d', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Sambungkan Adjektiva-NA 静か (tenang) dengan ので: この図書館は___ので、勉強しやすいです。', '{"options":["静かの","静かだ","静かい","静かな"],"translation":"Karena perpustakaan ini tenang, nyaman untuk belajar.","sentence_template":"この図書館は[blank]ので、勉強しやすいです。"}'::jsonb, '{"selected":"静かな"}'::jsonb, NULL, NULL, 'Adjektiva-NA (静か) membutuhkan な sebelum ので -> 静かなので.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21d4c096-2446-4357-a558-f04d5226a807', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Sambungkan Adjektiva-I (sibuk) dengan ので secara tepat: 今週はとても___ので、週末も出勤します。', '{"options":["忙しい","忙しく","忙しだ","忙しいな"],"translation":"Karena minggu ini sangat sibuk, akhir pekan pun saya masuk kerja.","sentence_template":"今週はとても[blank]ので、週末も出勤します。"}'::jsonb, '{"selected":"忙しい"}'::jsonb, NULL, NULL, 'Adjektiva-I langsung diikuti ので tanpa な -> 忙しいので.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('440ca8ae-e760-4a3d-94be-1ed6bacf4051', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta terlambat, saya terlambat datang ke rapat."', '{"romaji":"Densha ga okureta node, kaigi ni chikoku shimashita.","tokens":["遅刻しました。","電車が","遅れました。","早退しました。","会議に","遅れたので、"],"target_translation":"Karena kereta terlambat, saya terlambat datang ke rapat."}'::jsonb, '["電車が","遅れたので、","会議に","遅刻しました。"]'::jsonb, NULL, NULL, 'Verba bentuk biasa (遅れた) langsung disambungkan dengan ので.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a97b163-5fdc-4b56-8d49-6c972b3bb2e3', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena tempat ini dekat dari stasiun, sangat praktis."', '{"romaji":"Eki kara chikai node, totemo benri desu.","tokens":["近いので、","駅から","遠いです。","便利です。","とても","近いなので、"],"target_translation":"Karena tempat ini dekat dari stasiun, sangat praktis."}'::jsonb, '["駅から","近いので、","とても","便利です。"]'::jsonb, NULL, NULL, '近い adalah Adjektiva-I, jadi langsung 近いので (tanpa な).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('befdc751-eac9-4291-add6-838916f18caa', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena besok ada ujian, malam ini saya harus belajar."', '{"romaji":"Ashita wa shiken ga aru node, konya wa benkyou shinakereba narimasen.","display_text":"明日は試験があるので、今夜は勉強しなければなりません。","phonetic_breakdown":["a-shi-ta","wa","shi-ken","ga","a-ru","no-de","kon-ya","wa","ben-kyo-u","shi-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日は試験があるので、今夜は勉強しなければなりません。"}'::jsonb, NULL, NULL, 'ある (bentuk kamus) + ので menyatakan alasan secara halus dan objektif.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('62c903cb-785a-4104-983b-469f03488096', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: ここは図書館___、静かにしてください。', '{"options":["なので","での","だので","ので"],"translation":"Karena di sini perpustakaan, harap tenang.","sentence_template":"ここは図書館[blank]、静かにしてください。"}'::jsonb, '{"selected":"なので"}'::jsonb, NULL, NULL, 'Untuk kata benda dan kata sifat な, tambahkan な sebelum ので (図書館 + なので).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a91401c-a490-4bf8-bedc-7189d090b01e', '19259446-840c-4bfd-ac51-5591d33f5054', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena besok ada ujian penting, saya pulang lebih awal."', '{"romaji":"Ashita wa daiji na shiken ga aru node, hayaku kaerimasu.","tokens":["明日は","なので、","早く","あるので、","大事な","帰ります。","試験が","を"],"target_translation":"Karena besok ada ujian penting, saya pulang lebih awal."}'::jsonb, '["明日は","大事な","試験が","あるので、","早く","帰ります。"]'::jsonb, NULL, NULL, 'Kata kerja bentuk biasa (ある) langsung diikuti ので.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('88bd77d8-68cc-430a-8ead-46028fa0425d', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Saya membantu adik mengerjakan PR (saya -> orang lain): 私は弟の宿題を手伝って___。', '{"options":["いただきました","もらいました","あげました","くれました"],"translation":"Saya membantu mengerjakan PR adik saya.","sentence_template":"私は弟の宿題を手伝って[blank]。"}'::jsonb, '{"selected":"あげました"}'::jsonb, NULL, NULL, 'Jika pembicara (私は) memberi bantuan kepada orang lain, gunakan ～てあげます.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9d79c70-97c8-4cf1-868d-2c6df7aa435f', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Teman meminjamkan payung kepada saya (orang lain -> saya): 雨が降っていたので、友達が傘を貸して___。', '{"options":["もらいました","あげました","やりました","くれました"],"translation":"Karena hujan turun, teman meminjamkan payung kepada saya.","sentence_template":"雨が降っていたので、友達が傘を貸して[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, 'Jika orang lain (友達が) melakukan kebaikan untuk pembicara, gunakan ～てくれます.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d930cb1a-66af-463b-bec7-d0d984b4d7cd', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Saya menerima bantuan pemeriksaan laporan dari senior (私は ... に): 私は先輩にレポートをチェックして___。', '{"options":["もらいました","あげました","くれました","やりました"],"translation":"Saya dibantu senior memeriksa laporan.","sentence_template":"私は先輩にレポートをチェックして[blank]。"}'::jsonb, '{"selected":"もらいました"}'::jsonb, NULL, NULL, 'Saat subjeknya adalah penerima bantuan (私は) dan pemberinya ditandai に (先輩に), gunakan ～てもらいます.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac94a9d6-1d77-4ca5-9647-26d4939a3ec1', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya mengantar teman ke bandara dengan mobil."', '{"romaji":"Watashi wa tomodachi o kuukou made okutte agemashita.","tokens":["くれました。","もらいました。","あげました。","私は","空港まで","送って","友達を"],"target_translation":"Saya mengantar teman ke bandara dengan mobil."}'::jsonb, '["私は","友達を","空港まで","送って","あげました。"]'::jsonb, NULL, NULL, 'Pembicara memberi bantuan kepada teman -> 送ってあげました.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('468b19d5-e990-41bf-a9bd-cff8dfc90eb9', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Senior membelikan saya kopi hangat."', '{"romaji":"Senpai ga atatakai koohii o katte kuremashita.","tokens":["買って","あげました。","温かいコーヒーを","もらいました。","くれました。","先輩が"],"target_translation":"Senior membelikan saya kopi hangat."}'::jsonb, '["先輩が","温かいコーヒーを","買って","くれました。"]'::jsonb, NULL, NULL, 'Subjek pemberi kebaikan kepada saya adalah 先輩が -> 買ってくれました.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d090f922-0eee-4bf6-bb9e-10db15810c30', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya meminta teman Jepang memperbaiki bahasa Jepang saya."', '{"romaji":"Nihonjin no tomodachi ni Nihongo o naoshite moraimashita.","display_text":"日本人の友達に日本語を直してもらいました。","phonetic_breakdown":["ni-hon-jin","no","to-mo-da-chi","ni","ni-hon-go","o","na-o-shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"日本人の友達に日本語を直してもらいました。"}'::jsonb, NULL, NULL, '直します (memperbaiki/mengoreksi) + てもらいました berarti menerima bantuan koreksi dari teman.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('354f9fef-e736-43fe-877d-f950a209e3bd', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 風邪を引いたとき、ルームメイトがおかゆを作って___。', '{"options":["あげました","やりました","くれました","もらいました"],"translation":"Saat saya terkena flu, teman sekamar membuatkan bubur untuk saya.","sentence_template":"風邪を引いたとき、ルームメイトがおかゆを作って[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, 'Ketika orang lain (subjek が) melakukan kebaikan untuk saya, gunakan ～てくれる.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9671a097-ddc8-4a31-a789-bd9c39179671', '1b9d28b8-37da-4578-a088-aebee5486b04', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya diajari cara menulis laporan oleh senior."', '{"romaji":"Watashi wa senpai ni repooto no kakikata o oshiete moraimashita.","tokens":["書き方を","レポートの","もらいました。","先輩に","教えて","私は","くれました。","が"],"target_translation":"Saya diajari cara menulis laporan oleh senior."}'::jsonb, '["私は","先輩に","レポートの","書き方を","教えて","もらいました。"]'::jsonb, NULL, NULL, 'Dengan subjek 私は dan pemberi bantuan ditandai に, gunakan ～てもらう.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a1e20e1f-3736-4bcc-8512-c22a1f6c6f52', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Pilih bentuk saran positif yang tepat dari 聞きます (bertanya): わからないことは先輩に___ほうがいいですよ。', '{"options":["聞いて","聞きます","聞いた","聞く"],"translation":"Hal yang tidak kamu pahami sebaiknya ditanyakan kepada senior ya.","sentence_template":"わからないことは先輩に[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"聞いた"}'::jsonb, NULL, NULL, '聞きます -> Bentuk TA: 聞いた + ほうがいいですよ.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('844833f1-6eec-42d6-9d66-ee5d35d0f6a0', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Pilih saran larangan yang tepat untuk merokok di dalam ruangan: 健康のために、たばこは___ほうがいいです。', '{"options":["吸った","吸います","吸って","吸わない"],"translation":"Demi kesehatan, sebaiknya tidak merokok.","sentence_template":"健康のために、たばこは[blank]ほうがいいです。"}'::jsonb, '{"selected":"吸わない"}'::jsonb, NULL, NULL, '吸います (menghisap rokok) -> Bentuk NAI: 吸わない + ほうがいいです.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8d668d4-c497-45f0-8646-e2708e06f0c8', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Apa saran teman mengenai reservasi restoran?', '{"options":[{"id":"opt_1","text":"Datang langsung tanpa reservasi"},{"id":"opt_2","text":"Pergi pada tengah malam saja"},{"id":"opt_3","text":"Mencari restoran lain yang lebih mahal"},{"id":"opt_4","text":"Membuat reservasi lebih dulu karena sangat ramai saat akhir pekan"}],"audio_text":"そのレストランは週末とても人気がありますから、先に予約したほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '先に予約したほうがいい menyarankan memesan tempat lebih dulu.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f635e704-2ef9-438e-ada8-9ae08991b542', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran perawat di puskesmas. Apa yang harus dihindari pasien hari ini?', '{"options":[{"id":"opt_1","text":"Menghindari berendam di bak mandi dan cukup mandi pancuran saja"},{"id":"opt_2","text":"Tidak boleh minum air putih sepanjang hari"},{"id":"opt_3","text":"Harus tidur tanpa selimut"},{"id":"opt_4","text":"Tidak boleh makan nasi selama dua hari"}],"audio_text":"予防接種のあとは、今日はお風呂に入らないで、シャワーだけにしたほうがいいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お風呂に入らないで、シャワーだけにしたほうがいい menyarankan hanya mandi shower setelah vaksinasi.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e480621-483e-4b0e-981f-d35aca484185', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya memeriksa ramalan cuaca sebelum bepergian."', '{"romaji":"Dekakeru mae ni, tenkiyohou o mita hou ga ii desu.","tokens":["出かける前に、","天気予報を","見て","見る","見た","ほうがいいです。"],"target_translation":"Sebaiknya memeriksa ramalan cuaca sebelum bepergian."}'::jsonb, '["出かける前に、","天気予報を","見た","ほうがいいです。"]'::jsonb, NULL, NULL, '天気予報 (tenkiyohou) adalah ramalan cuaca; 見ます -> 見た + ほうがいいです.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d40ea846-3e9b-44e2-bb2e-31f2dd090d54', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika tenggorokan sakit, sebaiknya banyak minum minuman hangat."', '{"romaji":"Nodo ga itai nara, atatakai nomimono o nonda hou ga ii desu yo.","display_text":"のどが痛いなら、温かい飲み物を飲んだほうがいいですよ。","phonetic_breakdown":["no-do","ga","i-ta-i","na-ra","a-ta-ta-ka-i","no-mi-mo-no","o","non-da","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"のどが痛いなら、温かい飲み物を飲んだほうがいいですよ。"}'::jsonb, NULL, NULL, 'Kombinasi 痛いなら + 飲んだほうがいいですよ terdengar sangat alami saat memberi nasihat kepada rekan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a84b4b6-376a-4e49-b518-d64ed47855d8', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: その靴は滑りやすいので、雪の日は履か___ほうがいいですよ。', '{"options":["ない","て","なかった","る"],"translation":"Karena sepatu itu mudah licin, sebaiknya jangan memakainya di hari bersalju.","sentence_template":"その靴は滑りやすいので、雪の日は履か[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"ない"}'::jsonb, NULL, NULL, '履く -> bentuk ない adalah 履かない, diikuti ほうがいい.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('282868ac-6dd6-4114-a52b-3cfa2c268fc3', '23906bd8-e71b-4a0c-9483-5f027ba1d0e0', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dokumen penting sebaiknya difotokopi terlebih dahulu sebagai cadangan."', '{"romaji":"Taisetsu na shorui wa kopii o totte oita hou ga ii desu.","display_text":"大切な書類はコピーを取っておいたほうがいいです。","phonetic_breakdown":["tai-se-tsu-na","sho-ru-i-wa","ko-pii-o","tot-te-o-i-ta","hou-ga","ii-de-su"]}'::jsonb, '{"expected_transcript":"大切な書類はコピーを取っておいたほうがいいです。"}'::jsonb, NULL, NULL, 'Gabungan ～ておく dan ～たほうがいい memberi saran antisipatif yang sangat alami.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('431d3d87-a091-4a02-8bf0-37772486284b', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan permintaan di ruang kantor ini. Apa yang diinginkan pembicara?', '{"options":[{"id":"opt_1","text":"Meminta jendela ruang rapat dibuka"},{"id":"opt_2","text":"Meminta AC dimatikan sepenuhnya"},{"id":"opt_3","text":"Meminta suhu AC dinaikkan sedikit karena terasa dingin"},{"id":"opt_4","text":"Meminta suhu AC diturunkan karena gerah"}],"audio_text":"すみません、エアコンの温度を少し上げていただけませんか。ちょっと寒くて。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '温度を上げる berarti menaikkan suhu agar ruangan lebih hangat.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('13ebd418-8a47-40a2-900b-226b6fcf2980', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saat Anda memiliki waktu luang, maukah Anda membaca laporan ini?"', '{"romaji":"Ojikan no aru toki ni, repooto o yonde itadakemasen ka.","display_text":"お時間のあるときに、レポートを読んでいただけませんか。","phonetic_breakdown":["o-ji-kan-no","a-ru-to-ki-ni","re-poo-to-o","yon-de","i-ta-da-ke-ma-sen-ka"]}'::jsonb, '{"expected_transcript":"お時間のあるときに、レポートを読んでいただけませんか。"}'::jsonb, NULL, NULL, 'お時間のあるときに adalah ungkapan halus yang menunjukkan perhatian terhadap kesibukan lawan bicara.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef91ef5b-8064-493d-8f47-fe6374dbef09', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maukah Anda menunjukkan arah ke stasiun dengan peta?"', '{"romaji":"Eki made no ikikata o chizu de oshiete itadakemasen ka.","tokens":["教えます。","いただけませんか。","駅までの","行き方を","教えて","と","地図で"],"target_translation":"Maukah Anda menunjukkan arah ke stasiun dengan peta?"}'::jsonb, '["駅までの","行き方を","地図で","教えて","いただけませんか。"]'::jsonb, NULL, NULL, 'Partikel で menandai alat (peta), sedangkan 教えていただけませんか menyampaikan permohonan sopan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9e654c9d-42c4-4e89-9126-10c741ca2e90', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 写真を撮りたいので、シャッターを___いただけませんか。', '{"options":["押す","押した","押さ","押して"],"translation":"Karena saya ingin berfoto, maukah Anda menekan tombol kameranya?","sentence_template":"写真を撮りたいので、シャッターを[blank]いただけませんか。"}'::jsonb, '{"selected":"押して"}'::jsonb, NULL, NULL, '押す (osu) berubah menjadi bentuk て: 押して.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2002ee2-7e1f-4343-9d87-897cfe074514', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan imbauan staf kereta berikut. Apa yang diminta?', '{"options":[{"id":"opt_1","text":"Meminta penumpang berpindah gerbong"},{"id":"opt_2","text":"Memberitahukan barang yang tertinggal di rak"},{"id":"opt_3","text":"Meminta penumpang menyerahkan karcis kereta"},{"id":"opt_4","text":"Meminta penumpang meletakkan barang bawaan di rak atas"}],"audio_text":"申し訳ございませんが、お荷物を棚の上に乗せていただけませんか。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '棚の上に乗せる berarti menaikkan atau meletakkan barang di atas rak.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c330373-f8b8-4a93-b2f0-9f3056d447ac', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mohon maaf, bersediakah Anda menunggu di sini?"', '{"romaji":"Osoreirimasu ga, kochira de omachi itadakemasen ka.","display_text":"恐れ入りますが、こちらでお待ちいただけませんか。","phonetic_breakdown":["o-so-re-i-ri-ma-su-ga","ko-chi-ra-de","o-ma-chi","i-ta-da-ke-ma-sen-ka"]}'::jsonb, '{"expected_transcript":"恐れ入りますが、こちらでお待ちいただけませんか。"}'::jsonb, NULL, NULL, 'お待ちいただけませんか adalah bentuk sopan dari 待っていただけませんか yang sering dipakai staf pelayanan.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('65ea3208-afa7-412a-b4c1-b72d7b5694f6', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maukah Anda membagikan notulen rapat melalui email?"', '{"romaji":"Kaigi no gijiroku o meeru de kyouyuu shite itadakemasen ka.","tokens":["メールで","共有して","共有します。","いただけませんか。","議事録を","に","会議の"],"target_translation":"Maukah Anda membagikan notulen rapat melalui email?"}'::jsonb, '["会議の","議事録を","メールで","共有して","いただけませんか。"]'::jsonb, NULL, NULL, '議事録 (gijiroku) adalah notulen rapat; 共有する berarti membagikan informasi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67547c29-b4d6-4696-a4c4-6d4d450a5528', '25412363-1d94-4407-abf5-0efc18d2c8ab', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 次の電車まで時間がないので、急いで___いただけませんか。', '{"options":["調べて","調べた","調べる","調べ"],"translation":"Karena tidak banyak waktu sebelum kereta berikutnya, maukah Anda memeriksanya dengan cepat?","sentence_template":"次の電車まで時間がないので、急いで[blank]いただけませんか。"}'::jsonb, '{"selected":"調べて"}'::jsonb, NULL, NULL, '調べる (shiraberu) adalah kata kerja kelompok 2 sehingga bentuk て-nya adalah 調べて.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b87c442-7ce8-489d-9ca8-f11c2116d326', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan ucapan staf hotel ini. Apa yang ia tawarkan kepada tamu?', '{"options":[{"id":"opt_1","text":"Membawakan barang bawaan tamu sampai ke kamar"},{"id":"opt_2","text":"Memanggilkan taksi ke bandara"},{"id":"opt_3","text":"Mengganti kamar tamu dengan yang lebih besar"},{"id":"opt_4","text":"Menyimpan barang tamu di ruang bawah tanah"}],"audio_text":"重そうですね。お部屋までお荷物をお運びいたします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お運びいたします (Kenjougo dari 運びます) berarti biar saya bawakan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a396e78-fb01-4cd6-bb53-9b7e644d0425', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan telepon bisnis ini. Apa yang akan dilakukan staf penerima telepon?', '{"options":[{"id":"opt_1","text":"Menyambungkan langsung ke Pak Yamada sekarang"},{"id":"opt_2","text":"Menghubungi balik begitu Pak Yamada kembali ke mejanya"},{"id":"opt_3","text":"Meminta penelepon datang ke kantor besok"},{"id":"opt_4","text":"Memberikan nomor ponsel pribadi Pak Yamada"}],"audio_text":"申し訳ございません、山田は席を外しております。戻りましたら、こちらからご連絡いたします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '席を外しております (sedang tidak di tempat) + ご連絡いたします (kami akan menghubungi balik).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('50d89812-adae-4db8-af86-795fdd52531c', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan perkenalan diri saat wawancara. Bagaimana sikap pembicara?', '{"options":[{"id":"opt_1","text":"Meminta jadwal wawancara diundur"},{"id":"opt_2","text":"Menolak tawaran pekerjaan secara halus"},{"id":"opt_3","text":"Mengucapkan terima kasih atas waktu pewawancara dan berjanji berusaha maksimal"},{"id":"opt_4","text":"Menanyakan besaran gaji lembur"}],"audio_text":"本日はお忙しい中、お時間をいただきありがとうございます。精一杯頑張ります。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'お時間をいただきありがとうございます adalah ungkapan Kenjougo (いただく) yang sangat sopan.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f2a682a-147c-4a35-a1ca-64f760a7a2e5', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Pilih bentuk Kenjougo dari 見ます (melihat / memeriksa): お送りいただいたメールを___。', '{"options":["ご覧になりました","召し上がりました","おっしゃいました","拝見しました"],"translation":"Saya sudah membaca email yang Anda kirimkan.","sentence_template":"お送りいただいたメールを[blank]。"}'::jsonb, '{"selected":"拝見しました"}'::jsonb, NULL, NULL, '拝見します (haiken shimasu) adalah Kenjougo dari 見ます saat pembicara melihat/membaca sesuatu dari pihak yang dihormati.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a11584a-c3fb-46d6-aea5-2e42dd7f6383', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Pilih bentuk Kenjougo dari 食べます / 飲みます (makan / minum): おいしいお茶を___。ありがとうございます。', '{"options":["いただきました","なさいました","召し上がりました","いらっしゃいました"],"translation":"Saya telah menikmati teh yang lezat ini. Terima kasih banyak.","sentence_template":"おいしいお茶を[blank]。ありがとうございます。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, NULL, NULL, 'いただきます adalah Kenjougo untuk menerima/makan/minum dari pihak lain. 召し上がります adalah Sonkeigo.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('486c37df-6eb5-4699-b6cb-39ab8fb5be2c', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi pola Kenjougo ご + [Nomina verba] + いたします (menjelaskan): これから本日の予定をご___いたします。', '{"options":["歩き","説明","食べ","飲み"],"translation":"Sekarang saya akan menjelaskan jadwal hari ini.","sentence_template":"これから本日の予定をご[blank]いたします。"}'::jsonb, '{"selected":"説明"}'::jsonb, NULL, NULL, 'Untuk kata kerja Grup 3 (Kango + する) seperti 説明する, bentuk Kenjougo-nya adalah ご説明いたします.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8fd24a3f-0980-45d3-9f45-519ad67e9c73', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan janji bisnis berikut. Apa yang akan dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara meminta lawan bicara mengirimkan materi lewat email"},{"id":"opt_2","text":"Persiapan materi masih membutuhkan waktu sebulan"},{"id":"opt_3","text":"Materi sudah dikirimkan melalui pos kemarin"},{"id":"opt_4","text":"Begitu materi siap, pembicara akan segera mengirimkannya lewat email dengan sangat sopan"}],"audio_text":"資料の準備が整い次第、すぐメールでお送りいたします。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'お送りいたします adalah Kenjougo yang lebih formal dari お送りします.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('97d6784e-810a-4911-ad05-d12453df6ec5', '317cb772-2e5c-4dee-8c7c-dfe0d3a1371b', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 社長、先ほどいただいたメールを今___しました。', '{"options":["ご存じ","お休み","ご覧","拝見"],"translation":"Pak Direktur, saya baru saja membaca email yang Anda kirimkan tadi.","sentence_template":"社長、先ほどいただいたメールを今[blank]しました。"}'::jsonb, '{"selected":"拝見"}'::jsonb, NULL, NULL, '拝見する (haiken suru) adalah Kenjougo dari 見る (melihat/membaca).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7771d6d3-8d77-47b2-b247-a3a7abfb8985', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Ubah Adjektiva-I 安い (murah) ke bentuk ～たら: このパソコンがもっと___、買いたいです。', '{"options":["安かったら","安いったら","安くだったら","安いたら"],"translation":"Kalau komputer ini lebih murah, saya ingin membelinya.","sentence_template":"このパソコンがもっと[blank]、買いたいです。"}'::jsonb, '{"selected":"安かったら"}'::jsonb, NULL, NULL, 'Adjektiva-I diubah ke bentuk lampau biasa (安かった) lalu ditambah ら -> 安かったら.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('480cf912-ec13-4571-860f-850df042cd15', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Ubah Adjektiva-NA 暇 (senggang) ke bentuk ～たら: 明日___、映画を見に行きませんか。', '{"options":["暇ならたら","暇だったら","暇いったら","暇かったら"],"translation":"Kalau besok senggang, maukah pergi menonton film?","sentence_template":"明日[blank]、映画を見に行きませんか。"}'::jsonb, '{"selected":"暇だったら"}'::jsonb, NULL, NULL, 'Nomina dan Adjektiva-NA memakai だった + ら -> 暇だったら.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('19162db0-aa17-4711-8433-017a229d77f1', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Ubah bentuk negatif わからない (tidak tahu) ke ～たら: やり方が___、いつでも聞いてくださいね。', '{"options":["わかりませんでしたら","わからなくてら","わからなかったら","わからないたら"],"translation":"Kalau tidak tahu caranya, silakan bertanya kapan saja ya.","sentence_template":"やり方が[blank]、いつでも聞いてくださいね。"}'::jsonb, '{"selected":"わからなかったら"}'::jsonb, NULL, NULL, 'Bentuk NAI (わからない) -> lampau negatif (わからなかった) + ら = わからなかったら.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('837247d5-a1f8-40d1-96fa-2b8e95abb7e3', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau besok hujan, pertandingan akan dibatalkan."', '{"romaji":"Ashita ame dattara, shiai wa chuushi ni narimasu.","tokens":["雨かったら、","始まります。","中止になります。","雨だったら、","明日","試合は"],"target_translation":"Kalau besok hujan, pertandingan akan dibatalkan."}'::jsonb, '["明日","雨だったら、","試合は","中止になります。"]'::jsonb, NULL, NULL, '雨 (Nomina) + だったら membentuk pengandaian ''kalau hujan''.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aefd804d-23ba-46b0-9b36-7d9ab4ed063d', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah pekerjaan ini selesai, mari kita istirahat."', '{"romaji":"Kono shigoto ga owattara, kyuukei shimashou.","tokens":["始まったら、","終わります、","終わったら、","この仕事が","休憩しましょう。"],"target_translation":"Setelah pekerjaan ini selesai, mari kita istirahat."}'::jsonb, '["この仕事が","終わったら、","休憩しましょう。"]'::jsonb, NULL, NULL, '終わります -> 終わった + ら = 終わったら menyatakan ''setelah selesai''.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('804de9c7-659b-4fbd-baef-020bd5253c70', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah sampai di rumah, kirimkan pesan ya."', '{"romaji":"Ie ni tsuitara, messeeji o okutte kudasai ne.","display_text":"家に着いたら、メッセージを送ってくださいね。","phonetic_breakdown":["i-e","ni","tsu-i-ta-ra","mes-se-e-ji","o","o-kut-te","ku-da-sa-i","ne"]}'::jsonb, '{"expected_transcript":"家に着いたら、メッセージを送ってくださいね。"}'::jsonb, NULL, NULL, '着いたら sangat umum dipakai untuk memastikan teman atau keluarga sudah tiba dengan selamat.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b4e5c14-3cda-4444-8cfd-7d8440513067', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 仕事が___、一緒に飲みに行きませんか。', '{"options":["終わったら","終わらたら","終わるたら","終わてたら"],"translation":"Setelah pekerjaan selesai, maukah pergi minum bersama?","sentence_template":"仕事が[blank]、一緒に飲みに行きませんか。"}'::jsonb, '{"selected":"終わったら"}'::jsonb, NULL, NULL, 'Bentuk たら dibentuk dari bentuk lampau た + ら (終わる -> 終わった -> 終わったら).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('737659ae-4b90-4896-96ed-d4260add81a3', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah sampai di stasiun, tolong kirim pesan kepada saya."', '{"romaji":"Eki ni tsuitara, watashi ni messeeji o okutte kudasai.","tokens":["私に","着くたら、","メッセージを","送ってください。","着いたら、","駅に","が"],"target_translation":"Kalau sudah sampai di stasiun, tolong kirim pesan kepada saya."}'::jsonb, '["駅に","着いたら、","私に","メッセージを","送ってください。"]'::jsonb, NULL, NULL, '着く -> 着いた -> 着いたら menyatakan urutan waktu ''begitu sampai''.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5836849-1266-4ea6-8db8-f3935222d74f', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 新しいスマートフォンなら、暗い場所でもきれいな写真が___。', '{"options":["撮らせます","撮れます","撮りました","撮ります"],"translation":"Kalau memakai ponsel baru, di tempat gelap pun bisa mengambil foto yang bagus.","sentence_template":"新しいスマートフォンなら、暗い場所でもきれいな写真が[blank]。"}'::jsonb, '{"selected":"撮れます"}'::jsonb, NULL, NULL, '撮る (kelompok 1) -> 撮れる (bisa memotret).', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3195100d-c576-40b3-b9a4-28c848add86d', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このジムは二十四時間営業なので、仕事の後でも___。', '{"options":["通えます","通います","通いました","通わせます"],"translation":"Karena gym ini buka 24 jam, sepulang kerja pun bisa rutin datang.","sentence_template":"このジムは二十四時間営業なので、仕事の後でも[blank]。"}'::jsonb, '{"selected":"通えます"}'::jsonb, NULL, NULL, '通う (kayou, rutin datang) -> 通える (bisa rutin datang).', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cacab7da-e090-45f7-92a2-8a7b9d967826', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan rekomendasi rekan kerja berikut. Apa manfaat perangkat lunak tersebut?', '{"options":[{"id":"opt_1","text":"Email bisnis tidak boleh dibaca menggunakan komputer"},{"id":"opt_2","text":"Memahami email bisnis membutuhkan waktu berjam-jam"},{"id":"opt_3","text":"Perangkat lunak penerjemah ini membantu memahami email bisnis panjang dalam waktu singkat"},{"id":"opt_4","text":"Perangkat lunak ini hanya cocok untuk kalimat sangat pendek"}],"audio_text":"この翻訳ソフトを使えば、長いビジネスメールでも短時間で理解できますよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '理解できます adalah bentuk potensial dari 理解する (bisa memahami).', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73bc8b35-c699-441a-99e3-d3a55519bd35', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Tiket pesawat bisa dipesan secara daring kapan saja."', '{"romaji":"Onrain de itsudemo koukuuken ga yoyaku dekimasu.","tokens":["を","予約できます。","予約します。","オンラインで","いつでも","航空券が"],"target_translation":"Tiket pesawat bisa dipesan secara daring kapan saja."}'::jsonb, '["オンラインで","いつでも","航空券が","予約できます。"]'::jsonb, NULL, NULL, '予約する -> 予約できる menyatakan layanan yang dapat dilakukan.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a26a7c5-92c1-42c9-a57b-5d50f958ac15', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 納豆は最初苦手でしたが、今ではおいしく___。', '{"options":["食べさせます","食べてあります","食べられます","食べます"],"translation":"Awalnya saya tidak suka natto, tapi sekarang bisa memakannya dengan nikmat.","sentence_template":"納豆は最初苦手でしたが、今ではおいしく[blank]。"}'::jsonb, '{"selected":"食べられます"}'::jsonb, NULL, NULL, '食べる -> 食べられる menunjukkan kemampuan yang sekarang sudah dimiliki.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15dd8051-a7f9-4a34-ae6c-b0e8fcaf98b7', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan tiket ini, Anda bisa naik bus dalam kota berkali-kali."', '{"romaji":"Kono kippu de shinai no basu ni nankai demo noremasu.","display_text":"この切符で市内のバスに何回でも乗れます。","phonetic_breakdown":["ko-no","kip-pu-de","shi-nai-no","ba-su-ni","nan-kai-de-mo","no-re-ma-su"]}'::jsonb, '{"expected_transcript":"この切符で市内のバスに何回でも乗れます。"}'::jsonb, NULL, NULL, '乗る -> 乗れる (bisa naik kendaraan).', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e2cb41aa-7415-40e8-9778-6941da2d96a6', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan dialog singkat berikut. Apakah lawan bicara bisa hadir di pesta?', '{"options":[{"id":"opt_1","text":"Pesta besok dimulai pukul 7 pagi"},{"id":"opt_2","text":"Lawan bicara tidak bisa datang karena harus lembur sampai malam"},{"id":"opt_3","text":"Lawan bicara akan datang sebelum jam kerja selesai"},{"id":"opt_4","text":"Lawan bicara bisa datang ke pesta besok sekitar pukul 7 setelah selesai kerja"}],"audio_text":"明日のパーティーは仕事が終わってからでも来られますか。ええ、七時ごろなら大丈夫です。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '来られます (koraremasu) adalah bentuk potensial dari 来る (bisa datang).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fbb24869-8579-4e2e-9504-addff9c183e8', '33f9dc08-5086-4162-80ea-5322cfccd842', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun tanpa kamus, saya bisa membaca koran ini."', '{"romaji":"Jisho ga nakutemo kono shinbun ga yomemasu.","tokens":["なくても","この新聞が","読めます。","辞書が","へ","読みます。"],"target_translation":"Meskipun tanpa kamus, saya bisa membaca koran ini."}'::jsonb, '["辞書が","なくても","この新聞が","読めます。"]'::jsonb, NULL, NULL, '読む -> 読める (bisa membaca), dipadukan dengan が.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8cbe5bb3-e6c8-47f1-a926-29b6488beb20', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Ubah 話します (berbicara, Grup 1) ke bentuk potensial: 弟は日本語が少し___。', '{"options":["話せます","話します","話せります","話しられます"],"translation":"Adik laki-laki saya bisa berbicara bahasa Jepang sedikit.","sentence_template":"弟は日本語が少し[blank]。"}'::jsonb, '{"selected":"話せます"}'::jsonb, NULL, NULL, 'Verba Grup 1 mengubah bunyi vokal ''i'' sebelum ます menjadi ''e'': 話します (hanashimasu) -> 話せます (hanasemasu).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9239df90-ce4d-40b8-980f-8b807b0cade1', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Ubah 食べます (makan, Grup 2) ke bentuk potensial: 私は辛い料理も___。', '{"options":["食べます","食べられます","食べえます","食べれます"],"translation":"Saya juga bisa makan masakan pedas.","sentence_template":"私は辛い料理も[blank]。"}'::jsonb, '{"selected":"食べられます"}'::jsonb, NULL, NULL, 'Verba Grup 2 baku menambahkan られます pada akar kata: 食べます -> 食べられます.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff092d43-c51f-440e-bacb-6b604f1c50c5', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Pilih partikel objek yang paling tepat untuk bentuk potensial: 漢字___三百字ぐらい読めます。', '{"options":["で","に","が","へ"],"translation":"Saya bisa membaca sekitar tiga ratus huruf kanji.","sentence_template":"漢字[blank]三百字ぐらい読めます。"}'::jsonb, '{"selected":"が"}'::jsonb, NULL, NULL, 'Objek dari kata kerja bentuk potensial umumnya ditandai dengan partikel が (漢字が読めます).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c086c0d9-d80d-4f99-b2a5-2de2b5329ad0', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa menulis email dalam bahasa Jepang."', '{"romaji":"Nihongo de meeru ga kakemasu.","tokens":["書けます。","メールが","書きます。","メールを","日本語で"],"target_translation":"Saya bisa menulis email dalam bahasa Jepang."}'::jsonb, '["日本語で","メールが","書けます。"]'::jsonb, NULL, NULL, '書きます (Grup 1) -> 書けます (bisa menulis), dengan objek ditandai が.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('71cd1586-e8d2-4ef6-8405-56c1d2c0a77c', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Anda bisa datang ke pesta besok?"', '{"romaji":"Ashita no paatii ni koraremasu ka.","tokens":["パーティーに","明日の","来られますか。","行きますか。","来ますか。"],"target_translation":"Apakah Anda bisa datang ke pesta besok?"}'::jsonb, '["明日の","パーティーに","来られますか。"]'::jsonb, NULL, NULL, '来ます (Grup 3) memiliki bentuk potensial tidak beraturan: 来られます (koraremasu).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b882b9b6-3b54-44e2-8f19-97b79dede5a5', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di sini tidak bisa membayar dengan uang tunai."', '{"romaji":"Koko de wa genkin de haraemasen.","display_text":"ここでは現金で払えません。","phonetic_breakdown":["ko-ko","de","wa","gen-kin","de","ha-ra-e-ma-sen"]}'::jsonb, '{"expected_transcript":"ここでは現金で払えません。"}'::jsonb, NULL, NULL, '払います -> 払えます (bisa bayar) -> 払えません (tidak bisa bayar).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8da4386c-8be5-4f5d-b49d-3062dc69f955', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 毎日練習したので、ひらがなもカタカナも全部___ようになりました。', '{"options":["書かない","書いた","書く","書ける"],"translation":"Karena berlatih setiap hari, saya jadi bisa menulis semua hiragana dan katakana.","sentence_template":"毎日練習したので、ひらがなもカタカナも全部[blank]ようになりました。"}'::jsonb, '{"selected":"書ける"}'::jsonb, NULL, NULL, '書く (kelompok 1) -> bentuk potensialnya 書ける (bisa menulis).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c56570a4-e2d2-4601-93d2-6d57b787ccd7', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan aplikasi ini, perpindahan kereta bisa dicari."', '{"romaji":"Kono apuri de densha no norikae ga shiraberaremasu.","tokens":["アプリで","この","調べられます。","を","電車の","乗り換えが","調べます。"],"target_translation":"Dengan aplikasi ini, perpindahan kereta bisa dicari."}'::jsonb, '["この","アプリで","電車の","乗り換えが","調べられます。"]'::jsonb, NULL, NULL, '調べる (kelompok 2) -> 調べられる; objek bentuk potensial umumnya memakai partikel が.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fe368dac-f23a-47c1-930d-a1a3474a80c6', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan pertanyaan pejalan kaki berikut. Apa yang sedang dicari?', '{"options":[{"id":"opt_1","text":"Menanyakan apakah ada tempat parkir sepeda di sekitar sini"},{"id":"opt_2","text":"Melaporkan sepeda yang hilang di sekitar stasiun"},{"id":"opt_3","text":"Menanyakan toko yang menjual sepeda baru"},{"id":"opt_4","text":"Menanyakan harga sewa sepeda per jam"}],"audio_text":"すみません、この近くに自転車を止められるところはありますか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '止められるところ berarti tempat yang bisa dipakai untuk memarkirkan sepeda.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('883f6353-1aa9-446d-8e12-63eb032eaad5', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Anda bisa memperbaiki komputer sendiri?"', '{"romaji":"Pasokon no shuuri wa jibun de dekimasu ka.","display_text":"パソコンの修理は自分でできますか。","phonetic_breakdown":["pa-so-kon-no","shuu-ri-wa","ji-bun-de","de-ki-ma-su-ka"]}'::jsonb, '{"expected_transcript":"パソコンの修理は自分でできますか。"}'::jsonb, NULL, NULL, '自分でできますか menanyakan kemampuan melakukan sesuatu secara mandiri.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f6fc6136-450a-4102-bf24-b6c927d6adf5', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Di toko ini bisa membeli ikan yang segar."', '{"romaji":"Kono omise de wa shinsen na sakana ga kaemasu.","tokens":["お店では","この","買います。","買えます。","を","新鮮な","魚が"],"target_translation":"Di toko ini bisa membeli ikan yang segar."}'::jsonb, '["この","お店では","新鮮な","魚が","買えます。"]'::jsonb, NULL, NULL, '買う -> 買える (bisa membeli).', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a8e97312-a162-44cd-b3f7-9b7254223e33', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 風邪が治ったので、明日からまた___。', '{"options":["泳ぎます","泳ぎました","泳げます","泳がせます"],"translation":"Karena flu sudah sembuh, mulai besok saya bisa berenang lagi.","sentence_template":"風邪が治ったので、明日からまた[blank]。"}'::jsonb, '{"selected":"泳げます"}'::jsonb, NULL, NULL, '泳ぐ (oyogu) -> 泳げる (bisa berenang).', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('66cca130-afa9-4cee-af05-7b83e807da57', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan penjelasan fasilitas kantor berikut. Berapa kapasitas ruang rapatnya?', '{"options":[{"id":"opt_1","text":"Hanya 30 orang yang boleh berdiri di ruang rapat"},{"id":"opt_2","text":"Ruang rapat ini dapat menampung hingga 30 orang sehingga semua peserta bisa duduk"},{"id":"opt_3","text":"Ruang rapat ini terlalu kecil untuk 30 orang"},{"id":"opt_4","text":"Ruang rapat sedang direnovasi minggu ini"}],"audio_text":"この会議室は最大三十人まで入れますので、全員座れますよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '入れます (hairemasu, bisa masuk) dan 座れます (suwaremasu, bisa duduk) adalah bentuk potensial.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f30a345e-6ff5-46af-9a9d-9fb8de3228bf', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya senang karena akhir pekan bisa beristirahat dengan santai."', '{"romaji":"Shuumatsu wa yukkuri yasumeru node ureshii desu.","display_text":"週末はゆっくり休めるのでうれしいです。","phonetic_breakdown":["shuu-ma-tsu-wa","yuk-ku-ri","ya-su-me-ru-no-de","u-re-shii-de-su"]}'::jsonb, '{"expected_transcript":"週末はゆっくり休めるのでうれしいです。"}'::jsonb, NULL, NULL, '休む -> 休める (bisa beristirahat).', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f8bf58af-f19a-4c9c-be8a-4f476d8d4096', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Minuman di mesin penjual otomatis bisa dibeli dengan uang elektronik."', '{"romaji":"Denshi manee de jidou hanbaiki no nomimono ga kaemasu.","tokens":["買います。","買えます。","へ","電子マネーで","飲み物が","自動販売機の"],"target_translation":"Minuman di mesin penjual otomatis bisa dibeli dengan uang elektronik."}'::jsonb, '["電子マネーで","自動販売機の","飲み物が","買えます。"]'::jsonb, NULL, NULL, 'Partikel で menandai alat pembayaran, が menandai objek bentuk potensial 買えます.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae7e8bbc-01d7-4ccd-a2b8-5761ea036afc', '36dd2d59-eee2-48fb-9c9a-12d634da9be9', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 漢字は難しいですが、少しずつ___ようになってきました。', '{"options":["覚えられる","覚えさせる","覚えた","覚える"],"translation":"Kanji memang sulit, tetapi perlahan-lahan saya mulai bisa menghafalnya.","sentence_template":"漢字は難しいですが、少しずつ[blank]ようになってきました。"}'::jsonb, '{"selected":"覚えられる"}'::jsonb, NULL, NULL, '覚える (kelompok 2) -> 覚えられる (bisa menghafal).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b249ac4-1fe0-4fa9-b5f4-4d674d144c39', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan rencana kerja berikut. Mengapa serah terima harus selesai sore ini?', '{"options":[{"id":"opt_1","text":"Serah terima pekerjaan baru akan dilakukan besok"},{"id":"opt_2","text":"Pembicara baru saja pulang dari dinas luar kota"},{"id":"opt_3","text":"Karena mulai besok dinas luar kota, ingin menyelesaikan serah terima pekerjaan sebelum sore ini"},{"id":"opt_4","text":"Dinas luar kota dimulai sore ini"}],"audio_text":"明日から出張なので、今日の午後までに引き継ぎを終わらせたいです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '出張 (kata benda) + なので menyatakan alasan jadwal yang padat.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8597329a-74d7-4b08-83d6-a157ada09c8d', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ini pertama kalinya bagi saya, bisakah Anda mengajari caranya?"', '{"romaji":"Hajimete na node, yarikata o oshiete itadakemasu ka.","display_text":"初めてなので、やり方を教えていただけますか。","phonetic_breakdown":["ha-ji-me-te-na-no-de","ya-ri-ka-ta-o","o-shi-e-te","i-ta-da-ke-ma-su-ka"]}'::jsonb, '{"expected_transcript":"初めてなので、やり方を教えていただけますか。"}'::jsonb, NULL, NULL, '初めて (kata benda) + なので sangat sopan saat meminta bimbingan.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('35c9d276-e555-4792-acb4-6b4d0d1e7939', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena di sini area bebas rokok, tidak boleh merokok."', '{"romaji":"Koko wa kinen na node, tabako o suemasen.","tokens":["タバコを","吸えません。","禁煙ので、","禁煙","なので、","を","ここは"],"target_translation":"Karena di sini area bebas rokok, tidak boleh merokok."}'::jsonb, '["ここは","禁煙","なので、","タバコを","吸えません。"]'::jsonb, NULL, NULL, '禁煙 (kata benda) memerlukan な sebelum ので -> 禁煙なので.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cedeb7ff-b950-4c84-b17b-443ea2e39f8f', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 財布を家に忘れて___ので、お金を貸してもらえませんか。', '{"options":["しまっただ","しまうな","しまったな","しまった"],"translation":"Karena saya lupa membawa dompet dari rumah, maukah Anda meminjamkan uang?","sentence_template":"財布を家に忘れて[blank]ので、お金を貸してもらえませんか。"}'::jsonb, '{"selected":"しまった"}'::jsonb, NULL, NULL, '忘れてしまった (bentuk lampau biasa) langsung disambung ので.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('219ed134-3129-4be5-ae42-beb94ea450c5', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan informasi singkat berikut. Mengapa loket bank tutup?', '{"options":[{"id":"opt_1","text":"Loket bank buka lebih lama di hari Minggu"},{"id":"opt_2","text":"Bank tutup karena sedang libur tahun baru"},{"id":"opt_3","text":"Pembicara sedang mengantre di loket bank hari ini"},{"id":"opt_4","text":"Loket bank tutup hari ini karena hari Minggu"}],"audio_text":"今日は日曜日なので、銀行の窓口は閉まっていますよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '日曜日 (kata benda) + なので menjelaskan alasan operasional bank.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7733077f-a90b-4981-a5a1-f1dd2fdffb81', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena waktunya tidak cukup, saya akan menjelaskan poin utamanya dulu."', '{"romaji":"Jikan ga tarinai node, youten o saki ni setsumei shimasu.","display_text":"時間が足りないので、要点を先に説明します。","phonetic_breakdown":["ji-kan-ga","ta-ri-nai-no-de","you-ten-o","sa-ki-ni","se-tsu-mei-shi-ma-su"]}'::jsonb, '{"expected_transcript":"時間が足りないので、要点を先に説明します。"}'::jsonb, NULL, NULL, '足りない (bentuk negatif biasa) + ので.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dea92e2e-a30f-4799-a898-494866784808', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sepatu barunya sempit, kaki saya jadi sakit."', '{"romaji":"Atarashii kutsu ga kitsui node, ashi ga itaku narimashita.","tokens":["きついな","痛くなりました。","きついので、","新しい","へ","足が","靴が"],"target_translation":"Karena sepatu barunya sempit, kaki saya jadi sakit."}'::jsonb, '["新しい","靴が","きついので、","足が","痛くなりました。"]'::jsonb, NULL, NULL, 'きつい (kata sifat い) langsung diikuti ので.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('83532fd4-c580-4042-9a2b-67b1074e6595', '3712fa8d-79d2-4e86-9ea0-9d4877ecc4c3', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 明日は祝日___、会社はお休みです。', '{"options":["なので","ので","だので","のに"],"translation":"Karena besok hari libur nasional, kantor libur.","sentence_template":"明日は祝日[blank]、会社はお休みです。"}'::jsonb, '{"selected":"なので"}'::jsonb, NULL, NULL, '祝日 (shukujitsu, kata benda) + なので.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('62cecf7a-f07f-4903-b7e1-961052961829', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: ホテルのチェックインに備えて、予約番号を控えて___。', '{"options":["きます","います","おきます","いきます"],"translation":"Sebagai persiapan check-in hotel, saya akan mencatat nomor reservasi terlebih dahulu.","sentence_template":"ホテルのチェックインに備えて、予約番号を控えて[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, NULL, NULL, '控えておきます berarti mencatat/menyimpan informasi sebagai persiapan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a02baca-9764-4a9b-88c2-0a4dc0e50bf2', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 後で会議に使うので、この椅子はそのままに___おいてください。', '{"options":["した","して","し","する"],"translation":"Karena nanti akan dipakai untuk rapat, tolong biarkan kursi ini seperti itu saja.","sentence_template":"後で会議に使うので、この椅子はそのままに[blank]おいてください。"}'::jsonb, '{"selected":"して"}'::jsonb, NULL, NULL, 'そのままにしておく adalah penggunaan khusus ～ておく yang berarti ''membiarkan suatu keadaan tetap begitu''.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('869f5e70-8ed6-466a-b606-5c57847ed43c', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan pengingat keluarga berikut. Mengapa harus mengisi daya power bank sekarang?', '{"options":[{"id":"opt_1","text":"Meminta mengisi daya power bank sekarang karena besok dijadwalkan ada pemadaman listrik"},{"id":"opt_2","text":"Pemadaman listrik sedang terjadi sekarang sehingga tidak bisa mengisi daya"},{"id":"opt_3","text":"Jadwal pemadaman listrik besok sudah dibatalkan"},{"id":"opt_4","text":"Power bank tidak diperlukan selama pemadaman listrik"}],"audio_text":"明日は停電の予定があるので、今のうちにモバイルバッテリーを充電しておいてくださいね。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '充電しておいてください meminta persiapan mengisi baterai sebelum listrik padam.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8c4fe1c1-ca6a-4fb1-a598-a1a73ba437c1', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum pindahan, saya sudah membuang barang-barang yang tidak perlu terlebih dahulu."', '{"romaji":"Hikkoshi no mae ni iranai mono o sutete okimashita.","tokens":["おきました。","へ","捨てます。","捨てて","物を","前に","いらない","引っ越しの"],"target_translation":"Sebelum pindahan, saya sudah membuang barang-barang yang tidak perlu terlebih dahulu."}'::jsonb, '["引っ越しの","前に","いらない","物を","捨てて","おきました。"]'::jsonb, NULL, NULL, '捨てる -> 捨てておきました.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('438ce174-c387-43b2-8641-f5769acd2848', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: スープが冷めないように、ふたを___おきます。', '{"options":["閉める","閉めた","閉め","閉めて"],"translation":"Supaya sup tidak dingin, saya akan menutup tutup pancinya terlebih dahulu.","sentence_template":"スープが冷めないように、ふたを[blank]おきます。"}'::jsonb, '{"selected":"閉めて"}'::jsonb, NULL, NULL, '閉める -> 閉めておきます.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('50232270-debe-4524-94c7-80fc83ebad7d', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum ujian, saya akan mengulang pelajaran kanji terlebih dahulu."', '{"romaji":"Shiken no mae ni kanji o fukushuu shite okimasu.","display_text":"試験の前に漢字を復習しておきます。","phonetic_breakdown":["shi-ken-no","ma-e-ni","kan-ji-o","fu-ku-shuu-shi-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"試験の前に漢字を復習しておきます。"}'::jsonb, NULL, NULL, '復習しておきます menekankan persiapan akademik sebelum ujian.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6f3b396f-5cb8-472b-a8d3-863f24fd6953', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan koordinasi persiapan pesta berikut. Apa yang sudah diselesaikan kemarin?', '{"options":[{"id":"opt_1","text":"Hari ini masih harus membeli minuman dan memasak makanan"},{"id":"opt_2","text":"Minuman pesta sudah dibeli kemarin sehingga hari ini tinggal memasak makanan"},{"id":"opt_3","text":"Pesta ditunda karena minuman belum terbeli"},{"id":"opt_4","text":"Semua makanan dan minuman sudah dibeli kemarin"}],"audio_text":"パーティーの飲み物は昨日のうちに買っておいたので、今日は料理だけ作れば大丈夫です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '買っておいた menyatakan persiapan belanja sudah beres sehari sebelumnya.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0ff21b6-a1a5-4670-aefb-493daa989f0a', '3890b342-5e24-4d10-97c3-dd18962bf593', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Karena akan saya baca nanti, tolong biarkan koran itu di atas meja."', '{"romaji":"Ato de yomu node, sono shinbun wa tsukue ni oite oite kudasai.","tokens":["机に","おいてください。","後で","置きます。","置いて","読むので、","が","その新聞は"],"target_translation":"Karena akan saya baca nanti, tolong biarkan koran itu di atas meja."}'::jsonb, '["後で","読むので、","その新聞は","机に","置いて","おいてください。"]'::jsonb, NULL, NULL, '置いておいてください menggabungkan kata kerja 置く (meletakkan) dengan pola ～ておく.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e9ff50c2-edeb-4458-8199-703c65dc3578', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Pilih bentuk ～たら yang benar untuk Adjektiva-I いい (bagus): 都合が___、来週一緒に食事しませんか。', '{"options":["いいったら","よくったら","よかったら","いかったら"],"translation":"Kalau waktumu cocok, maukah makan bersama minggu depan?","sentence_template":"都合が[blank]、来週一緒に食事しませんか。"}'::jsonb, '{"selected":"よかったら"}'::jsonb, NULL, NULL, 'いい memiliki bentuk lampau tidak beraturan よかった, sehingga menjadi よかったら.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('83e20f6a-7951-4193-b900-bdbb9d0ebaa4', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi pengandaian menggunakan kata kerja 来ます (datang): 大阪へ___、ぜひ連絡してくださいね。', '{"options":["来いたら","来るたら","来ったら","来たら"],"translation":"Kalau kamu datang ke Osaka, pastikan hubungi saya ya.","sentence_template":"大阪へ[blank]、ぜひ連絡してくださいね。"}'::jsonb, '{"selected":"来たら"}'::jsonb, NULL, NULL, '来ます (kimasu) -> Bentuk TA: 来た (kita) + ら = 来たら (kitara).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b995d77-4840-4ea0-95ed-afdb837bfbae', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan percakapan di minimarket. Kapan pelanggan mendapat potongan harga?', '{"options":[{"id":"opt_1","text":"Jika membayar dengan uang tunai"},{"id":"opt_2","text":"Jika mendaftarkan aplikasi toko tersebut, mendapat diskon seratus yen"},{"id":"opt_3","text":"Jika berbelanja di atas sepuluh ribu yen"},{"id":"opt_4","text":"Jika datang sebelum jam tujuh pagi"}],"audio_text":"こちらのアプリを登録していただいたら、今日のお会計から百円引きになります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '登録していただいたら (jika berkenan mendaftar aplikasi) -> 百円引き (potongan 100 yen).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9733a680-f192-480d-9687-cf38edb389b1', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan pesan dari manajer. Apa yang diminta setelah laporan diperiksa?', '{"options":[{"id":"opt_1","text":"Menghapus file laporan dari komputer"},{"id":"opt_2","text":"Mengirim laporan lewat pos"},{"id":"opt_3","text":"Meletakkan laporan di atas meja manajer setelah memeriksa angkanya"},{"id":"opt_4","text":"Menunggu manajer kembali sampai malam"}],"audio_text":"数字を確認したら、そのまま部長の机の上に置いておいてください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '数字を確認したら (setelah memeriksa angkanya) + 部長の机の上に置いておいてください.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5feaabe-7826-4f55-a762-28efea8be4e2', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau tombol ini ditekan, pintu otomatis akan terbuka."', '{"romaji":"Kono botan o oshitara, jidou doa ga akimasu.","tokens":["このボタンを","開きます。","押したら、","閉まります。","押します、","自動ドアが"],"target_translation":"Kalau tombol ini ditekan, pintu otomatis akan terbuka."}'::jsonb, '["このボタンを","押したら、","自動ドアが","開きます。"]'::jsonb, NULL, NULL, '押します (menekan) -> 押した + ら = 押したら.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f5c3838-867d-45f4-b8fc-6c27e19ac320', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada pertanyaan tentang kontrak, silakan hubungi kantor."', '{"romaji":"Keiyaku ni tsuite shitsumon ga attara, jimusho made gorenraku kudasai.","display_text":"契約について質問があったら、事務所までご連絡ください。","phonetic_breakdown":["ke-i-ya-ku","ni","tsu-i-te","shi-tsu-mon","ga","at-ta-ra","ji-mu-sho","ma-de","go-ren-ra-ku","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"契約について質問があったら、事務所までご連絡ください。"}'::jsonb, NULL, NULL, '契約 (keiyaku) berarti kontrak; 質問があったら sangat sering dipakai dalam surat dan percakapan resmi.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8664a15a-f0d8-4d99-8f74-85012539442d', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 来年日本へ___、まず桜を見たいです。', '{"options":["行きたら","行くたら","行ったら","行ってたら"],"translation":"Kalau tahun depan pergi ke Jepang, pertama-tama saya ingin melihat sakura.","sentence_template":"来年日本へ[blank]、まず桜を見たいです。"}'::jsonb, '{"selected":"行ったら"}'::jsonb, NULL, NULL, '行く -> 行った -> 行ったら.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dd690bca-62c9-4bc0-a949-66a4d2418c3b', '398d1683-3a0f-4ec6-8bfe-30db4f7b380f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Begitu pulang ke rumah, pertama-tama saya mencuci tangan."', '{"romaji":"Ie ni kaettara, mazu te o araimasu.","display_text":"家に帰ったら、まず手を洗います。","phonetic_breakdown":["i-e-ni","ka-et-ta-ra","ma-zu","te-o","a-ra-i-ma-su"]}'::jsonb, '{"expected_transcript":"家に帰ったら、まず手を洗います。"}'::jsonb, NULL, NULL, '帰る -> 帰った -> 帰ったら menyatakan urutan kejadian yang pasti terjadi.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('72678d36-5f99-4893-9b1c-8f48b5a3fc82', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'reading', 'fill_blank', 'Pilih kosakata untuk ''rekan kerja'': 困ったとき、いつも___が助けてくれます。', '{"options":["同僚","財布","景色","季節"],"translation":"Saat kesulitan, rekan kerja selalu menolong saya.","sentence_template":"困ったとき、いつも[blank]が助けてくれます。"}'::jsonb, '{"selected":"同僚"}'::jsonb, NULL, NULL, '同僚 (douryou) berarti rekan kerja sejawat.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8c3f2c7f-d177-444d-8967-6978da91d79f', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'reading', 'fill_blank', 'Lengkapi kata kerja yang berarti ''memperbaiki'': 先輩がパソコンのエラーを___してくれました。', '{"options":["散歩","修理","旅行","予約"],"translation":"Senior memperbaiki error komputer untuk saya.","sentence_template":"先輩がパソコンのエラーを[blank]してくれました。"}'::jsonb, '{"selected":"修理"}'::jsonb, NULL, NULL, '修理 (shuuri) berarti perbaikan; 修理する berarti memperbaiki.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d06c642e-09ba-4833-b4e5-bb3c826db1c1', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'listening', 'listening_choice', 'Dengarkan cerita karyawan baru ini. Siapa yang membantunya pindah rumah?', '{"options":[{"id":"opt_1","text":"Senior dari tim yang sama"},{"id":"opt_2","text":"Pemilik apartemen"},{"id":"opt_3","text":"Tetangga sebelah rumah"},{"id":"opt_4","text":"Adik laki-lakinya"}],"audio_text":"引っ越しのとき、同じチームの先輩が荷物を運んでくれました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '同じチームの先輩 (onaji chiimu no senpai) berarti senior dari tim yang sama.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be03a471-1245-4058-959e-0bebfe0c3531', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Apa yang dilakukan Budi untuk temannya?', '{"options":[{"id":"opt_1","text":"Meminjamkan uang ongkos kereta"},{"id":"opt_2","text":"Mengantar dan memandu sampai stasiun"},{"id":"opt_3","text":"Membelikan peta kota"},{"id":"opt_4","text":"Memanggilkan taksi daring"}],"audio_text":"道がわからないと言っていたので、駅まで案内してあげました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '案内する (annai suru) berarti memandu/menunjukkan jalan.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b6749aef-71e7-44a8-90df-9fb7db87888d', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Rekan kerja mengajari saya cara membuat laporan."', '{"romaji":"Douryou ga houkokusho no tsukurikata o oshiete kuremashita.","tokens":["教えて","同僚が","もらいました。","くれました。","あげました。","報告書の作り方を"],"target_translation":"Rekan kerja mengajari saya cara membuat laporan."}'::jsonb, '["同僚が","報告書の作り方を","教えて","くれました。"]'::jsonb, NULL, NULL, 'Saat orang lain (同僚が) melakukan kebaikan untuk kita, gunakan ～てくれました.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ee116987-f3bc-4ddc-87c9-748516b7130c', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih karena selalu membantu saya."', '{"romaji":"Itsumo tetsudatte kurete, hontou ni arigatou.","display_text":"いつも手伝ってくれて、本当にありがとう。","phonetic_breakdown":["i-tsu-mo","te-tsu-dat-te","ku-re-te","hon-to-u","ni","a-ri-ga-to-u"]}'::jsonb, '{"expected_transcript":"いつも手伝ってくれて、本当にありがとう。"}'::jsonb, NULL, NULL, '～てくれてありがとう adalah ungkapan terima kasih yang sangat natural kepada teman atau rekan akrab.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95d63c67-db99-46f6-bec1-c6f9a05fcac4', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 道に迷っていた観光客に、駅まで___あげました。', '{"options":["案内した","案内する","案内して","案内"],"translation":"Saya mengantarkan turis yang tersesat sampai ke stasiun.","sentence_template":"道に迷っていた観光客に、駅まで[blank]あげました。"}'::jsonb, '{"selected":"案内して"}'::jsonb, NULL, NULL, '案内してあげました menunjukkan pembicara membantu orang lain (pemberi = saya).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f49c9348-7ee0-4a91-b031-3c780a866253', '3bc4a95f-90ae-4269-a01a-71ad7e3185ba', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita berikut. Siapa yang memberikan bantuan?', '{"options":[{"id":"opt_1","text":"Rekan kerja membantu membawakan barang berat saat pindahan sehingga sangat terbantu"},{"id":"opt_2","text":"Barang berat pembicara rusak saat pindahan"},{"id":"opt_3","text":"Rekan kerja tidak bisa datang membantu pindahan"},{"id":"opt_4","text":"Pembicara membantu rekan kerja pindah rumah"}],"audio_text":"引っ越しのとき、同僚が重い荷物を運んでくれて本当に助かりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '同僚が～てくれた menunjukkan rekan kerja berinisiatif membantu pembicara.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d51db82-3eff-42cf-b80f-7526a1fdbdbb', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 入り口のドアに「本日休業」と___あります。', '{"options":["書く","書か","書いた","書いて"],"translation":"Di pintu masuk tertulis ''Hari ini tutup''.","sentence_template":"入り口のドアに「本日休業」と[blank]あります。"}'::jsonb, '{"selected":"書いて"}'::jsonb, NULL, NULL, '書いてあります menjelaskan teks yang sengaja ditulis untuk memberi informasi.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f48b9a7-0078-439d-a31e-131b77dd32c0', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: プレゼン用のプロジェクターはもう___あります。', '{"options":["つなぎ","つないだ","つなぐ","つないで"],"translation":"Proyektor untuk presentasi sudah disambungkan.","sentence_template":"プレゼン用のプロジェクターはもう[blank]あります。"}'::jsonb, '{"selected":"つないで"}'::jsonb, NULL, NULL, 'つなぐ (tsunagu, menyambungkan) memiliki bentuk て yaitu つないで.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73024c43-87d9-493a-a734-6d0a0c2c54af', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan penjelasan rekan kerja berikut. Apa kondisi amplop tersebut?', '{"options":[{"id":"opt_1","text":"Amplop ini masih kosong dan perlu diisi dokumen"},{"id":"opt_2","text":"Dokumen permohonan hilang bersama amplopnya"},{"id":"opt_3","text":"Semua dokumen permohonan sudah dimasukkan ke dalam amplop ini"},{"id":"opt_4","text":"Amplop ini harus dikirimkan ke kantor pos hari ini"}],"audio_text":"この封筒の中に申請書類が全部入れてありますので、確認してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '入れてあります menandakan dokumen sudah sengaja dimasukkan dan siap diperiksa.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f36bf5c6-da43-45f2-a5ff-dff69f80e749', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di bagian paling atas rak sudah disimpan kertas cadangan."', '{"romaji":"Tana no ichiban ue ni yobi no kami ga shimatte arimasu.","tokens":["しまって","あります。","を","予備の","しまう","紙が","一番上に","棚の"],"target_translation":"Di bagian paling atas rak sudah disimpan kertas cadangan."}'::jsonb, '["棚の","一番上に","予備の","紙が","しまって","あります。"]'::jsonb, NULL, NULL, 'しまう (menyimpan) -> しまってあります menunjukkan barang disimpan dengan sengaja di tempat tertentu.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('66c0d371-f41c-4cbf-a5e2-7cb8687e13b1', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客さんが来るので、部屋がきれいに___あります。', '{"options":["掃除して","掃除した","掃除する","掃除"],"translation":"Karena tamu akan datang, ruangan sudah dibersihkan dengan rapi.","sentence_template":"お客さんが来るので、部屋がきれいに[blank]あります。"}'::jsonb, '{"selected":"掃除して"}'::jsonb, NULL, NULL, '掃除してあります menekankan hasil pembersihan ruangan yang dilakukan demi menyambut tamu.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('272b6fd2-7be7-4607-935a-0b59ea36abb7', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di catatan sudah tertulis nomor telepon dan alamat."', '{"romaji":"Memo ni denwa bangou to juusho ga kaite arimasu.","display_text":"メモに電話番号と住所が書いてあります。","phonetic_breakdown":["me-mo-ni","den-wa-ban-gou-to","juu-sho-ga","ka-i-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"メモに電話番号と住所が書いてあります。"}'::jsonb, NULL, NULL, 'Gunakan partikel に untuk tempat tertulisnya informasi dan が sebelum 書いてあります.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0453ba13-1ea7-4b9d-8dae-a63a5f8ec348', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan laporan persiapan berikut. Apa yang sudah dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Ruang rapat belum memiliki kursi sama sekali"},{"id":"opt_2","text":"Sepuluh kursi di ruang rapat perlu segera diperbaiki"},{"id":"opt_3","text":"Hanya ada sepuluh peserta yang boleh masuk ruang rapat"},{"id":"opt_4","text":"Sepuluh kursi sudah disiapkan di ruang rapat dan bisa ditambah jika kurang"}],"audio_text":"会議室の椅子は十脚用意してありますが、足りなければ追加しますね。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '用意してあります berarti sudah disiapkan dengan sengaja.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f0123f4-4b8f-4a3c-92f4-75d09ec8eeb2', '3bec9304-6cb4-4c35-a609-cbbd795f97b6', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Bahan untuk bekal besok sudah dipotong sebelumnya."', '{"romaji":"Ashita no obentou no zairyou wa kitte arimasu.","tokens":["切って","材料は","お弁当の","切ります。","明日の","へ","あります。"],"target_translation":"Bahan untuk bekal besok sudah dipotong sebelumnya."}'::jsonb, '["明日の","お弁当の","材料は","切って","あります。"]'::jsonb, NULL, NULL, '切ってあります menunjukkan bahan sudah dipotong agar pagi harinya tinggal dimasak.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('89fa2933-950d-4633-83ac-88c2bbac2315', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan arahan di pabrik. Apa yang dilakukan jika lampu merah menyala?', '{"options":[{"id":"opt_1","text":"Membiarkan mesin berjalan sampai jam istirahat"},{"id":"opt_2","text":"Mencabut kabel listrik seluruh gedung"},{"id":"opt_3","text":"Segera menghentikan mesin dan memanggil penanggung jawab"},{"id":"opt_4","text":"Menekan tombol hijau tiga kali"}],"audio_text":"もし赤いランプがついたら、すぐに機械を止めて責任者を呼んでください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '赤いランプがついたら (jika lampu merah menyala) + 機械を止めて責任者を呼んでください.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4e8fe880-058d-41dd-b19b-69b3400ce67f', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan percakapan teman. Apa rencana pembicara setelah lulus ujian N4?', '{"options":[{"id":"opt_1","text":"Langsung berhenti belajar bahasa Jepang"},{"id":"opt_2","text":"Pindah ke negara lain"},{"id":"opt_3","text":"Mengulang ujian N5"},{"id":"opt_4","text":"Ingin mencoba ujian Tokutei Ginou bidang keperawatan (Kaigo)"}],"audio_text":"N4に合格したら、次は介護の特定技能試験に挑戦したいです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'N4に合格したら (setelah lulus N4) + 介護の特定技能試験に挑戦したい (ingin menantang ujian Tokutei Ginou Kaigo).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98ac96ed-0822-42a1-83b8-21e5c883efd9', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan petunjuk arah ini. Belok di mana setelah keluar dari pintu timur?', '{"options":[{"id":"opt_1","text":"Segera belok kanan lalu jalan lurus"},{"id":"opt_2","text":"Belok kiri lalu menyeberang jembatan"},{"id":"opt_3","text":"Naik bus nomor lima di depan stasiun"},{"id":"opt_4","text":"Masuk ke gedung di sebelah kiri"}],"audio_text":"東口を出たら、すぐ右へ曲がってまっすぐ歩いてください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '東口を出たら (setelah keluar pintu timur) + すぐ右へ曲がって (segera belok kanan).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d95d056c-4b51-4ab2-9d5b-14f9b7b5c0d6', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Ubah 飲みます (minum) ke bentuk ～たら: この薬を___、少し眠くなりますよ。', '{"options":["飲いたら","飲みたら","飲ったら","飲んだら"],"translation":"Kalau minum obat ini, kamu akan merasa agak mengantuk ya.","sentence_template":"この薬を[blank]、少し眠くなりますよ。"}'::jsonb, '{"selected":"飲んだら"}'::jsonb, NULL, NULL, '飲みます -> Bentuk TA: 飲んだ + ら = 飲んだら.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ffef84ad-4dd7-429f-9e5f-cf9f3749b242', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi pengandaian menggunakan kata kerja 買います: もし宝くじに___、両親に家を建ててあげたいです。', '{"options":["当たったら","当たいたら","当たんだら","当たりたら"],"translation":"Seandainya menang lotre, saya ingin membangunkan rumah untuk orang tua.","sentence_template":"もし宝くじに[blank]、両親に家を建ててあげたいです。"}'::jsonb, '{"selected":"当たったら"}'::jsonb, NULL, NULL, '当たります (menang/kena) -> 当たった + ら = 当たったら.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e2cab66-46f8-4b46-956f-7545b5919f90', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi instruksi prosedur penggunaan mesin: カードを___、暗証番号を入力してください。', '{"options":["入れますら","入れたら","入ったら","入れるたら"],"translation":"Setelah memasukkan kartu, silakan masukkan nomor PIN Anda.","sentence_template":"カードを[blank]、暗証番号を入力してください。"}'::jsonb, '{"selected":"入れたら"}'::jsonb, NULL, NULL, '入れます (memasukkan, transitif) -> 入れた + ら = 入れたら.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11773e72-7fea-4ce7-ba0d-dcec87bf018a', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan petunjuk mesin berikut. Apa yang terjadi setelah tombol ditekan?', '{"options":[{"id":"opt_1","text":"Mesin hanya mengeluarkan air dingin jika tombol ditekan"},{"id":"opt_2","text":"Pembicara melarang menekan tombol tersebut"},{"id":"opt_3","text":"Tombol ini digunakan untuk mematikan mesin"},{"id":"opt_4","text":"Jika menekan tombol ini, teh hangat akan keluar"}],"audio_text":"このボタンを押したら、温かいお茶が出てきますよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '押す -> 押したら menunjukkan hasil otomatis dari suatu tindakan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4be440d-a85b-42bc-9671-418a3f5411fc', '3c5b234c-0db2-4f9b-b252-4116f8e98584', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: もっと___、買いたいのですが、高すぎますね。', '{"options":["安いたら","安かったら","安いだったら","安いったら"],"translation":"Kalau lebih murah sih saya ingin membelinya, tapi terlalu mahal ya.","sentence_template":"もっと[blank]、買いたいのですが、高すぎますね。"}'::jsonb, '{"selected":"安かったら"}'::jsonb, NULL, NULL, 'Kata sifat い: ganti い dengan かったら (安い -> 安かったら).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('66b46cf6-475b-46eb-8928-6ac99686b5e4', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 引っ越しをしたら、二週間以内に市役所へ届け出を___。', '{"options":["してあります","したいです","しませんでした","しなければなりません"],"translation":"Setelah pindah rumah, harus melapor ke balai kota dalam waktu dua minggu.","sentence_template":"引っ越しをしたら、二週間以内に市役所へ届け出を[blank]。"}'::jsonb, '{"selected":"しなければなりません"}'::jsonb, NULL, NULL, '届け出をする (todokede o suru) berarti melapor secara resmi; bentuk wajibnya しなければなりません.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('652e344d-3da4-474b-8314-dea767a074a1', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この区域は立ち入り禁止なので、許可証が___。', '{"options":["なければなりません","あります","いりません","いました"],"translation":"Karena area ini terlarang untuk umum, harus memiliki surat izin.","sentence_template":"この区域は立ち入り禁止なので、許可証が[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, 'ある bentuk negatifnya ない -> なければなりません berarti harus ada/memiliki.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c21774d-0463-42ce-9b4f-4e17fcbb12b3', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan aturan gedung perkantoran berikut. Apa yang harus dilakukan jika lupa kartu karyawan?', '{"options":[{"id":"opt_1","text":"Jika lupa membawa kartu karyawan, wajib meminjam kartu masuk sementara di resepsionis"},{"id":"opt_2","text":"Resepsionis tidak melayani peminjaman kartu masuk"},{"id":"opt_3","text":"Kartu karyawan hanya dipakai oleh tamu dari luar"},{"id":"opt_4","text":"Jika lupa kartu karyawan, karyawan harus pulang ke rumah"}],"audio_text":"社員証を忘れた場合は、受付で一時入館証を借りなければなりません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '借りる -> 借りない -> 借りなければなりません berarti wajib meminjam.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7e709d3-a4b9-4ca6-b8f2-0a5f8b48b2e5', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum pulang kantor, harus mematikan daya komputer."', '{"romaji":"Taisha suru mae ni pasokon no dengen o kiranakereba narimasen.","tokens":["が","電源を","切ります。","前に","なりません。","パソコンの","切らなければ","退社する"],"target_translation":"Sebelum pulang kantor, harus mematikan daya komputer."}'::jsonb, '["退社する","前に","パソコンの","電源を","切らなければ","なりません。"]'::jsonb, NULL, NULL, '電源を切る -> 電源を切らなければなりません.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7ef74a4-7a8c-42a9-abdc-4ae7477ebf35', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 機密情報は絶対に社外へ持ち出してはいけませんし、パスワードも定期的に変え___。', '{"options":["ておきます","たばかりです","てもいいです","なければなりません"],"translation":"Informasi rahasia tidak boleh dibawa keluar kantor, dan kata sandi juga harus diganti secara berkala.","sentence_template":"機密情報は絶対に社外へ持ち出してはいけませんし、パスワードも定期的に変え[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, '変える (kelompok 2) -> 変えない -> 変えなければなりません.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5fa77e6-a619-4f4a-a32e-5510f6cdb5a0', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Waktu yang dijanjikan dengan klien harus selalu ditepati."', '{"romaji":"Okyakusan to yakusoku shita jikan wa kanarazu mamoranakereba narimasen.","display_text":"お客さんと約束した時間は必ず守らなければなりません。","phonetic_breakdown":["o-kya-ku-san-to","ya-ku-so-ku-shi-ta","ji-kan-wa","ka-na-ra-zu","ma-mo-ra-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"お客さんと約束した時間は必ず守らなければなりません。"}'::jsonb, NULL, NULL, '必ず (kanarazu) memperkuat nuansa kewajiban pada 守らなければなりません.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0f7ac3d3-4026-4574-8f7b-dd7816bdb2ee', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan rencana perjalanan berikut. Mengapa pembicara harus bangun sangat pagi?', '{"options":[{"id":"opt_1","text":"Perjalanan shinkansen besok dibatalkan"},{"id":"opt_2","text":"Harus bangun pukul 5.30 karena naik shinkansen pukul 7 pagi besok"},{"id":"opt_3","text":"Pembicara biasa bangun pukul 7 pagi setiap hari"},{"id":"opt_4","text":"Shinkansen berangkat pukul 5.30 pagi besok"}],"audio_text":"明日は朝七時の新幹線に乗るので、五時半には起きなければなりません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '起きる -> 起きない -> 起きなければなりません berarti harus bangun.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7121c61b-c169-4de4-b5e7-fe40409479f1', '402a30af-24e7-43e3-ae5d-fd9c71b374d2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum mulai kerja paruh waktu, harus mendapatkan izin kerja di luar status visa."', '{"romaji":"Arubaito o hajimeru mae ni shikakugai katsudou kyoka o toranakereba narimasen.","tokens":["資格外活動許可を","へ","始める前に","なりません。","取らなければ","アルバイトを","取ります。"],"target_translation":"Sebelum mulai kerja paruh waktu, harus mendapatkan izin kerja di luar status visa."}'::jsonb, '["アルバイトを","始める前に","資格外活動許可を","取らなければ","なりません。"]'::jsonb, NULL, NULL, '取る -> 取らない -> 取らなければなりません.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b456b22e-95ed-4355-9a12-fbc93bb05386', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan ucapan perpisahan berikut. Apa yang dikatakan pembicara?', '{"options":[{"id":"opt_1","text":"Mengundang lawan bicara berkunjung ke rumah jika lain kali datang ke Tokyo"},{"id":"opt_2","text":"Lawan bicara baru saja pulang dari Tokyo"},{"id":"opt_3","text":"Pembicara akan pindah dari Tokyo minggu depan"},{"id":"opt_4","text":"Pembicara sedang berkunjung ke rumah lawan bicara di Tokyo"}],"audio_text":"今度東京へ来たら、ぜひ私の家にも遊びに来てくださいね。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来たら (kitara) menyatakan kondisi ''jika/ketika datang''.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4d7c4c95-5a33-41dd-910e-ca03fd502313', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah makan selesai, saya membereskan piring."', '{"romaji":"Shokuji ga owattara, osara o katazukemasu.","display_text":"食事が終わったら、お皿を片付けます。","phonetic_breakdown":["sho-ku-ji-ga","o-wat-ta-ra","o-sa-ra-o","ka-ta-zu-ke-ma-su"]}'::jsonb, '{"expected_transcript":"食事が終わったら、お皿を片付けます。"}'::jsonb, NULL, NULL, '終わったら menandai urutan aktivitas rumah tangga.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c603e8c-bf38-464b-af05-74e4a4f02555', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau bahasa Jepang saya sudah lebih mahir, saya ingin bekerja di perusahaan Jepang."', '{"romaji":"Motto Nihongo ga jouzu ni nattara, Nihon no kaisha de hatarakitai desu.","tokens":["日本語が","日本の会社で","もっと","上手になったら、","上手になるたら、","を","働きたいです。"],"target_translation":"Kalau bahasa Jepang saya sudah lebih mahir, saya ingin bekerja di perusahaan Jepang."}'::jsonb, '["もっと","日本語が","上手になったら、","日本の会社で","働きたいです。"]'::jsonb, NULL, NULL, '上手になる -> 上手になったら.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1998008c-0261-45a4-a781-9cef317dec47', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この薬を___、少し楽になりました。', '{"options":["飲んでら","飲みたら","飲むたら","飲んだら"],"translation":"Setelah saya minum obat ini, rasanya jadi sedikit lebih lega.","sentence_template":"この薬を[blank]、少し楽になりました。"}'::jsonb, '{"selected":"飲んだら"}'::jsonb, NULL, NULL, 'たら juga dipakai untuk menyatakan hasil tak terduga atau langsung setelah melakukan sesuatu.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e5954c5-6427-4296-be3a-fe1a62c5fd72', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan cerita musim dingin berikut. Apa yang dilihat pembicara saat membuka pintu?', '{"options":[{"id":"opt_1","text":"Pembicara tidak bisa membuka pintu karena salju terlalu tebal"},{"id":"opt_2","text":"Begitu membuka pintu, di luar seluruhnya sudah tertutup salju putih"},{"id":"opt_3","text":"Di luar sedang turun hujan deras"},{"id":"opt_4","text":"Salju masuk ke dalam rumah karena pintu lupa ditutup"}],"audio_text":"ドアを開けたら、外は一面真っ白な雪でした。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '開けたら～だった menggambarkan penemuan langsung begitu aksi dilakukan.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('10e1d403-c3a2-4d67-96f8-b2dbb116cd97', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada masalah apa pun, silakan berkonsultasi kapan saja."', '{"romaji":"Nanika mondai ga attara, itsudemo soudan shite kudasai.","display_text":"何か問題があったら、いつでも相談してください。","phonetic_breakdown":["na-ni-ka","mon-dai-ga","at-ta-ra","i-tsu-de-mo","sou-dan-shi-te","ku-da-sai"]}'::jsonb, '{"expected_transcript":"何か問題があったら、いつでも相談してください。"}'::jsonb, NULL, NULL, '問題があったら sangat umum diucapkan oleh atasan atau mentor di tempat kerja.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('faf51878-44cf-4a51-9fa5-539895f71d6b', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah pukul sepuluh, mari kita mulai rapatnya."', '{"romaji":"Juuji ni nattara, kaigi o hajimemashou.","tokens":["へ","十時に","なったら、","始めましょう。","会議を","なるたら、"],"target_translation":"Kalau sudah pukul sepuluh, mari kita mulai rapatnya."}'::jsonb, '["十時に","なったら、","会議を","始めましょう。"]'::jsonb, NULL, NULL, '十時になったら berarti ''ketika waktu menunjukkan pukul 10''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3f531c7-73d1-4307-9da3-91c53e694d5c', '4213596a-cb6c-4cd0-81d1-8e5f08639df1', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 値段が___、別の店も見てみましょう。', '{"options":["高いだったら","高いたら","高いったら","高かったら"],"translation":"Kalau harganya mahal, mari kita lihat toko lain juga.","sentence_template":"値段が[blank]、別の店も見てみましょう。"}'::jsonb, '{"selected":"高かったら"}'::jsonb, NULL, NULL, '高い -> 高かったら.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('28f0bc75-ee8f-4111-a1a8-952af5c3577d', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran dokter ini. Apa yang sebaiknya dilakukan pasien?', '{"options":[{"id":"opt_1","text":"Tidak berolahraga berat dan banyak tidur selama dua hingga tiga hari"},{"id":"opt_2","text":"Berlari pagi setiap hari agar berkeringat"},{"id":"opt_3","text":"Langsung kembali lembur di kantor"},{"id":"opt_4","text":"Menghentikan semua obat setelah satu hari"}],"audio_text":"二、三日は激しい運動をしないで、よく寝たほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '激しい運動をしないで、よく寝たほうがいい menyarankan menghindari olahraga berat dan tidur cukup.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3e143b62-a173-4ced-995c-c6bbb424d01e', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan nasihat senior ini. Apa sarannya sebelum musim dingin tiba?', '{"options":[{"id":"opt_1","text":"Menyalakan kipas angin di kamar"},{"id":"opt_2","text":"Membeli mantel hangat sebelum bulan depan mendadak dingin"},{"id":"opt_3","text":"Membuka jendela setiap malam"},{"id":"opt_4","text":"Pindah ke apartemen yang lebih kecil"}],"audio_text":"来月から急に寒くなりますから、暖かいコートを買っておいたほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '暖かいコートを買っておいたほうがいい menyarankan membeli mantel hangat sebagai persiapan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95381359-455c-4637-befc-91839d009dfe', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa dia menyarankan naik kereta?', '{"options":[{"id":"opt_1","text":"Karena tiket bus sudah habis"},{"id":"opt_2","text":"Karena stasiun kereta sangat jauh"},{"id":"opt_3","text":"Karena jalanan sangat macet pada sore hari"},{"id":"opt_4","text":"Karena bus tidak beroperasi pada hari kerja"}],"audio_text":"夕方は道路がとても混みますから、バスより電車で行ったほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '道路がとても混みますから (karena jalanan sangat macet) menjadi alasan saran naik kereta.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddec690e-0dbe-4439-910b-68bee2efb035', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi saran saat mata lelah menatap layar: パソコンを長く見すぎたら、少し目を___ほうがいいです。', '{"options":["休めない","休めて","休める","休めた"],"translation":"Kalau terlalu lama menatap komputer, sebaiknya mengistirahatkan mata sebentar.","sentence_template":"パソコンを長く見すぎたら、少し目を[blank]ほうがいいです。"}'::jsonb, '{"selected":"休めた"}'::jsonb, NULL, NULL, '休めます (mengistirahatkan, transitif) -> Bentuk TA: 休めた + ほうがいいです.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4c44fd73-9681-4fb2-82eb-79c9b56331e2', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Pilih saran negatif yang tepat untuk makanan pedas saat sakit perut: 胃が痛いときは、辛い物を___ほうがいいですよ。', '{"options":["食べない","食べます","食べた","食べて"],"translation":"Saat lambung sakit, sebaiknya tidak makan makanan pedas ya.","sentence_template":"胃が痛いときは、辛い物を[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"食べない"}'::jsonb, NULL, NULL, 'Saran menghindari sesuatu menggunakan bentuk NAI: 食べないほうがいい.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('36da8022-b72e-45ee-a453-f5934f94ea91', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi saran menghadapi ujian JLPT: 毎日少しずつ漢字を___ほうがいいです。', '{"options":["覚える","覚えた","覚えます","覚えて"],"translation":"Sebaiknya menghafal kanji sedikit demi sedikit setiap hari.","sentence_template":"毎日少しずつ漢字を[blank]ほうがいいです。"}'::jsonb, '{"selected":"覚えた"}'::jsonb, NULL, NULL, '覚えます (menghafal) -> Bentuk TA: 覚えた + ほうがいいです.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fe12cbd3-f339-46ff-8538-d8cf0a230262', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan nasihat rekan kerja berikut. Saran apa yang diberikan?', '{"options":[{"id":"opt_1","text":"Menyarankan mengganti komputer dengan yang baru"},{"id":"opt_2","text":"Meminta lawan bicara mematikan lampu kantor"},{"id":"opt_3","text":"Menyarankan untuk bekerja satu jam lebih lama tanpa istirahat"},{"id":"opt_4","text":"Menyarankan untuk mengalihkan pandangan dari layar setiap satu jam agar mata tidak lelah"}],"audio_text":"目が疲れているみたいですね。一時間ごとに少し画面から目を離したほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '目を離したほうがいい berarti sebaiknya mengalihkan pandangan dari layar.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efaddec1-738f-43b9-94b2-94c040c92fc2', '45a980af-99e5-4b28-af40-9cc695063f22', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 風邪が流行っているので、手洗いとうがいをしっかり___ほうがいいです。', '{"options":["する","して","した","しない"],"translation":"Karena flu sedang mewabah, sebaiknya rajin mencuci tangan dan berkumur.","sentence_template":"風邪が流行っているので、手洗いとうがいをしっかり[blank]ほうがいいです。"}'::jsonb, '{"selected":"した"}'::jsonb, NULL, NULL, 'する dalam saran positif berubah menjadi bentuk た -> したほうがいい.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f915695-93b2-4cdd-abc3-6fa4fb5c6b64', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''demam'': 昨夜から三十八度の___があります。', '{"options":["風","雲","熱","音"],"translation":"Sejak semalam saya mengalami demam 38 derajat.","sentence_template":"昨夜から三十八度の[blank]があります。"}'::jsonb, '{"selected":"熱"}'::jsonb, NULL, NULL, '熱 (netsu) berarti demam atau panas tubuh; 熱がある berarti sedang demam.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cad60c31-4f65-4649-b7c9-a28e81860295', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata gejala flu: のどが痛くて、___も止まりません。', '{"options":["めがね","かさ","くつ","せき"],"translation":"Tenggorokan saya sakit dan batuk juga tidak berhenti.","sentence_template":"のどが痛くて、[blank]も止まりません。"}'::jsonb, '{"selected":"せき"}'::jsonb, NULL, NULL, 'せき (seki) berarti batuk; のどが痛い berarti sakit tenggorokan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b467f55-f985-4615-8814-f564c446b26d', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'listening', 'listening_choice', 'Dengarkan keluhan pasien di klinik. Bagian tubuh mana yang sakit?', '{"options":[{"id":"opt_1","text":"Kepala karena kurang tidur"},{"id":"opt_2","text":"Punggung karena mengangkat beban"},{"id":"opt_3","text":"Perut karena terlalu banyak makan makanan dingin"},{"id":"opt_4","text":"Gigi karena makan makanan manis"}],"audio_text":"朝からずっとお腹が痛いんです。昨日の夜、冷たいものを食べすぎました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'お腹が痛い (onaka ga itai) berarti sakit perut, akibat 冷たいものを食べすぎました.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61717ebc-88a6-4c55-bc39-21b13d44927f', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'listening', 'listening_choice', 'Dengarkan arahan apoteker berikut. Kapan obat ini harus diminum?', '{"options":[{"id":"opt_1","text":"Sekali sehari sebelum tidur"},{"id":"opt_2","text":"Dua kali sehari sebelum makan"},{"id":"opt_3","text":"Hanya saat demam tinggi"},{"id":"opt_4","text":"Tiga kali sehari setelah makan"}],"audio_text":"この薬は一日に三回、食事のあとで飲んでください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '一日に三回、食事のあとで berarti tiga kali sehari setelah makan.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ec53352-a4dd-4c7c-8d20-8164c870fca9', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kondisi badan kurang sehat, saya pergi ke klinik."', '{"romaji":"Taichou ga warui node, byouin e ikimasu.","tokens":["体調が悪いので、","行きます。","会社へ","行きました。","病院へ"],"target_translation":"Karena kondisi badan kurang sehat, saya pergi ke klinik."}'::jsonb, '["体調が悪いので、","病院へ","行きます。"]'::jsonb, NULL, NULL, '体調が悪い (taichou ga warui) adalah ungkapan umum untuk kondisi badan sedang tidak fit.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6bd7f7ee-1a09-4a2e-8ae4-af41edd6d1b1', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan beristirahat cukup dan minum banyak air hangat."', '{"romaji":"Yukkuri yasunde, atatakai mizu o takusan nomimasu.","display_text":"ゆっくり休んで、温かい水をたくさん飲みます。","phonetic_breakdown":["yuk-ku-ri","ya-sun-de","a-ta-ta-ka-i","mi-zu","o","ta-ku-san","no-mi-ma-su"]}'::jsonb, '{"expected_transcript":"ゆっくり休んで、温かい水をたくさん飲みます。"}'::jsonb, NULL, NULL, 'ゆっくり休む (beristirahat tenang) dan 温かい水 (air hangat) sering dipakai saat membahas pemulihan kesehatan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('64a6f271-aa74-4d10-b5b0-9238e93eb0d1', '4f360f65-8d89-4043-bb0c-1132d140b17e', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 熱が高いときは、無理をしないで早めに___を受けたほうがいいですよ。', '{"options":["診察","買い物","運転","見学"],"translation":"Saat demam tinggi, sebaiknya jangan memaksakan diri dan segera menjalani pemeriksaan dokter.","sentence_template":"熱が高いときは、無理をしないで早めに[blank]を受けたほうがいいですよ。"}'::jsonb, '{"selected":"診察"}'::jsonb, NULL, NULL, '診察 (shinsatsu) berarti pemeriksaan medis di klinik atau rumah sakit.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c02fe3c-2489-4205-ab48-2cc8dabf7d64', '4f360f65-8d89-4043-bb0c-1132d140b17e', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran berikut. Apa yang dianjurkan oleh pembicara?', '{"options":[{"id":"opt_1","text":"Meminta lawan bicara membeli minuman di minimarket"},{"id":"opt_2","text":"Melarang lawan bicara berbicara sepanjang hari"},{"id":"opt_3","text":"Menyarankan untuk tidak minum minuman dingin saat tenggorokan sakit"},{"id":"opt_4","text":"Menyarankan minum air es agar tenggorokan cepat sembuh"}],"audio_text":"のどが痛いなら、冷たい飲み物は飲まないほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '飲まないほうがいい adalah saran negatif yang berarti ''sebaiknya tidak minum''.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('14749cd3-22e7-404a-8008-17966ae900e4', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan mengirimkan dokumennya lewat email hari ini."', '{"romaji":"Honjitsuchuu ni shiryou o meeru de ookuri itashimasu.","display_text":"本日中に資料をメールでお送りいたします。","phonetic_breakdown":["hon-ji-tsu-chu-u","ni","shi-ryo-u","o","me-e-ru","de","o-o-ku-ri","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"本日中に資料をメールでお送りいたします。"}'::jsonb, NULL, NULL, '送ります -> お送りいたします sangat sering dipakai dalam korespondensi bisnis Jepang.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('05da86b6-67bd-4989-a5b0-1256da1ca5bd', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya sudah menerima kartu nama Anda dengan hormat."', '{"romaji":"Choudai itashimasu. Arigatou gozaimasu.","display_text":"頂戴いたします。ありがとうございます。","phonetic_breakdown":["cho-u-da-i","i-ta-shi-ma-su","a-ri-ga-to-u","go-za-i-ma-su"]}'::jsonb, '{"expected_transcript":"頂戴いたします。ありがとうございます。"}'::jsonb, NULL, NULL, '頂戴いたします adalah ungkapan Kenjougo saat menerima kartu nama atau pemberian dari klien/atasan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d62aef4-acb8-425d-a1dd-222658b31967', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Biar saya yang memanggilkan taksi untuk Anda."', '{"romaji":"Watashi ga takushii o oyobi itashimasu.","display_text":"私がタクシーをお呼びいたします。","phonetic_breakdown":["wa-ta-shi","ga","ta-ku-shi-i","o","o-yo-bi","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"私がタクシーをお呼びいたします。"}'::jsonb, NULL, NULL, '呼びます -> お呼びいたします merendahkan tindakan pembicara yang melayani tamu.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b0bea46d-bca9-4f5f-8d4d-154cc037db6d', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan segera menghubungi kepala bagian."', '{"romaji":"Sugu ni kachou e gorenraku itashimasu.","tokens":["ご連絡になります。","連絡しますか。","課長へ","いたします。","ご連絡","すぐに"],"target_translation":"Saya akan segera menghubungi kepala bagian."}'::jsonb, '["すぐに","課長へ","ご連絡","いたします。"]'::jsonb, NULL, NULL, 'ご連絡いたします (Kenjougo dari 連絡します).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9aec16e9-42d1-4fd9-8fec-5ca5c035e0f9', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menyiapkan kopi untuk Anda."', '{"romaji":"Koohii o goyoui itashimasu.","tokens":["コーヒーを","ご用意になります。","いたします。","ご用意","飲みます。"],"target_translation":"Saya akan menyiapkan kopi untuk Anda."}'::jsonb, '["コーヒーを","ご用意","いたします。"]'::jsonb, NULL, NULL, '用意する (menyiapkan) -> ご用意いたします.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('699dfe6e-f54b-407e-ad99-216f2444a0a1', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya sudah membaca surat dari Bapak dengan baik."', '{"romaji":"Shachou kara no otegami o haiken itashimashita.","tokens":["拝見","読みます。","ご覧になりました。","いたしました。","社長からの","お手紙を"],"target_translation":"Saya sudah membaca surat dari Bapak dengan baik."}'::jsonb, '["社長からの","お手紙を","拝見","いたしました。"]'::jsonb, NULL, NULL, '拝見いたしました adalah Kenjougo paling halus untuk ''saya telah membaca/melihat''.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('525010ea-06a6-49ca-a104-e3862dd0ac6d', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan segera memeriksanya sekarang, mohon tunggu sebentar."', '{"romaji":"Tadaima kakunin itashimasu node, shoushou omachi kudasai.","display_text":"ただいま確認いたしますので、少々お待ちください。","phonetic_breakdown":["ta-da-i-ma","ka-ku-nin","i-ta-shi-ma-su-no-de","shou-shou","o-ma-chi","ku-da-sai"]}'::jsonb, '{"expected_transcript":"ただいま確認いたしますので、少々お待ちください。"}'::jsonb, NULL, NULL, 'いたします adalah bentuk Kenjougo dari します.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5ce6aec-baf4-4890-9d1f-a73a74105893', '50c53ca9-5279-43cb-8951-c6b625ef77ec', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan mengantarkan Anda sampai ruang rapat."', '{"romaji":"Watashi ga kaigishitsu made go-annai itashimasu.","tokens":["ご案内になります。","会議室まで","私が","いたします。","ご案内","を"],"target_translation":"Saya akan mengantarkan Anda sampai ruang rapat."}'::jsonb, '["私が","会議室まで","ご案内","いたします。"]'::jsonb, NULL, NULL, 'Kata kerja する berunsur kanji memakai pola ご + kata benda + します/いたします.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dac72443-ffe9-46ea-8a95-934ed0c20743', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: メールの添付ファイルが開けないので、もう一度___いただけませんか。', '{"options":["送る","送って","送った","送り"],"translation":"Karena lampiran email tidak bisa dibuka, maukah Anda mengirimkannya sekali lagi?","sentence_template":"メールの添付ファイルが開けないので、もう一度[blank]いただけませんか。"}'::jsonb, '{"selected":"送って"}'::jsonb, NULL, NULL, 'Sebelum いただけませんか, kata kerja harus diubah ke bentuk て (送る -> 送って).', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5ad52bd-bd36-4c50-b492-d5e99dbffc69', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客様にお渡しする資料ですので、念のため___していただけませんか。', '{"options":["ドライブ","ランチ","ショッピング","チェック"],"translation":"Karena ini materi untuk diberikan kepada klien, maukah Anda mengeceknya untuk berjaga-jaga?","sentence_template":"お客様にお渡しする資料ですので、念のため[blank]していただけませんか。"}'::jsonb, '{"selected":"チェック"}'::jsonb, NULL, NULL, 'チェックしていただけませんか berarti ''maukah Anda memeriksa/mengeceknya''.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('59d67a3f-70cd-4050-b22c-471c77660a13', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan pesan bisnis berikut. Permintaan apa yang disampaikan?', '{"options":[{"id":"opt_1","text":"Meminta izin mengundurkan jadwal pertemuan besok sekitar 30 menit"},{"id":"opt_2","text":"Meminta memajukan jadwal rapat 30 menit lebih awal"},{"id":"opt_3","text":"Menginformasikan bahwa rapat berlangsung selama 30 menit"},{"id":"opt_4","text":"Membatalkan pertemuan besok secara sepihak"}],"audio_text":"申し訳ありませんが、明日の打ち合わせの時間を三十分ほど遅らせていただけませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '遅らせていただけませんか berarti memohon agar waktu dapat dimundurkan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa633346-cf38-4284-a91b-533fb128aa42', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maukah Anda mengisi alamat Anda pada formulir ini?"', '{"romaji":"Kochira no foomu ni go-juusho o kinyuu shite itadakemasen ka.","tokens":["フォームに","いただけませんか。","ご住所を","を","記入します。","記入して","こちらの"],"target_translation":"Maukah Anda mengisi alamat Anda pada formulir ini?"}'::jsonb, '["こちらの","フォームに","ご住所を","記入して","いただけませんか。"]'::jsonb, NULL, NULL, '記入する (kinyuu suru) berarti mengisi formulir; gunakan partikel に untuk tempat penulisan.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('697ee211-4379-4c30-82c7-8272958745e0', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 社内ネットワークにつながらないので、パスワードを___いただけませんか。', '{"options":["教えても","教えない","教える","教えて"],"translation":"Karena tidak terhubung ke jaringan internal, maukah Anda memberi tahu kata sandinya?","sentence_template":"社内ネットワークにつながらないので、パスワードを[blank]いただけませんか。"}'::jsonb, '{"selected":"教えて"}'::jsonb, NULL, NULL, 'Bentuk て dari 教える adalah 教えて, diikuti いただけませんか.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('18d3e282-5dad-4b01-9e5c-cb7c0bce7072', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, maukah Anda memeriksa nominal pada surat penawaran harga ini?"', '{"romaji":"Sumimasen ga, mitsumorisho no kingaku o go-kakunin itadakemasen ka.","display_text":"すみませんが、見積書の金額をご確認いただけませんか。","phonetic_breakdown":["su-mi-ma-sen-ga","mi-tsu-mo-ri-sho-no","kin-ga-ku-o","go-ka-ku-nin","i-ta-da-ke-ma-sen-ka"]}'::jsonb, '{"expected_transcript":"すみませんが、見積書の金額をご確認いただけませんか。"}'::jsonb, NULL, NULL, '見積書 (mitsumorisho) adalah surat penawaran harga; ご確認いただけませんか sangat lazim dalam bisnis.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa7ca6e7-51af-4970-be5d-8fc0eb658563', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan permintaan di loket kantor berikut. Apa yang diminta pembicara?', '{"options":[{"id":"opt_1","text":"Menanyakan lokasi mesin pencetak kuitansi"},{"id":"opt_2","text":"Meminta pembubuhan stempel perusahaan pada kuitansi"},{"id":"opt_3","text":"Meminta penerbitan kuitansi baru dengan tanggal berbeda"},{"id":"opt_4","text":"Mengembalikan kuitansi yang salah nominal"}],"audio_text":"お急ぎのところ申し訳ありませんが、こちらの領収書に社印を押していただけませんか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '社印を押す (shain o osu) berarti membubuhkan cap atau stempel perusahaan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8221a069-3fa8-48d1-ba26-992613837dc7', '5440b53b-c2c7-47e9-832e-80deb653081c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maukah Anda memperbaiki sedikit ungkapan bahasa Jepang saya?"', '{"romaji":"Nihongo no hyougen o sukoshi naoshite itadakemasen ka.","tokens":["少し","表現を","いただけませんか。","直しました。","直して","へ","日本語の"],"target_translation":"Maukah Anda memperbaiki sedikit ungkapan bahasa Jepang saya?"}'::jsonb, '["日本語の","表現を","少し","直して","いただけませんか。"]'::jsonb, NULL, NULL, '直す (naosu) berarti memperbaiki; bentuk て-nya adalah 直して.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70c1e5be-6fb1-47df-8ad1-77b60f94d20a', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 佐藤さんは私が忙しいとき、いつも資料をコピーして___。', '{"options":["もらいます","あげます","くれます","あります"],"translation":"Saat saya sibuk, Sato-san selalu membantu memfotokopikan materi untuk saya.","sentence_template":"佐藤さんは私が忙しいとき、いつも資料をコピーして[blank]。"}'::jsonb, '{"selected":"くれます"}'::jsonb, NULL, NULL, '佐藤さんは adalah pemberi bantuan kepada saya (私が), sehingga pola yang tepat adalah ～てくれます.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61dcf000-83e4-41d4-9362-79bc0cf68e7f', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 駅で切符の買い方が分からなかった外国人に、買い方を説明して___。', '{"options":["くれました","もらいました","きました","あげました"],"translation":"Saya menjelaskan cara membeli tiket kepada warga asing yang kebingungan di stasiun.","sentence_template":"駅で切符の買い方が分からなかった外国人に、買い方を説明して[blank]。"}'::jsonb, '{"selected":"あげました"}'::jsonb, NULL, NULL, 'Pembicara membantu orang lain -> 説明してあげました.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('19a23aaf-8894-45af-b91c-e53aca6a4cbc', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita singkat berikut. Bagaimana reaksi rekan kerja pembicara?', '{"options":[{"id":"opt_1","text":"Rekan-rekan di tempat kerja sangat senang menerima oleh-oleh dinas dari pembicara"},{"id":"opt_2","text":"Pembicara lupa membeli oleh-oleh saat dinas"},{"id":"opt_3","text":"Oleh-oleh yang dibeli pembicara tertinggal di kereta"},{"id":"opt_4","text":"Rekan kerja membelikan oleh-oleh untuk pembicara"}],"audio_text":"出張のお土産を買ってきたら、職場の皆がとても喜んでくれました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '喜んでくれました menunjukkan perasaan senang orang lain yang membuat pembicara ikut bersyukur.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73061de6-02f2-4181-a889-49befcc6fa12', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya dikenalkan kedai ramen yang enak oleh rekan kerja."', '{"romaji":"Watashi wa douryou ni oishii raamenya o shoukai shite moraimashita.","tokens":["紹介して","私は","あげました。","が","同僚に","もらいました。","美味しい","ラーメン屋を"],"target_translation":"Saya dikenalkan kedai ramen yang enak oleh rekan kerja."}'::jsonb, '["私は","同僚に","美味しい","ラーメン屋を","紹介して","もらいました。"]'::jsonb, NULL, NULL, '同僚に + 紹介してもらいました menyatakan pembicara menerima rekomendasi dari rekan kerja.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6fd1bcc5-0fb8-42e1-a7d6-4fb246a86cff', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 祖父は目が悪くなったので、私が新聞を読んで___。', '{"options":["もらっています","くれています","あげています","いっています"],"translation":"Karena penglihatan kakek melemah, saya membacakan koran untuknya.","sentence_template":"祖父は目が悪くなったので、私が新聞を読んで[blank]。"}'::jsonb, '{"selected":"あげています"}'::jsonb, NULL, NULL, '私が adalah pemberi bantuan kepada kakek -> 読んであげています.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb378d26-e6e8-4c1c-9f8f-78e9d30199a3', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanaka-san datang menjemput saya sampai ke stasiun."', '{"romaji":"Tanaka-san ga eki made mukae ni kite kuremashita.","display_text":"田中さんが駅まで迎えに来てくれました。","phonetic_breakdown":["ta-na-ka-san-ga","e-ki-ma-de","mu-ka-e-ni","ki-te","ku-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"田中さんが駅まで迎えに来てくれました。"}'::jsonb, NULL, NULL, '迎えに来てくれました mengungkapkan apresiasi karena Tanaka datang menjemput.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f86bab96-8062-46d8-9929-7b2d29e4cd6b', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan pengalaman berbelanja berikut. Apa yang dilakukan pegawai toko?', '{"options":[{"id":"opt_1","text":"Kamera yang dibeli pembicara tidak ada buku panduannya"},{"id":"opt_2","text":"Pembicara menerima penjelasan ramah dari pegawai toko tentang cara memakai kamera"},{"id":"opt_3","text":"Pegawai toko menolak menjelaskan fungsi kamera"},{"id":"opt_4","text":"Pembicara mengajari pegawai toko cara memakai kamera"}],"audio_text":"カメラの使い方が分からなかったので、店員さんに丁寧に教えてもらいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '店員さんに教えてもらいました berarti pembicara diajari oleh pegawai toko.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2475ad4b-00fc-496a-9593-bf7e1d499354', '5f4e5aaa-f1c7-439c-a72e-3569f9df1ab1', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Adik perempuan saya membantu menerima paket menggantikan saya."', '{"romaji":"Imouto ga watashi no kawari ni nimotsu o uketotte kuremashita.","tokens":["荷物を","に","くれました。","あげました。","代わりに","妹が","私の","受け取って"],"target_translation":"Adik perempuan saya membantu menerima paket menggantikan saya."}'::jsonb, '["妹が","私の","代わりに","荷物を","受け取って","くれました。"]'::jsonb, NULL, NULL, '代わりに berarti menggantikan; 妹が + 受け取ってくれました.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7724e32-c007-4db5-9ee1-8710c300b277', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan saran rekan kerja berikut. Mengapa perlu memesan tiket sekarang?', '{"options":[{"id":"opt_1","text":"Harga tiket pesawat bulan depan pasti akan turun"},{"id":"opt_2","text":"Dinas bulan depan akan menggunakan kereta api saja"},{"id":"opt_3","text":"Menyarankan memesan tiket pesawat dinas bulan depan sebelum harganya naik"},{"id":"opt_4","text":"Tiket pesawat dinas bulan depan sudah dipesan oleh kantor"}],"audio_text":"来月の出張の航空券、値段が上がる前に予約しておいたほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '予約しておいたほうがいい menyarankan pemesanan lebih awal sebagai persiapan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('133e917a-98df-4803-8bdb-4f18161f26ab', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan mencadangkan file penting terlebih dahulu."', '{"romaji":"Daiji na fairu wa bakkuappu o totte okimasu.","display_text":"大事なファイルはバックアップを取っておきます。","phonetic_breakdown":["dai-ji-na","fai-ru-wa","bak-ku-ap-pu-o","tot-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"大事なファイルはバックアップを取っておきます。"}'::jsonb, NULL, NULL, 'バックアップを取っておきます adalah tindakan antisipasi kehilangan data.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c115b000-7035-45d7-8b11-9da91f6dda94', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum tamu datang, saya akan menyalakan AC terlebih dahulu."', '{"romaji":"Okyakusan ga kuru mae ni eakon o tsukete okimasu.","tokens":["おきます。","つけます。","エアコンを","お客さんが","が","来る前に","つけて"],"target_translation":"Sebelum tamu datang, saya akan menyalakan AC terlebih dahulu."}'::jsonb, '["お客さんが","来る前に","エアコンを","つけて","おきます。"]'::jsonb, NULL, NULL, 'つけておきます mempersiapkan kenyamanan ruangan sebelum tamu tiba.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d47989c9-f289-47d6-8911-eeb5d60588b2', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 面接で聞かれそうな質問の答えを、あらかじめ___おきました。', '{"options":["考えて","考えた","考える","考え"],"translation":"Saya sudah memikirkan terlebih dahulu jawaban atas pertanyaan yang kemungkinan ditanyakan saat wawancara.","sentence_template":"面接で聞かれそうな質問の答えを、あらかじめ[blank]おきました。"}'::jsonb, '{"selected":"考えて"}'::jsonb, NULL, NULL, '考える -> 考えておきました.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('993c892f-703d-4613-9a72-c1ea0b068600', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan pesan di rumah berikut. Apa yang terjadi jika jendela dibiarkan terbuka?', '{"options":[{"id":"opt_1","text":"Serangga tidak pernah masuk lewat jendela"},{"id":"opt_2","text":"Jendela harus dibiarkan terbuka sepanjang malam"},{"id":"opt_3","text":"Pembicara sudah menutup semua jendela sejak pagi"},{"id":"opt_4","text":"Jika jendela dibiarkan terbuka serangga akan masuk, jadi tolong tutup saat sore"}],"audio_text":"窓を開けたままにしておくと虫が入りますから、夕方になったら閉めてくださいね。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '開けたままにしておく berarti membiarkan jendela dalam keadaan terbuka.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61e55e5d-1f60-4025-8435-7155c8ac7654', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Agar besok pagi bisa berangkat dengan lancar, saya menyiapkan tas terlebih dahulu."', '{"romaji":"Ashita no asa sumuuzu ni derareru you ni, kaban o junbi shite okimasu.","display_text":"明日の朝スムーズに出られるように、かばんを準備しておきます。","phonetic_breakdown":["a-shi-ta-no","a-sa","su-muu-zu-ni","de-ra-re-ru-you-ni","ka-ban-o","jun-bi-shi-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"明日の朝スムーズに出られるように、かばんを準備しておきます。"}'::jsonb, NULL, NULL, '準備しておきます menunjukkan persiapan malam sebelumnya.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ad42600-5bda-4503-af32-86b11167c256', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum menelepon, saya sudah merangkum isi pembicaraan terlebih dahulu."', '{"romaji":"Denwa o kakeru mae ni hanasu naiyou o matomete okimashita.","tokens":["おきました。","まとめます。","まとめて","電話を","かける前に","へ","話す内容を"],"target_translation":"Sebelum menelepon, saya sudah merangkum isi pembicaraan terlebih dahulu."}'::jsonb, '["電話を","かける前に","話す内容を","まとめて","おきました。"]'::jsonb, NULL, NULL, 'まとめる -> まとめておきました.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ab4fa8b-2232-4462-92d4-db7da03e9f35', '647161c2-7fb3-428c-b07b-d50c3c53d7b8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 使い終わったら、ホワイトボードをきれいに___おいてください。', '{"options":["消して","消す","消した","消し"],"translation":"Setelah selesai dipakai, tolong hapus papan tulis sampai bersih.","sentence_template":"使い終わったら、ホワイトボードをきれいに[blank]おいてください。"}'::jsonb, '{"selected":"消して"}'::jsonb, NULL, NULL, '消す -> 消しておいてください.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a4b9e59-eed6-4f4f-8e43-954383c26a89', '6725a578-30b6-408f-b571-fb82c71c292c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: すみませんが、この申請書の書き方を教えて___。', '{"options":["いただけませんか","おきます","あげませんか","あります"],"translation":"Maaf, maukah Anda mengajari saya cara mengisi formulir permohonan ini?","sentence_template":"すみませんが、この申請書の書き方を教えて[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, 'Pola ～ていただけませんか adalah permohonan paling sopan di tingkat N4.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3b8eb58-82e3-46a9-9613-a76798f02e26', '6725a578-30b6-408f-b571-fb82c71c292c', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan pengumuman persiapan rapat berikut. Bagaimana kondisi ruang rapat?', '{"options":[{"id":"opt_1","text":"Materi dan minuman sesuai jumlah peserta sudah disiapkan di ruang rapat"},{"id":"opt_2","text":"Ruang rapat belum dibersihkan sejak kemarin"},{"id":"opt_3","text":"Peserta harus menyiapkan materi dan minuman sendiri"},{"id":"opt_4","text":"Jumlah minuman di ruang rapat masih kurang"}],"audio_text":"会議室に人数分の資料と飲み物が用意してありますので、そのままお使いください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '用意してあります menunjukkan persiapan yang sudah sengaja dilakukan.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e3898776-b54d-44c6-a38a-dff223b0a7cd', '6725a578-30b6-408f-b571-fb82c71c292c', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam bulan ini harus menyerahkan surat keterangan domisili ke balai kota."', '{"romaji":"Kongetsuchuu ni juuminhyou o shiyakusho e teishutsu shinakereba narimasen.","tokens":["なりません。","が","住民票を","市役所へ","今月中に","提出しなければ","提出します。"],"target_translation":"Dalam bulan ini harus menyerahkan surat keterangan domisili ke balai kota."}'::jsonb, '["今月中に","住民票を","市役所へ","提出しなければ","なりません。"]'::jsonb, NULL, NULL, '～なければなりません menyatakan kewajiban resmi.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('30252184-d32c-4c11-b688-ce6ce6c8a554', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このカードを使えば、駅の売店でも買い物が___。', '{"options":["させます","できます","します","ありました"],"translation":"Jika memakai kartu ini, di kios stasiun pun bisa berbelanja.","sentence_template":"このカードを使えば、駅の売店でも買い物が[blank]。"}'::jsonb, '{"selected":"できます"}'::jsonb, NULL, NULL, '買い物する berubah menjadi bentuk potensial 買い物できます (bisa berbelanja).', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e83d5dee-646c-49f8-9166-a86ef28cfcbb', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Senior mengajari saya cara kerja dengan mudah dipahami."', '{"romaji":"Senpai ga wakariyasuku shigoto no yarikata o oshiete kuremashita.","display_text":"先輩が分かりやすく仕事のやり方を教えてくれました。","phonetic_breakdown":["sen-pai-ga","wa-ka-ri-ya-su-ku","shi-go-to-no","ya-ri-ka-ta-o","o-shi-e-te","ku-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先輩が分かりやすく仕事のやり方を教えてくれました。"}'::jsonb, NULL, NULL, '先輩が + 教えてくれました menekankan rasa syukur atas bantuan senior kepada pembicara.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c7c33313-969f-48fb-b464-fbb06d1b0ab7', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan nasihat berikut. Apa yang dianjurkan oleh pembicara?', '{"options":[{"id":"opt_1","text":"Menyarankan berolahraga ringan di luar rumah"},{"id":"opt_2","text":"Menyarankan untuk tidak memaksakan diri dan beristirahat di rumah karena demam belum turun"},{"id":"opt_3","text":"Menyarankan tetap masuk kantor meski demam"},{"id":"opt_4","text":"Mengatakan bahwa demam sudah sembuh total"}],"audio_text":"まだ熱が下がっていないようですから、今日は無理をせず家でゆっくり休んだほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '休んだほうがいい memberikan saran kesehatan yang jelas.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40605840-9a23-4d63-80f6-5a2e5de781ab', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 明日は朝から出張___、今夜のうちに荷造りを終わらせます。', '{"options":["のに","なので","ので","だので"],"translation":"Karena besok pagi ada dinas luar kota, saya akan menyelesaikan pengemasan barang malam ini.","sentence_template":"明日は朝から出張[blank]、今夜のうちに荷造りを終わらせます。"}'::jsonb, '{"selected":"なので"}'::jsonb, NULL, NULL, '出張 (kata benda) memerlukan な sebelum ので -> 出張なので.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('897b7d61-007b-45db-87c0-cde21436ccc6', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah tiba di bandara, tolong segera menelepon."', '{"romaji":"Kuukou ni tsuitara, sugu denwa o kakete kudasai.","tokens":["空港に","電話を","かけてください。","着くたら、","すぐ","着いたら、","が"],"target_translation":"Setelah tiba di bandara, tolong segera menelepon."}'::jsonb, '["空港に","着いたら、","すぐ","電話を","かけてください。"]'::jsonb, NULL, NULL, '着く -> 着いたら menyatakan urutan waktu ''begitu sampai''.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3bbc5f76-860f-41ab-8e89-89ee83efdd71', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan laporan kerja berikut. Apa yang sudah dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Reservasi ruang rapat baru akan dilakukan besok pagi"},{"id":"opt_2","text":"Tamu besok membatalkan kunjungan ke kantor"},{"id":"opt_3","text":"Reservasi ruang rapat dan penataan kursi untuk tamu besok sudah dibereskan sebelumnya"},{"id":"opt_4","text":"Pembicara meminta rekan kerja menata kursi besok"}],"audio_text":"明日のお客様のために、会議室の予約と席の配置はもう済ませておきました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '済ませておきました menggunakan ～ておく untuk menyatakan persiapan telah selesai lebih awal.', 9, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4c3a463b-5d93-4fd2-8617-ce59461040a9', '6725a578-30b6-408f-b571-fb82c71c292c', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan segera mengonfirmasi kepada penanggung jawab, mohon tunggu sebentar."', '{"romaji":"Tadaima tantousha ni kakunin itashimasu node, shoushou omachi kudasai.","display_text":"ただいま担当者に確認いたしますので、少々お待ちください。","phonetic_breakdown":["ta-da-i-ma","tan-tou-sha-ni","ka-ku-nin","i-ta-shi-ma-su-no-de","shou-shou","o-ma-chi","ku-da-sai"]}'::jsonb, '{"expected_transcript":"ただいま担当者に確認いたしますので、少々お待ちください。"}'::jsonb, NULL, NULL, '確認いたします adalah bentuk Kenjougo yang mencerminkan kesiapan komunikasi bisnis N4.', 10, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00ee3499-5637-49bd-884f-9c67075a1887', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang berarti ''hujan berhenti / reda'': 雨が___、外へ散歩に行きましょう。', '{"options":["食べたら","読んだら","やんだら","書いたら"],"translation":"Kalau hujan sudah reda, mari kita pergi jalan-jalan ke luar.","sentence_template":"雨が[blank]、外へ散歩に行きましょう。"}'::jsonb, '{"selected":"やんだら"}'::jsonb, NULL, NULL, '雨がやみます berarti hujan berhenti/reda -> bentuk たら: やんだら.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('33930d13-9b47-44bc-be28-d0580c9fb04c', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata rencana akhir pekan: 今度の___に友達と京都へ旅行します。', '{"options":["残業","遅刻","欠席","連休"],"translation":"Pada libur panjang nanti, saya akan berwisata ke Kyoto bersama teman.","sentence_template":"今度の[blank]に友達と京都へ旅行します。"}'::jsonb, '{"selected":"連休"}'::jsonb, NULL, NULL, '連休 (renkyuu) berarti hari libur berturut-turut / libur panjang.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('62894fa3-d6c2-4cb9-a3d5-5f09ba103c93', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja ini. Apa yang akan mereka lakukan kalau hari Minggu cerah?', '{"options":[{"id":"opt_1","text":"Mengadakan barbekyu bersama di taman"},{"id":"opt_2","text":"Menonton film di bioskop"},{"id":"opt_3","text":"Belajar bahasa Jepang di perpustakaan"},{"id":"opt_4","text":"Berbelanja di pusat perbelanjaan"}],"audio_text":"日曜日、天気がよかったら、みんなで公園でバーベキューをしませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '天気がよかったら (kalau cuacanya bagus) + 公園でバーベキュー (barbekyu di taman).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ab814d8-67bc-47e7-9a94-8f77c0457449', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'listening', 'listening_choice', 'Dengarkan instruksi kerja ini. Apa yang harus dilakukan setelah selesai membersihkan mesin?', '{"options":[{"id":"opt_1","text":"Langsung pulang tanpa melapor"},{"id":"opt_2","text":"Mematikan sakelar dan melapor setelah pembersihan selesai"},{"id":"opt_3","text":"Menyalakan mesin kembali selama lima menit"},{"id":"opt_4","text":"Memindahkan mesin ke gudang"}],"audio_text":"機械の掃除が終わったら、スイッチを切って報告してください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '掃除が終わったら (setelah bersih-bersih selesai) + スイッチを切って報告 (matikan sakelar dan lapor).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('830c6b6c-0768-4623-a82b-cc5c225ab6b6', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah sampai di stasiun, tolong telepon saya."', '{"romaji":"Eki ni tsuitara, denwa o kudasai.","tokens":["電話を","着きます、","駅に","ください。","着いたら、","食べたら、"],"target_translation":"Kalau sudah sampai di stasiun, tolong telepon saya."}'::jsonb, '["駅に","着いたら、","電話を","ください。"]'::jsonb, NULL, NULL, '着きます (tiba) -> Bentuk TA: 着いた + ら = 着いたら (jika/setelah tiba).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9d2a081-74bb-4853-aec3-95dda028037b', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada waktu luang, saya ingin pergi ke pemandian air panas."', '{"romaji":"Jikan ga attara, onsen e ikitai desu.","display_text":"時間があったら、温泉へ行きたいです。","phonetic_breakdown":["ji-kan","ga","at-ta-ra","on-sen","e","i-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"時間があったら、温泉へ行きたいです。"}'::jsonb, NULL, NULL, 'あります -> あった + ら = あったら (kalau ada).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bc19e857-81fc-4d6e-a5bd-76e3e5b094e2', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 空港に___したら、すぐ家族に連絡します。', '{"options":["欠席","到着","出発","中止"],"translation":"Setelah tiba di bandara, saya akan segera menghubungi keluarga.","sentence_template":"空港に[blank]したら、すぐ家族に連絡します。"}'::jsonb, '{"selected":"到着"}'::jsonb, NULL, NULL, '到着する (touchaku suru, tiba) -> 到着したら berarti ''setelah tiba''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b81b68b-802e-42a2-9887-abbd2274d2f9', '6752f180-a7c5-4bc8-b6cf-9fd7f1e43ec2', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan rencana akhir pekan berikut. Apa yang akan dilakukan jika turun hujan?', '{"options":[{"id":"opt_1","text":"Acara barbeku hari ini dibatalkan karena hujan"},{"id":"opt_2","text":"Jika cerah, barbeku akan dipindahkan ke dalam ruangan"},{"id":"opt_3","text":"Jika besok turun hujan, acara barbeku akan dipindahkan ke dalam ruangan"},{"id":"opt_4","text":"Acara barbeku pasti dilaksanakan di luar ruangan meski hujan"}],"audio_text":"もし雨が降ったら、明日のバーベキューは室内に変更しましょう。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'もし～たら menyatakan pengandaian bersyarat.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1be18053-0f79-4dd4-aea7-b38d8b2d6dcd', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 明日___、公園でピクニックをしましょう。', '{"options":["晴れてら","晴れるたら","晴れたら","晴れた"],"translation":"Kalau besok cerah, mari piknik di taman.","sentence_template":"明日[blank]、公園でピクニックをしましょう。"}'::jsonb, '{"selected":"晴れたら"}'::jsonb, NULL, NULL, '晴れる (kelompok 2) -> 晴れた -> 晴れたら.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bc05106-9687-40e1-a541-02227a5bdac3', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この交差点を右に___、左側に郵便局が見えます。', '{"options":["曲がってら","曲がったら","曲がるたら","曲がりたら"],"translation":"Setelah belok kanan di perempatan ini, kantor pos terlihat di sisi kiri.","sentence_template":"この交差点を右に[blank]、左側に郵便局が見えます。"}'::jsonb, '{"selected":"曲がったら"}'::jsonb, NULL, NULL, '曲がる -> 曲がった -> 曲がったら umum dipakai dalam petunjuk arah.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a2880dd7-178a-4146-b309-5c0c355b8fa2', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan arahan staf balai kota berikut. Apa yang harus dilakukan setelah selesai mengisi?', '{"options":[{"id":"opt_1","text":"Formulir harus diambil terlebih dahulu di loket nomor tiga"},{"id":"opt_2","text":"Pengisian formulir dilakukan di depan loket nomor satu"},{"id":"opt_3","text":"Setelah selesai mengisi formulir, harap serahkan ke loket nomor tiga"},{"id":"opt_4","text":"Loket nomor tiga sedang tidak menerima formulir"}],"audio_text":"書類の記入が終わったら、三番の窓口へ提出してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '終わったら menunjukkan langkah berikutnya dalam prosedur.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7564e3f-8b12-4760-a379-96dbe6fb6b87', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau demamnya tidak turun, silakan datang lagi ke rumah sakit."', '{"romaji":"Netsu ga sagaranakattara, mou ichido byouin e kite kudasai.","tokens":["を","下がらないたら、","下がらなかったら、","もう一度","熱が","病院へ","来てください。"],"target_translation":"Kalau demamnya tidak turun, silakan datang lagi ke rumah sakit."}'::jsonb, '["熱が","下がらなかったら、","もう一度","病院へ","来てください。"]'::jsonb, NULL, NULL, 'Bentuk negatif: 下がらない -> 下がらなかったら.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d0a86dc-2ccd-4e64-9f8e-bef992b00e85', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 明日が___、映画を見に行きませんか。', '{"options":["暇だったら","暇たら","暇なったら","暇かったら"],"translation":"Kalau besok senggang, maukah pergi menonton film?","sentence_template":"明日が[blank]、映画を見に行きませんか。"}'::jsonb, '{"selected":"暇だったら"}'::jsonb, NULL, NULL, 'Kata sifat な dan kata benda + だったら (暇 -> 暇だったら).', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b4f7eee-2392-4ebf-b4d9-a333ccae1d64', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah masuk musim semi, saya akan pindah ke apartemen baru."', '{"romaji":"Haru ni nattara, atarashii apaato ni hikkoshimasu.","display_text":"春になったら、新しいアパートに引っ越します。","phonetic_breakdown":["ha-ru-ni","nat-ta-ra","a-ta-ra-shii","a-paa-to-ni","hik-ko-shi-ma-su"]}'::jsonb, '{"expected_transcript":"春になったら、新しいアパートに引っ越します。"}'::jsonb, NULL, NULL, 'なる -> なった -> なったら menyatakan waktu yang akan tiba.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54b2b173-0a64-4d25-92a0-9c6704d16a31', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'listening', 'listening_choice', 'Dengarkan arahan keselamatan berikut. Apa yang harus dilakukan jika paspor hilang?', '{"options":[{"id":"opt_1","text":"Jika paspor hilang, cukup menunggu sampai ditemukan"},{"id":"opt_2","text":"Paspor harus disimpan di kantor polisi selama di Jepang"},{"id":"opt_3","text":"Kedutaan besar tidak menangani kasus paspor hilang"},{"id":"opt_4","text":"Jika kehilangan paspor, segera hubungi kedutaan besar dan polisi"}],"audio_text":"もしパスポートをなくしたら、すぐに大使館と警察へ連絡してください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'なくしたら berarti ''jika menghilangkan/kehilangan''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8c766741-c6e0-493c-9a14-39550bebca7d', '6883817e-cb8f-4d48-a531-0505ea919191', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Saat kereta datang, mari menunggu di belakang garis kuning."', '{"romaji":"Densha ga kitara, kiiroi sen no uchigawa de machimashou.","tokens":["黄色い線の","を","電車が","待ちましょう。","来たら、","来るたら、","内側で"],"target_translation":"Saat kereta datang, mari menunggu di belakang garis kuning."}'::jsonb, '["電車が","来たら、","黄色い線の","内側で","待ちましょう。"]'::jsonb, NULL, NULL, '来る -> 来た -> 来たら.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('641a72fa-ba5e-4d47-9f53-4b8a727c995e', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah pukul lima, kita bisa pulang."', '{"romaji":"Goji ni nattara, kaette mo ii desu yo.","display_text":"五時になったら、帰ってもいいですよ。","phonetic_breakdown":["go-ji","ni","nat-ta-ra","ka-et-te","mo","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"五時になったら、帰ってもいいですよ。"}'::jsonb, NULL, NULL, 'なります -> なった + ら = なったら (kalau sudah menjadi jam 5).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90a4949d-8e83-44d2-917f-5eff665de10c', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau terjadi kesalahan, tolong segera beri tahu saya."', '{"romaji":"Machigai ga attara, sugu oshiete kudasai.","display_text":"間違いがあったら、すぐ教えてください。","phonetic_breakdown":["ma-chi-ga-i","ga","at-ta-ra","su-gu","o-shi-e-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"間違いがあったら、すぐ教えてください。"}'::jsonb, NULL, NULL, '間違いがあったら (jika ada kesalahan) adalah frasa wajib dalam pemeriksaan dokumen di kantor.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4f88a07-3a65-4a55-aa9a-deb10740b3a7', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah pulang ke Indonesia, saya ingin membuka restoran Jepang."', '{"romaji":"Indoneshia e kaettara, Nihon ryouri no mise o hirakitai desu.","display_text":"インドネシアへ帰ったら、日本料理の店を開きたいです。","phonetic_breakdown":["in-do-ne-shi-a","e","ka-et-ta-ra","ni-hon","ryo-u-ri","no","mi-se","o","hi-ra-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"インドネシアへ帰ったら、日本料理の店を開きたいです。"}'::jsonb, NULL, NULL, '帰ります -> 帰った + ら = 帰ったら menyatakan rencana setelah pulang ke tanah air.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5e94c8b2-5412-4c70-a782-7e82089a0468', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau musim semi tiba, bunga sakura akan mekar."', '{"romaji":"Haru ni nattara, sakura ga sakimasu.","tokens":["なったら、","雪が","春に","なります、","桜が","咲きます。"],"target_translation":"Kalau musim semi tiba, bunga sakura akan mekar."}'::jsonb, '["春に","なったら、","桜が","咲きます。"]'::jsonb, NULL, NULL, '春になったら (kalau musim semi tiba) + 桜が咲きます (sakura mekar).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('939a383b-00fc-4435-a5db-16d6faae9531', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau makan siang selesai, ayo kita rapat sebentar."', '{"romaji":"Hirugohan o tabeowattara, sukoshi uchiawase o shimashou.","tokens":["少し","食べ終わったら、","打ち合わせをしましょう。","寝ましょう。","昼ご飯を","食べます、"],"target_translation":"Kalau makan siang selesai, ayo kita rapat sebentar."}'::jsonb, '["昼ご飯を","食べ終わったら、","少し","打ち合わせをしましょう。"]'::jsonb, NULL, NULL, '打ち合わせ (uchiawase) adalah rapat singkat/koordinasi; 食べ終わったら berarti setelah selesai makan.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('80ab7bf2-8f24-40bc-9080-c8334089a5f8', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau tubuhmu tidak enak, jangan memaksakan diri."', '{"romaji":"Guai ga warukattara, muri o shinaide kudasai.","tokens":["具合が","してください。","悪いったら、","悪かったら、","しないでください。","無理を"],"target_translation":"Kalau tubuhmu tidak enak, jangan memaksakan diri."}'::jsonb, '["具合が","悪かったら、","無理を","しないでください。"]'::jsonb, NULL, NULL, '悪い (Adjektiva-I) -> 悪かった + ら = 悪かったら.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c939b894-cbf6-46d9-bb41-e60a89b33eea', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada waktu, saya ingin pergi berwisata ke Kyoto."', '{"romaji":"Jikan ga attara, Kyouto e ryokou ni ikitai desu.","display_text":"時間があったら、京都へ旅行に行きたいです。","phonetic_breakdown":["ji-kan-ga","at-ta-ra","kyou-to-e","ryo-kou-ni","i-ki-tai-de-su"]}'::jsonb, '{"expected_transcript":"時間があったら、京都へ旅行に行きたいです。"}'::jsonb, NULL, NULL, 'ある -> あった -> あったら sangat sering dipakai untuk menyatakan harapan bersyarat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef4a99fb-69f5-4cc3-8e87-d62c3299d685', '6889b273-7a2f-47ca-a32c-a3e2ae26e22f', 'd1000019-0000-0000-0000-000000000005', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau ada kata yang tidak dipahami, silakan cari di kamus ini."', '{"romaji":"Wakaranai kotoba ga attara, kono jisho de shirabete kudasai.","tokens":["あるたら、","言葉が","調べてください。","を","あったら、","この辞書で","分からない"],"target_translation":"Kalau ada kata yang tidak dipahami, silakan cari di kamus ini."}'::jsonb, '["分からない","言葉が","あったら、","この辞書で","調べてください。"]'::jsonb, NULL, NULL, 'あったら membentuk syarat sebelum kalimat instruksi.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0720feb6-b239-4f1c-85f3-4b8543f7738f', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan menulis catatan dulu supaya tidak lupa."', '{"romaji":"Wasurenai you ni, memo ni kaite okimasu.","display_text":"忘れないように、メモに書いておきます。","phonetic_breakdown":["wa-su-re-na-i","yo-u","ni","me-mo","ni","ka-i-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"忘れないように、メモに書いておきます。"}'::jsonb, NULL, NULL, '忘れないように (supaya tidak lupa) sangat sering berpasangan dengan 書いておきます.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6ee1c172-d4cd-427b-b1dd-43d568b6d0cc', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum berangkat, saya sudah menutup semua jendela."', '{"romaji":"Dekakeru mae ni, mado o zenbu shimete okimashita.","display_text":"出かける前に、窓を全部閉めておきました。","phonetic_breakdown":["de-ka-ke-ru","ma-e","ni","ma-do","o","zen-bu","shi-me-te","o-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"出かける前に、窓を全部閉めておきました。"}'::jsonb, NULL, NULL, '閉めておきました menunjukkan tindakan pencegahan/persiapan sebelum meninggalkan rumah.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2af82936-42dc-48f5-85e2-504ddcd858c5', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tolong siapkan paspor dan tiket pesawat sejak malam ini."', '{"romaji":"Konya no uchi ni, pasupooto to koukuuken o youi shite oite kudasai.","display_text":"今夜のうちに、パスポートと航空券を用意しておいてください。","phonetic_breakdown":["kon-ya","no","u-chi","ni","pa-su-po-o-to","to","ko-u-ku-u-ken","o","yo-u-i","shi-te","o-i-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"今夜のうちに、パスポートと航空券を用意しておいてください。"}'::jsonb, NULL, NULL, '航空券 (koukuuken) berarti tiket pesawat; 用意しておいてください meminta menyiapkan sejak malam ini.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9d3abdd-97c8-4219-9ca0-4e27cc1c552b', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum ujian dimulai, saya sudah menajamkan pensil."', '{"romaji":"Shiken no mae ni, enpitsu o kezutte okimashita.","tokens":["試験の前に、","おきました。","忘れました。","削ります。","鉛筆を","削って"],"target_translation":"Sebelum ujian dimulai, saya sudah menajamkan pensil."}'::jsonb, '["試験の前に、","鉛筆を","削って","おきました。"]'::jsonb, NULL, NULL, '削ります (meraut/menajamkan) -> 削っておきました.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('30c3d7ff-bf51-48f5-9cb4-a8b77c5840b9', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Biar saya saja yang membersihkan ruang rapat dulu."', '{"romaji":"Watashi ga saki ni kaigishitsu o souji shite okimasu ne.","tokens":["先に","掃除して","私が","掃除します。","おきますね。","帰ります。","会議室を"],"target_translation":"Biar saya saja yang membersihkan ruang rapat dulu."}'::jsonb, '["私が","先に","会議室を","掃除して","おきますね。"]'::jsonb, NULL, NULL, '先に...しておきますね adalah ungkapan proaktif yang sangat dihargai di lingkungan kerja Jepang.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61e3500b-3a68-443d-b405-529005766474', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Tolong biarkan lampu lorong tetap menyala."', '{"romaji":"Rouka no denki wa sono mama tsukete oite kudasai.","tokens":["廊下の電気は","あります。","おいてください。","そのまま","つけて","消して"],"target_translation":"Tolong biarkan lampu lorong tetap menyala."}'::jsonb, '["廊下の電気は","そのまま","つけて","おいてください。"]'::jsonb, NULL, NULL, 'そのままつけておいてください berarti tolong biarkan tetap menyala.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f2d5bea-bfd7-4911-b6d0-570341348207', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum berangkat, saya akan mengecek prakiraan cuaca terlebih dahulu."', '{"romaji":"Shuppatsu suru mae ni, tenki yohou o kakunin shite okimasu.","display_text":"出発する前に、天気予報を確認しておきます。","phonetic_breakdown":["shup-pa-tsu-su-ru","ma-e-ni","ten-ki-yo-hou-o","ka-ku-nin-shi-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"出発する前に、天気予報を確認しておきます。"}'::jsonb, NULL, NULL, '確認しておきます adalah kebiasaan persiapan sebelum bepergian.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b28f947-396f-4347-bbfd-68e7ba7e2c5f', '74788deb-130c-46d6-a312-f152431b6156', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Karena tamu akan datang, mari kita bereskan ruangan terlebih dahulu."', '{"romaji":"Okyakusan ga kuru node, heya o katazukete okimashou.","tokens":["が","おきましょう。","片付けて","お客さんが","部屋を","片付けます。","来るので、"],"target_translation":"Karena tamu akan datang, mari kita bereskan ruangan terlebih dahulu."}'::jsonb, '["お客さんが","来るので、","部屋を","片付けて","おきましょう。"]'::jsonb, NULL, NULL, '片付けておきましょう mengajak melakukan persiapan merapikan ruangan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b576e0cf-1e6c-40c7-bd6e-85b2d3a49aa1', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 台風が近づいている___、午後の授業は休講になりました。', '{"options":["のに","なので","だので","ので"],"translation":"Karena topan sedang mendekat, kelas sore diliburkan.","sentence_template":"台風が近づいている[blank]、午後の授業は休講になりました。"}'::jsonb, '{"selected":"ので"}'::jsonb, NULL, NULL, '近づいている (bentuk biasa kata kerja) langsung diikuti ので.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6ff78134-ead3-4e00-a898-1d43d0e007a7', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼は日本語が___ので、通訳を任されています。', '{"options":["上手だ","上手","上手い","上手な"],"translation":"Karena bahasa Jepangnya mahir, dia dipercaya menjadi penerjemah lisan.","sentence_template":"彼は日本語が[blank]ので、通訳を任されています。"}'::jsonb, '{"selected":"上手な"}'::jsonb, NULL, NULL, '上手 adalah kata sifat な, sehingga menjadi 上手なので.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('83adf7cc-d06c-4935-9685-3395be426ecc', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan jawaban telepon kantor berikut. Mengapa pembicara tidak bisa berbicara lama sekarang?', '{"options":[{"id":"opt_1","text":"Saat ini sedang rapat sehingga pembicara akan menelepon balik nanti"},{"id":"opt_2","text":"Nomor telepon yang dihubungi salah sambung"},{"id":"opt_3","text":"Pembicara meminta lawan bicara datang ke ruang rapat"},{"id":"opt_4","text":"Rapat baru saja selesai sehingga bisa berbicara sekarang"}],"audio_text":"すみません、今ちょうど会議中なので、後ほど折り返しお電話いたします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '会議中 (kata benda) + なので menyampaikan alasan dengan sangat sopan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('91c48cb2-a6d2-480a-9415-453ff102da24', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena hujan turun deras, pertandingan dibatalkan."', '{"romaji":"Ame ga hageshiku futte iru node, shiai wa chuushi desu.","tokens":["いるので、","降って","中止です。","降ってなので、","試合は","激しく","へ","雨が"],"target_translation":"Karena hujan turun deras, pertandingan dibatalkan."}'::jsonb, '["雨が","激しく","降って","いるので、","試合は","中止です。"]'::jsonb, NULL, NULL, '降っている + ので menyatakan sebab-akibat faktual.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eb35265f-bb17-46e5-9b60-54c79f65544c', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この町は静か___、勉強に集中できます。', '{"options":["ので","にので","なので","だので"],"translation":"Karena kota ini tenang, saya bisa berkonsentrasi belajar.","sentence_template":"この町は静か[blank]、勉強に集中できます。"}'::jsonb, '{"selected":"なので"}'::jsonb, NULL, NULL, '静か (kata sifat な) memerlukan な sebelum ので -> 静かなので.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53546898-d51a-4333-a370-1a4a5de62f11', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ada barang yang tertinggal, saya kembali sebentar ya."', '{"romaji":"Wasuremono o shita node, chotto modotte kimasu.","display_text":"忘れ物をしたので、ちょっと戻ってきます。","phonetic_breakdown":["wa-su-re-mo-no-o","shi-ta-no-de","chot-to","mo-dot-te-ki-ma-su"]}'::jsonb, '{"expected_transcript":"忘れ物をしたので、ちょっと戻ってきます。"}'::jsonb, NULL, NULL, 'した (bentuk lampau biasa) langsung diikuti ので.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea0f6377-a6ba-4844-b145-9701dd9628ab', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan ulasan tempat makan berikut. Mengapa perlu reservasi saat akhir pekan?', '{"options":[{"id":"opt_1","text":"Restoran ini tidak menerima reservasi di akhir pekan"},{"id":"opt_2","text":"Restoran ini populer sehingga saat akhir pekan sering tidak bisa masuk tanpa reservasi"},{"id":"opt_3","text":"Restoran ini tutup setiap akhir pekan"},{"id":"opt_4","text":"Restoran ini selalu sepi pengunjung di akhir pekan"}],"audio_text":"このレストランは人気があるので、週末は予約しないと入れないことが多いです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '人気があるので menjelaskan alasan ramainya restoran.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('967812dc-6a8e-452c-80aa-2aa3a7cf2525', '748c991e-b8af-43d7-b1c5-9a5ab009fec7', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena barangnya terlalu besar, saya mengirimkannya lewat jasa kurir."', '{"romaji":"Nimotsu ga ookisugiru node, takuhaibin de okurimashita.","tokens":["大きすぎる","荷物が","が","送りました。","ので、","宅配便で","大きすぎるな"],"target_translation":"Karena barangnya terlalu besar, saya mengirimkannya lewat jasa kurir."}'::jsonb, '["荷物が","大きすぎる","ので、","宅配便で","送りました。"]'::jsonb, NULL, NULL, '大きすぎる adalah kata kerja bentuk biasa, langsung diikuti ので.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6fe7f9d-dd94-4eaa-85bc-f9b22e8233b9', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bisa memasak masakan Indonesia."', '{"romaji":"Watashi wa Indoneshia ryouri ga tsukuremasu.","display_text":"私はインドネシア料理が作れます。","phonetic_breakdown":["wa-ta-shi","wa","in-do-ne-shi-a","ryo-u-ri","ga","tsu-ku-re-ma-su"]}'::jsonb, '{"expected_transcript":"私はインドネシア料理が作れます。"}'::jsonb, NULL, NULL, '作ります (membuat) -> 作れます (bisa membuat/memasak).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7ecf4708-ef9d-4fa6-bf5f-513ff33d6cb1', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah di sini bisa menggunakan kartu transportasi IC?"', '{"romaji":"Koko de wa ai-shii kaado ga tsukaemasu ka.","display_text":"ここではICカードが使えますか。","phonetic_breakdown":["ko-ko","de","wa","a-i-shi-i","ka-a-do","ga","tsu-ka-e-ma-su","ka"]}'::jsonb, '{"expected_transcript":"ここではICカードが使えますか。"}'::jsonb, NULL, NULL, '使います (menggunakan) -> 使えます (bisa digunakan).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0886176a-c337-4ee9-acf9-6fd3d23b4ce0', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena terlalu sibuk, hari ini saya tidak bisa istirahat."', '{"romaji":"Isogashisugite, kyou wa yasumemasen.","display_text":"忙しすぎて、今日は休めません。","phonetic_breakdown":["i-so-ga-shi-su-gi-te","kyo-u","wa","ya-su-me-ma-sen"]}'::jsonb, '{"expected_transcript":"忙しすぎて、今日は休めません。"}'::jsonb, NULL, NULL, '休みます -> 休めます -> 休めません (tidak bisa beristirahat).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6aca2fa3-0389-416a-b26b-4e2cc58db47b', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa mengendarai sepeda dan sepeda motor."', '{"romaji":"Jitensha mo baiku mo unten dekimasu.","tokens":["運転できます。","歩けます。","運転します。","バイクも","自転車も"],"target_translation":"Saya bisa mengendarai sepeda dan sepeda motor."}'::jsonb, '["自転車も","バイクも","運転できます。"]'::jsonb, NULL, NULL, '運転します (Grup 3) bentuk potensialnya adalah 運転できます.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54ab2a04-34a0-4fdf-8d58-b9f7dab24665', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Di perpustakaan ini kita bisa meminjam lima buku."', '{"romaji":"Kono toshokan de wa hon ga gosatsu kariraremasu.","tokens":["本が","借りられます。","貸せます。","借ります。","五冊","この図書館では"],"target_translation":"Di perpustakaan ini kita bisa meminjam lima buku."}'::jsonb, '["この図書館では","本が","五冊","借りられます。"]'::jsonb, NULL, NULL, '借ります (meminjam, Grup 2) -> 借りられます (bisa meminjam).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('151f7b1e-1130-455f-a262-fc01ba929513', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Karena suaranya kecil, saya tidak bisa mendengar dengan baik."', '{"romaji":"Koe ga chiisai node, yoku kikemasen.","tokens":["聞けません。","聞きます。","声が小さいので、","話せません。","よく"],"target_translation":"Karena suaranya kecil, saya tidak bisa mendengar dengan baik."}'::jsonb, '["声が小さいので、","よく","聞けません。"]'::jsonb, NULL, NULL, '聞きます -> 聞けます -> 聞けません (tidak bisa mendengar/menyimak).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b444a047-c500-416a-9297-c6deab77e51a', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bisa berbicara bahasa Inggris dan bahasa Jepang sedikit."', '{"romaji":"Watashi wa Eigo to Nihongo ga sukoshi hanasemasu.","display_text":"私は英語と日本語が少し話せます。","phonetic_breakdown":["wa-ta-shi-wa","ei-go-to","ni-hon-go-ga","su-ko-shi","ha-na-se-ma-su"]}'::jsonb, '{"expected_transcript":"私は英語と日本語が少し話せます。"}'::jsonb, NULL, NULL, '話す -> 話せる; partikel が digunakan untuk kemampuan bahasa.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('276da81e-5c63-422c-9d5f-09d126fc9176', '74ff2c80-f8bf-4e06-81bd-7a4905d3f0a1', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Di perpustakaan ini bisa belajar di ruangan yang tenang."', '{"romaji":"Kono toshokan de wa shizuka na heya de benkyou dekimasu.","tokens":["勉強できます。","この","図書館では","静かな","を","部屋で","勉強します。"],"target_translation":"Di perpustakaan ini bisa belajar di ruangan yang tenang."}'::jsonb, '["この","図書館では","静かな","部屋で","勉強できます。"]'::jsonb, NULL, NULL, 'Kata kerja する berubah menjadi できる untuk bentuk potensial.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('384e0f1b-25ae-49e8-b233-42ca49c06a1f', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Anda berkenan memeriksa dokumen ini?"', '{"romaji":"Kono shiryou o chekku shite itadakemasen ka.","display_text":"この資料をチェックしていただけませんか。","phonetic_breakdown":["ko-no","shi-ryo-u","o","chek-ku","shi-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"この資料をチェックしていただけませんか。"}'::jsonb, NULL, NULL, 'チェックします adalah verba Grup 3, bentuk TE-nya チェックして + いただけませんか.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23f58b70-cde3-4860-af96-6d03c9ef43eb', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, maukah Anda tolong mengambilkan foto?"', '{"romaji":"Sumimasen ga, shashin o totte itadakemasen ka.","display_text":"すみませんが、写真を撮っていただけませんか。","phonetic_breakdown":["su-mi-ma-sen","ga","sha-shin","o","tot-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、写真を撮っていただけませんか。"}'::jsonb, NULL, NULL, '写真を撮ります -> 写真を撮って + いただけませんか digunakan saat meminta orang lain mengambilkan foto secara sopan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b8d7994-308c-4835-9006-3997ef1c838c', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bersediakah Anda mengajari saya cara menggunakan mesin ini?"', '{"romaji":"Kono kikai no tsukaikata o oshiete itadakemasen ka.","display_text":"この機械の使い方を教えていただけませんか。","phonetic_breakdown":["ko-no","ki-ka-i","no","tsu-ka-i-ka-ta","o","o-shi-e-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"この機械の使い方を教えていただけませんか。"}'::jsonb, NULL, NULL, '使い方 (tsukaikata) berarti cara penggunaan; 教えます -> 教えて.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('570ab995-9733-4575-ac00-f3f99e1641da', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda memberitahukan nomor telepon cabang Osaka?"', '{"romaji":"Oosaka shiten no denwa bangou o oshiete itadakemasen ka.","tokens":["大阪支店の","知って","いただけませんか。","教えて","聞きます","電話番号を"],"target_translation":"Bersediakah Anda memberitahukan nomor telepon cabang Osaka?"}'::jsonb, '["大阪支店の","電話番号を","教えて","いただけませんか。"]'::jsonb, NULL, NULL, 'Urutan alami: [cabang Osaka] + [nomor telepon] + を + 教えて + いただけませんか.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e530715e-ffa8-4db1-ae50-44444a6127b1', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maaf, bersediakah Anda mengulanginya sekali lagi?"', '{"romaji":"Sumimasen ga, mou ichido itte itadakemasen ka.","tokens":["言って","いただけませんか。","言います","聞いて","すみませんが、","もう一度"],"target_translation":"Maaf, bersediakah Anda mengulanginya sekali lagi?"}'::jsonb, '["すみませんが、","もう一度","言って","いただけませんか。"]'::jsonb, NULL, NULL, '言います (mengatakan) -> Bentuk TE: 言って + いただけませんか.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b513f002-b6d1-4929-918c-da2ed447a9ee', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda membawakan kotak ini ke ruang rapat?"', '{"romaji":"Kono hako o kaigishitsu made hakonde itadakemasen ka.","tokens":["いただけませんか。","置きます","運んで","会議室まで","この箱を","運びて"],"target_translation":"Bersediakah Anda membawakan kotak ini ke ruang rapat?"}'::jsonb, '["この箱を","会議室まで","運んで","いただけませんか。"]'::jsonb, NULL, NULL, '運びます (membawa/mengangkut) berubah menjadi 運んで pada bentuk TE.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c1e6005-0fce-41cb-83e7-846abea55718', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, maukah Anda memfotokopi dokumen ini?"', '{"romaji":"Sumimasen ga, kono shorui o kopii shite itadakemasen ka.","display_text":"すみませんが、この書類をコピーしていただけませんか。","phonetic_breakdown":["su-mi-ma-sen-ga","ko-no","sho-ru-i-o","ko-pii-shi-te","i-ta-da-ke-ma-sen-ka"]}'::jsonb, '{"expected_transcript":"すみませんが、この書類をコピーしていただけませんか。"}'::jsonb, NULL, NULL, 'Pola コピーしていただけませんか sangat umum dipakai saat meminta bantuan administrasi di kantor Jepang.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a98a66d4-4b61-477e-b4c1-7330ec2a7801', '7629bf0c-ab25-4754-993a-7787e433d09f', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maaf mengganggu di tengah kesibukan Anda, maukah Anda menandatanganinya?"', '{"romaji":"Oisogashii tokoro osoreirimasu ga, sain shite itadakemasen ka.","tokens":["でも","お忙しいところ","サインしてあげます。","サインして","いただけませんか。","恐れ入りますが、"],"target_translation":"Maaf mengganggu di tengah kesibukan Anda, maukah Anda menandatanganinya?"}'::jsonb, '["お忙しいところ","恐れ入りますが、","サインして","いただけませんか。"]'::jsonb, NULL, NULL, 'Frasa お忙しいところ恐れ入りますが memperhalus permohonan kepada atasan atau klien.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bffbe9d-3d22-440d-b9b2-2ad4da10bdce', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Ubah 提出します (mengumpulkan) ke pola keharusan: 明日までにこの書類を___。', '{"options":["提出してなりません","提出したなりません","提出しなければなりません","提出しますなりません"],"translation":"Saya harus mengumpulkan dokumen ini paling lambat besok.","sentence_template":"明日までにこの書類を[blank]。"}'::jsonb, '{"selected":"提出しなければなりません"}'::jsonb, NULL, NULL, 'Pola keharusan: ubah verba ke bentuk NAI (提出しない), buang い, lalu tambah ければなりません.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a668c90-2695-4e48-9749-3d126424a103', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Pilih konjugasi bentuk NAI yang tepat dari 行きます: 明日は八時に会社へ___なりません。', '{"options":["行ってければ","行きなければ","行くければ","行かなければ"],"translation":"Besok saya harus pergi ke kantor pukul delapan.","sentence_template":"明日は八時に会社へ[blank]なりません。"}'::jsonb, '{"selected":"行かなければ"}'::jsonb, NULL, NULL, '行きます -> Bentuk NAI: 行かない -> hilangkan い -> 行かなければなりません.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('138eaec2-3131-4209-8661-7e1caaabb51a', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kewajiban membayar sewa rumah: 毎月二十五日までに家賃を___なりません。', '{"options":["払わなければ","払うければ","払ってければ","払いないければ"],"translation":"Setiap bulan saya harus membayar uang sewa paling lambat tanggal 25.","sentence_template":"毎月二十五日までに家賃を[blank]なりません。"}'::jsonb, '{"selected":"払わなければ"}'::jsonb, NULL, NULL, '払います berakhiran い (Grup 1) -> bentuk NAI menjadi 払わない -> 払わなければなりません.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea22b3d8-1d3b-4b24-9ce6-b4955b5cc048', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Saya harus mencuci tangan sebelum masuk ruang produksi."', '{"romaji":"Sagyoushitsu ni hairu mae ni, te o arawanakereba narimasen.","tokens":["洗って","入る前に、","作業室に","洗わなければ","手を","なりません。","洗います"],"target_translation":"Saya harus mencuci tangan sebelum masuk ruang produksi."}'::jsonb, '["作業室に","入る前に、","手を","洗わなければ","なりません。"]'::jsonb, NULL, NULL, '洗います -> 洗わない -> 洗わなければなりません (harus mencuci).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1003706c-631c-4152-ac8c-6cb1821d92d5', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Hari ini saya harus lembur sampai jam delapan."', '{"romaji":"Kyou wa hachiji made zangyou shinakereba narimasen.","tokens":["今日は","残業して","八時まで","なりません。","残業しなければ","残業します"],"target_translation":"Hari ini saya harus lembur sampai jam delapan."}'::jsonb, '["今日は","八時まで","残業しなければ","なりません。"]'::jsonb, NULL, NULL, '残業します (lembur) -> 残業しない -> 残業しなければなりません.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0061531c-c216-4a57-8b02-06b8e7e531d2', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya harus meminum obat ini setelah makan."', '{"romaji":"Shokugo ni kono kusuri o nomanakereba narimasen.","display_text":"食後にこの薬を飲まなければなりません。","phonetic_breakdown":["sho-ku-go","ni","ko-no","ku-su-ri","o","no-ma-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"食後にこの薬を飲まなければなりません。"}'::jsonb, NULL, NULL, '飲みます -> 飲まない -> 飲まなければなりません. 食後 (shokugo) berarti setelah makan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ad23245-f554-498d-9078-0a4a2e616885', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この薬は食後に飲ま___。', '{"options":["ないでください","たほうがいいです","てもいいです","なければなりません"],"translation":"Obat ini harus diminum setelah makan.","sentence_template":"この薬は食後に飲ま[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, 'Bentuk ない tanpa い + ければなりません menyatakan keharusan atau kewajiban.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ff5ce96-1ddc-4660-9160-1bf25fde6054', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap hari setelah masuk kerja, harus mencatatkan kartu absensi."', '{"romaji":"Mainichi shukkin shitara taimukaado o osanakereba narimasen.","tokens":["押さなければ","毎日","押してあります。","と","タイムカードを","なりません。","出勤したら"],"target_translation":"Setiap hari setelah masuk kerja, harus mencatatkan kartu absensi."}'::jsonb, '["毎日","出勤したら","タイムカードを","押さなければ","なりません。"]'::jsonb, NULL, NULL, '押す -> 押さない -> 押さなければなりません berarti harus menekan/mencatatkan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b56c5538-febe-4095-b988-f6dc7071eab9', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan penjelasan resepsionis hotel. Fasilitas apa yang bisa dipakai sampai malam?', '{"options":[{"id":"opt_1","text":"Restoran prasmanan"},{"id":"opt_2","text":"Ruang rapat lantai tiga"},{"id":"opt_3","text":"Kolam renang luar ruangan"},{"id":"opt_4","text":"Pemandian air panas umum sampai jam 11 malam"}],"audio_text":"大浴場は夜の十一時まで入れますので、ぜひご利用ください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '大浴場 (daiyokujou) adalah pemandian umum besar, dan 入れます (hairemasu) berarti bisa masuk/menggunakan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4fc52ab8-aa0d-40ef-a763-7d105798cd0c', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa Rina tidak ikut menyetir?', '{"options":[{"id":"opt_1","text":"Dia tidak bisa menyetir saat hari bersalju karena berbahaya"},{"id":"opt_2","text":"Dia belum memiliki SIM"},{"id":"opt_3","text":"Mobilnya sedang diperbaiki di bengkel"},{"id":"opt_4","text":"Dia tidak tahu jalan menuju kantor cabang"}],"audio_text":"免許は持っていますが、雪の日は危ないので運転できません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '運転できません berarti tidak bisa mengemudi; 免許は持っています berarti dia sebenarnya punya SIM.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('787686ae-4876-44c3-8759-3fe2ab4e15a2', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan informasi minimarket ini. Layanan apa yang tersedia di mesin ATM?', '{"options":[{"id":"opt_1","text":"Hanya bisa menukar mata uang asing"},{"id":"opt_2","text":"Bisa menarik uang tunai kapan saja selama 24 jam"},{"id":"opt_3","text":"Hanya buka pada hari kerja"},{"id":"opt_4","text":"Bisa mencetak tiket pesawat"}],"audio_text":"このATMでは、二十四時間いつでもお金がおろせます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'お金がおろせます berarti bisa menarik uang (おろします -> おろせます).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('531ee611-85d4-4faa-a484-d7002e92332a', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Pilih bentuk potensial dari 見ます (melihat, Grup 2): 晴れた日には、この窓から富士山が___。', '{"options":["見ます","見えます","見れります","見られます"],"translation":"Pada hari cerah, dari jendela ini kita dapat menyaksikan Gunung Fuji.","sentence_template":"晴れた日には、この窓から富士山が[blank]。"}'::jsonb, '{"selected":"見られます"}'::jsonb, NULL, NULL, '見られます adalah bentuk potensial baku dari 見ます (dapat dilihat/disaksikan).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('09daea09-9e66-4b26-bf2a-da4b598475cf', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Ubah 泳ぎます (berenang, Grup 1) ke bentuk potensial: 私は一キロぐらい___。', '{"options":["泳げます","泳ぎられます","泳ぎます","泳げります"],"translation":"Saya bisa berenang sekitar satu kilometer.","sentence_template":"私は一キロぐらい[blank]。"}'::jsonb, '{"selected":"泳げます"}'::jsonb, NULL, NULL, '泳ぎます (oyogimasu) -> ubah gi ke ge -> 泳げます (oyogemasu).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a93e5f70-1313-47da-95d3-3f24e629590e', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat tentang kemampuan berbahasa: 辞書があれば、日本の新聞も少し___。', '{"options":["読めります","読めます","読みます","読まれます"],"translation":"Kalau ada kamus, saya juga bisa membaca koran Jepang sedikit.","sentence_template":"辞書があれば、日本の新聞も少し[blank]。"}'::jsonb, '{"selected":"読めます"}'::jsonb, NULL, NULL, '読みます (yomimasu) -> ubah mi ke me -> 読めます (yomemasu).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74bafb3b-9053-4206-968c-8bfb563fe64b', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan percakapan di kasir berikut. Apakah kartu kredit bisa digunakan?', '{"options":[{"id":"opt_1","text":"Mesin kartu kredit sedang rusak hari ini"},{"id":"opt_2","text":"Kartu kredit hanya bisa dipakai untuk pembelian di atas 10.000 yen"},{"id":"opt_3","text":"Toko ini hanya menerima uang tunai"},{"id":"opt_4","text":"Pembayaran dengan sebagian besar kartu kredit utama bisa dilakukan di sini"}],"audio_text":"すみません、ここではクレジットカードが使えますか。はい、主要なカードはほとんどご利用になれます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '使えますか menanyakan ketersediaan penggunaan kartu, dan kasir menjawab bisa.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2dc43316-fad6-4fc2-8ac4-4958d646084b', '784b6901-b78f-43e7-b045-e3a0dcf431e1', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 晴れた日には、このビルの屋上から富士山が___。', '{"options":["見ます","見られます","見させます","見せます"],"translation":"Pada hari cerah, Gunung Fuji bisa dilihat dari atap gedung ini.","sentence_template":"晴れた日には、このビルの屋上から富士山が[blank]。"}'::jsonb, '{"selected":"見られます"}'::jsonb, NULL, NULL, '見る (kelompok 2) bentuk potensialnya 見られる (bisa melihat/dilihat dalam kondisi tertentu).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11a1fa12-b360-467c-a0a1-ff69aee484bd', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi pola tindakan persiapan sebelum acara: パーティーの前に、飲み物を冷やして___。', '{"options":["みます","しまいます","おきます","あります"],"translation":"Sebelum pesta, saya akan mendinginkan minuman terlebih dahulu.","sentence_template":"パーティーの前に、飲み物を冷やして[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, NULL, NULL, '～ておきます digunakan saat subjek melakukan tindakan persiapan demi keperluan yang akan datang.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('64c59fc2-2edf-4b07-a3dc-019f625d8307', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Pilih bentuk TE yang benar untuk 買います (membeli): 旅行の前に、新しいカメラを___おきたいです。', '{"options":["買いて","買んで","買いって","買って"],"translation":"Sebelum berwisata, saya ingin membeli kamera baru terlebih dahulu.","sentence_template":"旅行の前に、新しいカメラを[blank]おきたいです。"}'::jsonb, '{"selected":"買って"}'::jsonb, NULL, NULL, '買います -> Bentuk TE: 買って + おきたいです.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('750377d4-c81f-4321-a2a9-3ac349e5a519', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi bentuk permintaan persiapan lebih awal: 明日までにこの書類を読んで___。', '{"options":["おいてください","おかないください","おったください","おきますください"],"translation":"Tolong baca dokumen ini terlebih dahulu paling lambat besok.","sentence_template":"明日までにこの書類を読んで[blank]。"}'::jsonb, '{"selected":"おいてください"}'::jsonb, NULL, NULL, 'おきます diubah ke bentuk TE (おいて) lalu ditambah ください -> 読んでおいてください.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0596d88-504e-46b1-a2e7-684d746efff0', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Tolong nyalakan AC sebelum tamu datang."', '{"romaji":"Okyakusama ga kuru mae ni, eakon o tsukete oite kudasai.","tokens":["お客様が来る前に、","エアコンを","あります。","消して","おいてください。","つけて"],"target_translation":"Tolong nyalakan AC sebelum tamu datang."}'::jsonb, '["お客様が来る前に、","エアコンを","つけて","おいてください。"]'::jsonb, NULL, NULL, 'つけておいてください meminta agar AC dinyalakan lebih awal agar ruangan sudah sejuk saat tamu tiba.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('506d97ee-c5d1-4666-8c75-0b031e8840b5', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Saya sudah memesan restoran untuk makan malam besok."', '{"romaji":"Ashita no tame ni, resutoran o yoyaku shite okimashita.","tokens":["予約して","食べました。","明日のために、","レストランを","予約します。","おきました。"],"target_translation":"Saya sudah memesan restoran untuk makan malam besok."}'::jsonb, '["明日のために、","レストランを","予約して","おきました。"]'::jsonb, NULL, NULL, '予約しておきました menyatakan reservasi sudah dilakukan sebelumnya sebagai persiapan.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5811259b-daa0-4515-bad3-37e7dc03d8d9', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tolong bereskan meja ini setelah selesai dipakai ya."', '{"romaji":"Tsukaiowattara, kono tsukue o katazukete oite kudasai.","display_text":"使い終わったら、この机を片付けておいてください。","phonetic_breakdown":["tsu-ka-i-o-wat-ta-ra","ko-no","tsu-ku-e","o","ka-ta-zu-ke-te","o-i-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"使い終わったら、この机を片付けておいてください。"}'::jsonb, NULL, NULL, '片付けておいてください berarti tolong rapikan agar siap dipakai berikutnya.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eac54a02-bdf6-4107-a405-a843d1e855a7', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 旅行の前に、ガイドブックを読んで___。', '{"options":["あります","しまいます","みます","おきます"],"translation":"Sebelum bepergian, saya akan membaca buku panduan terlebih dahulu.","sentence_template":"旅行の前に、ガイドブックを読んで[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, NULL, NULL, 'Bentuk て + おく menyatakan tindakan persiapan sebelum suatu acara atau tujuan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fcb7ab94-82ee-43fa-9e67-261e57cf23e4', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Untuk kelas berikutnya, saya akan mencari arti kosakata baru terlebih dahulu."', '{"romaji":"Tsugi no jugyou no tame ni atarashii tango o shirabete okimasu.","tokens":["ために","おきます。","授業の","が","単語を","新しい","次の","調べます。","調べて"],"target_translation":"Untuk kelas berikutnya, saya akan mencari arti kosakata baru terlebih dahulu."}'::jsonb, '["次の","授業の","ために","新しい","単語を","調べて","おきます。"]'::jsonb, NULL, NULL, '調べておきます menunjukkan persiapan belajar sebelum kelas dimulai.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('13cd82f1-23e7-453a-a510-598026f2c0a9', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita ini. Siapa yang memasakkan bubur?', '{"options":[{"id":"opt_1","text":"Pembicara memasak sendiri"},{"id":"opt_2","text":"Ibu pembicara yang memasak"},{"id":"opt_3","text":"Teman sekamar memasakkan bubur untuk pembicara"},{"id":"opt_4","text":"Dokter menyarankan membeli bubur"}],"audio_text":"昨日風邪を引いたとき、ルームメイトがおかゆを作ってくれました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'ルームメイトがおかゆを作ってくれました berarti teman sekamar membuatkan bubur untuk saya.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f5a4ed64-841e-468d-ad32-85eaea175c75', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan percakapan kantor ini. Apa yang didapat pembicara dari Pak Suzuki?', '{"options":[{"id":"opt_1","text":"Hadiah ulang tahun"},{"id":"opt_2","text":"Pinjaman buku kamus"},{"id":"opt_3","text":"Jadwal cuti baru"},{"id":"opt_4","text":"Penjelasan cara input jadwal shift baru"}],"audio_text":"鈴木さんに新しいシフトの入力方法を教えてもらいました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '鈴木さんに...教えてもらいました berarti saya diajari oleh Pak Suzuki.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d04ff524-05a7-411e-b3bb-0f6872c53294', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita berikut. Apa yang dilakukan pembicara untuk karyawan baru?', '{"options":[{"id":"opt_1","text":"Menjelaskan cara memakai mesin fotokopi kepada karyawan baru"},{"id":"opt_2","text":"Meminta karyawan baru memfotokopi dokumen"},{"id":"opt_3","text":"Memperbaiki mesin fotokopi yang macet"},{"id":"opt_4","text":"Membelikan kertas fotokopi baru"}],"audio_text":"新入社員が困っていたので、コピー機の使い方を説明してあげました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '説明してあげました menunjukkan pembicara membantu menjelaskan kepada karyawan baru.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c87eabcc-ea32-4844-a909-1e3048742a5b', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Pilih partikel pemberi bantuan pada pola ～てもらいました: 私は田中さん___駅まで車で送ってもらいました。', '{"options":["が","に","で","を"],"translation":"Saya diantar oleh Pak Tanaka sampai stasiun dengan mobil.","sentence_template":"私は田中さん[blank]駅まで車で送ってもらいました。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, NULL, 'Pada pola ～てもらう, orang yang memberi bantuan ditandai dengan partikel に (atau から).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9a36b49e-a875-4b56-96c2-b9a52a5f7f84', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Pilih verba bantu yang tepat untuk subjek 友達が: 誕生日に友達がケーキを焼いて___。', '{"options":["あげました","やりました","くれました","もらいました"],"translation":"Pada hari ulang tahun saya, teman memanggangkan kue untuk saya.","sentence_template":"誕生日に友達がケーキを焼いて[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, '友達が (teman sebagai subjek yang berbuat baik kepada saya) wajib berpasangan dengan くれました.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b284f31d-fc6b-48ad-b379-1cb6565574ff', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat penawaran bantuan kepada junior: その荷物、重そうだね。僕が持って___よ。', '{"options":["くれる","もらう","いただく","あげる"],"translation":"Barang itu kelihatannya berat ya. Biar aku bawakan ya.","sentence_template":"その荷物、重そうだね。僕が持って[blank]よ。"}'::jsonb, '{"selected":"あげる"}'::jsonb, NULL, NULL, 'Subjek 僕が (aku) menawarkan bantuan kepada lawan bicara yang setara/lebih muda -> 持ってあげるよ.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('68fbca06-745f-4a86-9fd3-bd466fc992e7', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita di kantor berikut. Apa yang terjadi?', '{"options":[{"id":"opt_1","text":"Pembicara memperbaiki komputer milik Suzuki"},{"id":"opt_2","text":"Pembicara meminta dan menerima bantuan Suzuki dari tim IT untuk memperbaiki komputernya"},{"id":"opt_3","text":"Komputer Suzuki rusak dan belum diperbaiki"},{"id":"opt_4","text":"Tim IT menyarankan pembicara membeli komputer baru"}],"audio_text":"パソコンの調子が悪かったので、IT担当の鈴木さんに直してもらいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '鈴木さんに直してもらいました menunjukkan pembicara menerima bantuan perbaikan dari Suzuki.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea51eeb0-45af-4934-82d5-e2121d6fc7fd', '7eab6736-77f7-4b2d-a45f-a52343fd545d', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 弟が宿題で困っていたので、数学を教えて___。', '{"options":["いただきました","もらいました","あげました","くれました"],"translation":"Karena adik laki-laki kesulitan dengan PR, saya mengajarinya matematika.","sentence_template":"弟が宿題で困っていたので、数学を教えて[blank]。"}'::jsonb, '{"selected":"あげました"}'::jsonb, NULL, NULL, 'Subjek adalah saya yang membantu adik, maka gunakan ～てあげる.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('52198868-b955-49c2-9633-f568f5a6e190', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan arahan kepala pabrik. Apa yang wajib dipakai di area kerja?', '{"options":[{"id":"opt_1","text":"Sarung tangan dan masker"},{"id":"opt_2","text":"Jas hujan dan sepatu bot"},{"id":"opt_3","text":"Dasi dan kemeja putih"},{"id":"opt_4","text":"Kacamata hitam dan topi"}],"audio_text":"この工場では、作業中に必ず手袋とマスクをつけなければなりません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '手袋 (tebukuro) berarti sarung tangan, dan マスク (masuku) berarti masker.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf385735-1739-43f1-bb9a-779fad775ed0', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa Andi pulang lebih awal?', '{"options":[{"id":"opt_1","text":"Karena dia sedang demam tinggi"},{"id":"opt_2","text":"Karena dia harus pergi ke kantor balai kota pukul lima"},{"id":"opt_3","text":"Karena keluarganya datang dari Indonesia"},{"id":"opt_4","text":"Karena keretanya akan berhenti beroperasi"}],"audio_text":"すみません、今日は五時に市役所へ行かなければなりませんので、先に失礼します。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '市役所へ行かなければなりません berarti harus pergi ke kantor balai kota (shiyakusho).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('09825614-1e05-4018-abf0-2f30e2ec470e', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan pengumuman asrama. Kapan sampah plastik harus dibuang?', '{"options":[{"id":"opt_1","text":"Setiap Senin malam"},{"id":"opt_2","text":"Setiap Jumat siang"},{"id":"opt_3","text":"Setiap Rabu pagi paling lambat jam delapan"},{"id":"opt_4","text":"Kapan saja sepanjang minggu"}],"audio_text":"プラスチックごみは、毎週水曜日の朝八時までに出さなければなりません。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '毎週水曜日の朝八時までに出さなければなりません berarti harus dikeluarkan setiap Rabu pagi maksimal jam 8.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('285b00dd-3738-458a-b6a6-d4c6fb1734c3', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi aturan membawa kartu identitas di Jepang: 外国人はいつでも在留カードを___なりません。', '{"options":["持っていますければ","持っていなければ","持つければ","持ったければ"],"translation":"Warga asing harus selalu membawa kartu izin tinggal (Zairyu Card).","sentence_template":"外国人はいつでも在留カードを[blank]なりません。"}'::jsonb, '{"selected":"持っていなければ"}'::jsonb, NULL, NULL, '持っています -> 持っていない -> 持っていなければなりません.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9e9a9052-cca0-4241-b30a-fe314c1ffcfb', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Pilih kata kerja keharusan untuk mengembalikan buku: 図書館の本は二週間以内に___なりません。', '{"options":["返しなければ","返してければ","返さなければ","返るければ"],"translation":"Buku perpustakaan harus dikembalikan dalam waktu dua minggu.","sentence_template":"図書館の本は二週間以内に[blank]なりません。"}'::jsonb, '{"selected":"返さなければ"}'::jsonb, NULL, NULL, '返します (mengembalikan) -> 返さない -> 返さなければなりません.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5e7e7b4d-34a4-4d6a-9123-04ea44549347', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kewajiban memperbarui visa: 来月までにビザを___なりません。', '{"options":["更新してければ","更新するければ","更新したければ","更新しなければ"],"translation":"Saya harus memperbarui visa paling lambat bulan depan.","sentence_template":"来月までにビザを[blank]なりません。"}'::jsonb, '{"selected":"更新しなければ"}'::jsonb, NULL, NULL, '更新します (memperbarui/renew) -> 更新しない -> 更新しなければなりません.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('101453c7-7cd0-49ca-b769-4a6e9e4db36e', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan peraturan perusahaan berikut. Apa yang wajib dilakukan jika akan terlambat?', '{"options":[{"id":"opt_1","text":"Jika terlambat 10 menit, tidak perlu memberi kabar"},{"id":"opt_2","text":"Jika diperkirakan terlambat, wajib menelepon maksimal 10 menit sebelum jam kerja mulai"},{"id":"opt_3","text":"Laporan keterlambatan cukup dikirim lewat surat pos"},{"id":"opt_4","text":"Karyawan boleh datang 10 menit setelah jam kerja dimulai"}],"audio_text":"遅刻しそうなときは、始業時間の十分前までに電話で連絡しなければなりません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '始業時間 (shigyou jikan) adalah jam mulai kerja; 連絡しなければなりません berarti wajib menghubungi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85b99fbb-9346-49e8-9cc6-e495543de72f', '83372d52-be22-4e51-8d29-ada95529644a', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: パスポートの有効期限が切れる前に、更新___。', '{"options":["するはずです","してもかまいません","したことがあります","しなければなりません"],"translation":"Sebelum masa berlaku paspor habis, harus diperpanjang.","sentence_template":"パスポートの有効期限が切れる前に、更新[blank]。"}'::jsonb, '{"selected":"しなければなりません"}'::jsonb, NULL, NULL, '更新する -> 更新しない -> 更新しなければなりません menyatakan kewajiban mengurus perpanjangan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('451965bb-ebbc-46f9-9dfb-1894fa2a1c7a', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masih baru pertama kali, tolong bimbing saya."', '{"romaji":"Hajimete na node, douzo yoroshiku onegai shimasu.","display_text":"初めてなので、どうぞよろしくお願いします。","phonetic_breakdown":["ha-ji-me-te","na","no-de","do-u-zo","yo-ro-shi-ku","o-ne-ga-i","shi-ma-su"]}'::jsonb, '{"expected_transcript":"初めてなので、どうぞよろしくお願いします。"}'::jsonb, NULL, NULL, '初めて (pertama kali) berperilaku seperti nomina/na-adj, sehingga memakai なので -> 初めてなので.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21e4b519-f0e8-4e9b-b466-2b75411a6479', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak sempat sarapan, sekarang saya sangat lapar."', '{"romaji":"Asagohan o tabenakatta node, ima totemo onaka ga suite imasu.","display_text":"朝ご飯を食べなかったので、今とてもお腹が空いています。","phonetic_breakdown":["a-sa-go-han","o","ta-be-na-kat-ta","no-de","i-ma","to-te-mo","o-na-ka","ga","su-i-te","i-ma-su"]}'::jsonb, '{"expected_transcript":"朝ご飯を食べなかったので、今とてもお腹が空いています。"}'::jsonb, NULL, NULL, '食べなかった (tidak makan, lampau biasa) + ので.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82ae15c1-84bd-4ce2-b42b-d2be981473a6', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena suaranya kurang terdengar, tolong keraskan sedikit."', '{"romaji":"Sukoshi kikoenikui node, mou sukoshi ookiku hanashite kudasai.","display_text":"少し聞こえにくいので、もう少し大きく話してください。","phonetic_breakdown":["su-ko-shi","ki-ko-e-ni-ku-i","no-de","mo-u","su-ko-shi","o-o-ki-ku","ha-na-shi-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"少し聞こえにくいので、もう少し大きく話してください。"}'::jsonb, NULL, NULL, '聞こえにくい (sulit terdengar) berakhiran い sehingga langsung diikuti ので.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('17dbd569-b71f-49d6-8a18-d6890fc72edb', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena ruangannya panas, saya membuka jendela."', '{"romaji":"Heya ga atsui node, mado o akemashita.","tokens":["窓を","閉めました。","暑いので、","部屋が","暑いなので、","開けました。"],"target_translation":"Karena ruangannya panas, saya membuka jendela."}'::jsonb, '["部屋が","暑いので、","窓を","開けました。"]'::jsonb, NULL, NULL, '暑い (Adjektiva-I) + ので + 窓を開けました.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('47e19060-a5ae-4f41-bda9-61db53a70ee5', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena saya suka masakan Jepang, saya sering memasak ramen."', '{"romaji":"Nihon ryouri ga suki na node, yoku raamen o tsukurimasu.","tokens":["日本料理が","好きなので、","よくラーメンを","嫌いです。","好きだので、","作ります。"],"target_translation":"Karena saya suka masakan Jepang, saya sering memasak ramen."}'::jsonb, '["日本料理が","好きなので、","よくラーメンを","作ります。"]'::jsonb, NULL, NULL, '好き adalah Adjektiva-NA, sehingga wajib memakai な sebelum ので -> 好きなので.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('520bfc1c-5e01-45aa-a923-9ccc7d2920bf', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah jam lima, mari kita selesaikan pekerjaan hari ini."', '{"romaji":"Mou goji na node, kyou no shigoto o owari ni shimashou.","tokens":["今日の仕事を","なので、","終わりにしましょう。","始めましょう。","もう五時","だので、"],"target_translation":"Karena sudah jam lima, mari kita selesaikan pekerjaan hari ini."}'::jsonb, '["もう五時","なので、","今日の仕事を","終わりにしましょう。"]'::jsonb, NULL, NULL, '五時 adalah Nomina, jadi memakai なので.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a735c41-a34d-4eeb-9100-6cae48566336', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ada urusan, saya izin pulang duluan."', '{"romaji":"Youji ga aru node, osaki ni shitsurei shimasu.","display_text":"用事があるので、お先に失礼します。","phonetic_breakdown":["you-ji-ga","a-ru-no-de","o-sa-ki-ni","shi-tsu-re-i-shi-ma-su"]}'::jsonb, '{"expected_transcript":"用事があるので、お先に失礼します。"}'::jsonb, NULL, NULL, '～ので terdengar lebih halus dan objektif daripada から saat pamit di kantor.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d05444c-cfec-4190-8db6-d2e7ebd93e45', '871e7cd1-52ba-403d-bb15-480f34de9241', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena di sini dekat dari stasiun, praktis untuk berangkat kerja."', '{"romaji":"Koko wa eki kara chikai node, tsuukin ni benri desu.","tokens":["近いなので、","通勤に","を","駅から","近いので、","便利です。","ここは"],"target_translation":"Karena di sini dekat dari stasiun, praktis untuk berangkat kerja."}'::jsonb, '["ここは","駅から","近いので、","通勤に","便利です。"]'::jsonb, NULL, NULL, 'Kata sifat い (近い) langsung diikuti ので tanpa な.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7ed008dc-16f2-473c-8371-15d2a8f9d7fe', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Pilih bentuk percakapan kasual (kontraksi) dari ～ておく yang sering muncul di audio N4: 明日早いから、今夜のうちに荷物を準備し___よ。', '{"options":["とく","てる","みる","ちゃう"],"translation":"Karena besok berangkat pagi, malam ini aku siapkan barang-barang dulu ya.","sentence_template":"明日早いから、今夜のうちに荷物を準備し[blank]よ。"}'::jsonb, '{"selected":"とく"}'::jsonb, NULL, NULL, 'Dalam percakapan sehari-hari, ～ておく sering disingkat menjadi ～とく (準備しておく -> 準備しとく).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15a60fab-2a27-41fc-83f3-4d47fde4afa2', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Bedakan pola aksi persiapan vs laporan keadaan hasil aksi: 明日のプレゼンのために、今晩よく練習して___。', '{"options":["きました","おきます","いますか","あります"],"translation":"Demi presentasi besok, malam ini saya akan berlatih dengan baik terlebih dahulu.","sentence_template":"明日のプレゼンのために、今晩よく練習して[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, NULL, NULL, 'Karena menyatakan rencana tindakan aktif yang akan dilakukan subjek (今晩), gunakan 練習しておきます.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6316b00-ba85-4eff-bd28-4a90dd772027', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Apa yang sudah dilakukan Sato untuk rapat sore?', '{"options":[{"id":"opt_1","text":"Sato sudah membagikan materi ke meja semua peserta sebelumnya"},{"id":"opt_2","text":"Sato belum mencetak materi rapat"},{"id":"opt_3","text":"Sato akan membagikan materi setelah rapat"},{"id":"opt_4","text":"Sato meminta orang lain membagikan materi"}],"audio_text":"佐藤さん、午後の資料はどうですか。はい、すでに全員の机に配っておきました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '配っておきました berarti sudah dibagikan sebelumnya sebagai persiapan.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9120181c-2963-4012-8e26-531218905b22', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'listening', 'listening_choice', 'Dengarkan pesan ibu sebelum pergi. Apa yang diminta kepada anaknya?', '{"options":[{"id":"opt_1","text":"Menjemur pakaian baru di luar"},{"id":"opt_2","text":"Memasukkan jemuran sebelum keluar rumah karena sepertinya sore akan hujan"},{"id":"opt_3","text":"Mencuci pakaian dengan mesin cuci"},{"id":"opt_4","text":"Menyetrika seragam sekolah"}],"audio_text":"夕方雨が降りそうだから、外に出る前に洗濯物を取り込んでおいてね。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '洗濯物を取り込んでおいてね berarti tolong angkat/masukkan jemuran terlebih dahulu.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7717ee2a-497b-4eeb-a413-af1684b40916', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menelepon dokter dulu untuk membuat janji."', '{"romaji":"Byouin ni denwa shite, yoyaku o totte okimasu.","tokens":["おきます。","忘れます。","病院に","取って","電話して、","予約を","取ります。"],"target_translation":"Saya akan menelepon dokter dulu untuk membuat janji."}'::jsonb, '["病院に","電話して、","予約を","取って","おきます。"]'::jsonb, NULL, NULL, '予約を取ります (membuat janji temu) -> 予約を取っておきます.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d44b3af5-7108-4330-ae1b-d0f585de5a2c', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum pindah rumah, saya harus mengurus prosedur di balai kota dulu."', '{"romaji":"Hikkosu mae ni, shiyakusho de tetsuzuki o shite okanakereba narimasen.","display_text":"引っ越す前に、市役所で手続きをしておかなければなりません。","phonetic_breakdown":["hik-ko-su","ma-e","ni","shi-ya-ku-sho","de","te-tsu-zu-ki","o","shi-te","o-ka-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"引っ越す前に、市役所で手続きをしておかなければなりません。"}'::jsonb, NULL, NULL, 'Kombinasi ～ておく + ～なければなりません berarti ''harus mempersiapkan terlebih dahulu''.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be7fe7ed-2838-4b54-9d05-9e8e6f426b6f', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 次の人もすぐ使えるように、道具は元の場所に___おいてください。', '{"options":["戻し","戻す","戻して","戻した"],"translation":"Agar orang berikutnya juga bisa langsung memakai, tolong kembalikan alat ke tempat semula.","sentence_template":"次の人もすぐ使えるように、道具は元の場所に[blank]おいてください。"}'::jsonb, '{"selected":"戻して"}'::jsonb, NULL, NULL, '戻す -> 戻して + おいてください menunjukkan tindakan merapikan demi kemudahan berikutnya.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d3b6a837-8c52-4b64-8217-2aae15918ef7', '8757af6e-bc98-4b42-9b83-a2426e3ffe6c', 'd1000019-0000-0000-0000-000000000006', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum rapat, saya sudah mencatat pertanyaan terlebih dahulu."', '{"romaji":"Kaigi no mae ni shitsumon o memo shite okimashita.","display_text":"会議の前に質問をメモしておきました。","phonetic_breakdown":["kai-gi-no","ma-e-ni","shi-tsu-mon-o","me-mo-shi-te","o-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"会議の前に質問をメモしておきました。"}'::jsonb, NULL, NULL, 'メモしておきました menunjukkan kesiapan aktif sebelum rapat berlangsung.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a5c607b-fdd5-4503-8394-8dcf381a666f', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan laporan staf ini. Bagaimana kondisi ruang rapat sekarang?', '{"options":[{"id":"opt_1","text":"AC rusak dan dokumen belum dicetak"},{"id":"opt_2","text":"AC sudah dinyalakan dan dokumen sudah ditata untuk semua peserta"},{"id":"opt_3","text":"Ruang rapat sedang dipakai tim lain"},{"id":"opt_4","text":"Hanya kursi yang sudah disiapkan"}],"audio_text":"エアコンもつけてありますし、資料も全員分並べてあります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'つけてあります (AC sudah dinyalakan) dan 並べてあります (dokumen sudah ditata) menunjukkan persiapan ruang sudah lengkap.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('852891e0-0769-40e3-88a7-37a4017d09c1', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak perlu memesan hotel lagi?', '{"options":[{"id":"opt_1","text":"Perjalanan dinas dibatalkan"},{"id":"opt_2","text":"Mereka akan menginap di rumah rekan kerja"},{"id":"opt_3","text":"Hotel untuk perjalanan dinas sudah dipesan sebelumnya"},{"id":"opt_4","text":"Mereka pulang di hari yang sama"}],"audio_text":"出張のホテルはもう予約してありますから、安心してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '予約してあります berarti sudah dipesan sebelumnya untuk tujuan perjalanan dinas.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a6c7bdc-8c22-489f-aacf-8042f9540666', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan petunjuk di dapur kantor. Di mana kopi disiapkan?', '{"options":[{"id":"opt_1","text":"Belum dibuat karena air belum panas"},{"id":"opt_2","text":"Harus dibeli di minimarket depan"},{"id":"opt_3","text":"Disimpan di dalam kulkas"},{"id":"opt_4","text":"Sudah dibuat dan berada di dalam teko termos"}],"audio_text":"お客様用のコーヒーは、ポットに作ってありますよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'ポットに作ってあります berarti sudah diseduh/dibuat dan ditaruh di dalam teko termos.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00755bdd-898d-4ab9-aa8e-3c5a3dcc3252', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat laporan persiapan dokumen: 明日のプレゼンの資料はもう印刷して___。', '{"options":["きます","みます","いきます","あります"],"translation":"Materi presentasi besok sudah selesai dicetak.","sentence_template":"明日のプレゼンの資料はもう印刷して[blank]。"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, '印刷してあります menekankan bahwa pencetakan sudah selesai dilakukan untuk persiapan presentasi besok.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('636e7c26-1b5f-4381-8ba1-be1cd95a6493', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Pilih kata kerja transitif yang tepat untuk pintu: 防犯のために、裏口には鍵が___あります。', '{"options":["かけて","あいて","しまって","かかって"],"translation":"Demi keamanan, pintu belakang sudah dikunci.","sentence_template":"防犯のために、裏口には鍵が[blank]あります。"}'::jsonb, '{"selected":"かけて"}'::jsonb, NULL, NULL, '鍵をかけます (mengunci, transitif) -> 鍵がかけてあります. かかって adalah bentuk intransitif.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('298924fc-0998-4857-bf4e-375f648283ea', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi informasi yang tertera pada kemasan obat: この薬の箱に飲み方が詳しく___あります。', '{"options":["見て","書いて","聞いて","読んで"],"translation":"Di kotak obat ini sudah tertulis cara minumnya secara rinci.","sentence_template":"この薬の箱に飲み方が詳しく[blank]あります。"}'::jsonb, '{"selected":"書いて"}'::jsonb, NULL, NULL, '書いてあります menyatakan informasi yang memang sengaja dicetak/ditulis pada kemasan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dea68a43-392a-4aba-ad02-54094a64f673', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan laporan staf berikut. Bagaimana kondisi ruang rapat?', '{"options":[{"id":"opt_1","text":"AC ruang rapat lupa dimatikan sejak kemarin"},{"id":"opt_2","text":"Peserta rapat diminta menyalakan AC sendiri"},{"id":"opt_3","text":"Rapat ditunda karena AC ruang rapat belum menyala"},{"id":"opt_4","text":"AC ruang rapat sudah dinyalakan sebelumnya sehingga rapat bisa segera dimulai"}],"audio_text":"会議室のエアコンはもうつけてありますので、すぐ始められますよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'つけてあります menunjukkan seseorang sengaja menyalakan AC sebagai persiapan rapat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('38b50c4e-de67-4b99-94ee-6feeb6a38f94', '8892b332-7234-4356-8b25-ae143a019550', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 玄関に傘が三本___あります。', '{"options":["置いて","置く","置き","置いた"],"translation":"Di pintu masuk sudah diletakkan tiga buah payung.","sentence_template":"玄関に傘が三本[blank]あります。"}'::jsonb, '{"selected":"置いて"}'::jsonb, NULL, NULL, '置く (oku) berubah menjadi 置いて sebelum あります.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e215a175-42f2-4365-ad00-cacc2c48701f', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan permintaan karyawan ini. Apa yang ia minta dari seniornya?', '{"options":[{"id":"opt_1","text":"Menulis ulang seluruh laporan"},{"id":"opt_2","text":"Mengirimkan file ke klien"},{"id":"opt_3","text":"Memberi tahu cara baca kanji tersebut"},{"id":"opt_4","text":"Memfotokopi buku manual"}],"audio_text":"佐藤さん、すみませんが、この漢字の読み方を教えていただけませんか。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'この漢字の読み方を教えていただけませんか berarti ''Bersediakah Anda memberi tahu cara baca kanji ini?''', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('104b373f-778a-41ee-80bb-54f96f3f42b0', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan pengumuman di resepsionis. Apa yang diminta kepada tamu?', '{"options":[{"id":"opt_1","text":"Menunggu di lantai dua"},{"id":"opt_2","text":"Menunjukkan paspor asli"},{"id":"opt_3","text":"Mematikan ponsel saat rapat"},{"id":"opt_4","text":"Menuliskan nama dan nama perusahaan di formulir"}],"audio_text":"恐れ入りますが、お名前と会社名をこちらにご記入いただけませんか。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'お名前と会社名をこちらにご記入いただけませんか meminta tamu mengisi nama dan nama perusahaan dengan sangat sopan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c7a8f0be-a5fe-4a12-b1b6-6689ed442663', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan permintaan di ruang rapat. Apa masalah pembicara?', '{"options":[{"id":"opt_1","text":"Ruangan terasa terlalu dingin"},{"id":"opt_2","text":"Ruangan terasa terlalu gelap"},{"id":"opt_3","text":"Proyektor tidak menyala"},{"id":"opt_4","text":"Suara mikrofon terlalu kecil"}],"audio_text":"すみませんが、エアコンの温度を少し上げていただけませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'エアコンの温度を少し上げていただけませんか meminta menaikkan suhu AC karena ruangan terasa terlalu dingin.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('34fce43a-eca6-40d2-aaa8-9d0eb99ad838', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Pilih kata kerja bentuk TE yang paling sesuai konteks: 荷物が重いので、ドアを___いただけませんか。', '{"options":["消して","開けて","閉めて","飲んで"],"translation":"Karena barang bawaan saya berat, bersediakah Anda membukakan pintu?","sentence_template":"荷物が重いので、ドアを[blank]いただけませんか。"}'::jsonb, '{"selected":"開けて"}'::jsonb, NULL, NULL, '開けます (membuka) -> 開けて. Konteks membawa barang berat cocok dengan meminta dibukakan pintu.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b4626ee-d4c4-4554-ba10-a7eabcee28db', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi permintaan kepada staf hotel: 明日の朝七時にタクシーを___いただけませんか。', '{"options":["呼びて","呼べて","呼んで","呼って"],"translation":"Bersediakah Anda memanggilkan taksi besok pagi pukul tujuh?","sentence_template":"明日の朝七時にタクシーを[blank]いただけませんか。"}'::jsonb, '{"selected":"呼んで"}'::jsonb, NULL, NULL, '呼びます (memanggil) berakhiran び, sehingga bentuk TE-nya adalah 呼んで.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1875c1e5-025b-4863-bd05-12a19e44b34c', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat permintaan pengiriman data: 今日中にそのデータをメールで___いただけませんか。', '{"options":["送んで","送りて","送いて","送って"],"translation":"Bersediakah Anda mengirimkan data tersebut lewat email hari ini juga?","sentence_template":"今日中にそのデータをメールで[blank]いただけませんか。"}'::jsonb, '{"selected":"送って"}'::jsonb, NULL, NULL, '送ります (mengirim) berakhiran り, sehingga bentuk TE-nya adalah 送って.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf42e28d-e8e6-46f4-aafb-c44003e398c5', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan percakapan kantor berikut. Apa tujuan pembicara?', '{"options":[{"id":"opt_1","text":"Melaporkan bahwa rapat proyek dibatalkan"},{"id":"opt_2","text":"Meminta kepala bagian meninjau proposal proyek yang baru selesai"},{"id":"opt_3","text":"Meminta kepala bagian menulis proposal baru"},{"id":"opt_4","text":"Menyerahkan kunci ruang rapat kepada kepala bagian"}],"audio_text":"部長、新しい企画書ができましたので、目を通していただけませんか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '目を通す (me o toosu) berarti membaca sekilas atau meninjau dokumen.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44d49d4d-b4a7-400c-8545-baa9314dcfa9', '88be0b49-99b1-4034-9ed7-d9ff6455d81e', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 少し声が小さいので、もう少し大きく話して___。', '{"options":["いただけませんか","あります","おきます","しまいます"],"translation":"Karena suaranya agak pelan, maukah Anda berbicara sedikit lebih keras?","sentence_template":"少し声が小さいので、もう少し大きく話して[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, '話していただけませんか adalah permohonan sopan agar lawan bicara berbicara lebih keras.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f371b9d4-dffd-41a3-8bd6-d577d3d36821', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi pola permohonan sangat sopan: すみませんが、もう一度説明して___。', '{"options":["ありましたか","しまいますか","いただけませんか","いますか"],"translation":"Maaf, bersediakah Anda menjelaskannya sekali lagi?","sentence_template":"すみませんが、もう一度説明して[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, 'Pola [Verba Bentuk-TE] + いただけませんか digunakan untuk memohon bantuan dengan sangat sopan kepada atasan atau lawan bicara yang dihormati.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a5e4bbde-e59b-4b4c-b2b1-6f8679cf71a3', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang tepat sebelum いただけませんか: 課長、この書類を___いただけませんか。', '{"options":["見ない","見ます","見た","見て"],"translation":"Pak Kepala Seksi, berkenankah Bapak memeriksa dokumen ini?","sentence_template":"課長、この書類を[blank]いただけませんか。"}'::jsonb, '{"selected":"見て"}'::jsonb, NULL, NULL, 'Sebelum いただけませんか, kata kerja wajib diubah ke bentuk TE: 見ます -> 見て.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d309aa1-c167-4d51-b93f-72d008e4a831', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Ubah kata kerja 待ちます (menunggu) ke bentuk yang benar: 少々ここで___いただけませんか。', '{"options":["待って","待ちて","待いて","待んで"],"translation":"Bersediakah Anda menunggu sebentar di sini?","sentence_template":"少々ここで[blank]いただけませんか。"}'::jsonb, '{"selected":"待って"}'::jsonb, NULL, NULL, 'Kata kerja Grup 1 berakhiran ち (待ちます) berubah menjadi って pada bentuk TE -> 待って.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('46f6cf45-4c3b-4475-8500-4a25621408ee', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maaf, bersediakah Anda menuliskan alamat di sini?"', '{"romaji":"Sumimasen ga, koko ni juusho o kaite itadakemasen ka.","tokens":["書いて","住所を","すみませんが、","いただけませんか。","書きます","食べます","ここに"],"target_translation":"Maaf, bersediakah Anda menuliskan alamat di sini?"}'::jsonb, '["すみませんが、","ここに","住所を","書いて","いただけませんか。"]'::jsonb, NULL, NULL, '書いて (bentuk TE dari 書きます) diikuti いただけませんか membentuk permohonan sangat sopan.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e83812ca-601d-4684-863a-78d694ae19c8', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda meminjamkan pulpen sebentar?"', '{"romaji":"Chotto pen o kashite itadakemasen ka.","tokens":["いただけませんか。","ペンを","貸して","ちょっと","借りて","貸します"],"target_translation":"Bersediakah Anda meminjamkan pulpen sebentar?"}'::jsonb, '["ちょっと","ペンを","貸して","いただけませんか。"]'::jsonb, NULL, NULL, '貸します (meminjamkan) -> 貸して + いただけませんか. Jangan tertukar dengan 借りて (meminjam).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4796fc5-d2a5-4269-9773-b15c84b59802', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bersediakah Anda berbicara sedikit lebih pelan?"', '{"romaji":"Mou sukoshi yukkuri hanashite itadakemasen ka.","display_text":"もう少しゆっくり話していただけませんか。","phonetic_breakdown":["mo-u","su-ko-shi","yuk-ku-ri","ha-na-shi-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"もう少しゆっくり話していただけませんか。"}'::jsonb, NULL, NULL, '話します -> 話して + いただけませんか sangat berguna saat berkomunikasi dengan penutur asli di tempat kerja.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b09b2912-b4d7-405b-93c5-e14b09bc0509', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: すみませんが、この漢字の読み方を教えて___。', '{"options":["あげます","しまいました","いただけませんか","おきます"],"translation":"Maaf, maukah Anda mengajari saya cara membaca kanji ini?","sentence_template":"すみませんが、この漢字の読み方を教えて[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, 'Bentuk て + いただけませんか digunakan untuk memohon bantuan secara sangat sopan kepada atasan atau orang yang lebih dihormati.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9413bc7a-0fa5-41b4-98ec-72833e7876a5', '92e8f853-8217-483d-92af-d4801236393d', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Maukah Anda mengirimkan balasannya paling lambat besok?"', '{"romaji":"Ashita made ni henji o okutte itadakemasen ka.","tokens":["明日までに","いただけませんか。","送って","あげませんか。","返事を","から"],"target_translation":"Maukah Anda mengirimkan balasannya paling lambat besok?"}'::jsonb, '["明日までに","返事を","送って","いただけませんか。"]'::jsonb, NULL, NULL, 'Gunakan までに untuk batas waktu dan bentuk て + いただけませんか untuk permohonan sopan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('adc1df8a-a182-404c-bdda-9527b175ffbf', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi pola Kenjougo お + [Akar Masu] + します untuk 持ちます (membawa): お荷物を___。', '{"options":["お持ちします","持ちられます","持ってあります","お持ちになります"],"translation":"Biar saya yang membawakan barang bawaan Anda.","sentence_template":"お荷物を[blank]。"}'::jsonb, '{"selected":"お持ちします"}'::jsonb, NULL, NULL, 'Kenjougo merendahkan tindakan pembicara sendiri: お + 持ち + します -> お持ちします. (お持ちになります adalah Sonkeigo untuk lawan bicara).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e09049bb-b888-460e-b59c-08ac33fc54b3', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Pilih bentuk Kenjougo khusus dari 行きます / 来ます (pergi / datang): 明日、十時にそちらへ___。', '{"options":["なさいます","まいります","おっしゃいます","いらっしゃいます"],"translation":"Besok pukul sepuluh saya akan datang ke tempat Anda.","sentence_template":"明日、十時にそちらへ[blank]。"}'::jsonb, '{"selected":"まいります"}'::jsonb, NULL, NULL, 'まいります adalah Kenjougo dari 行きます/来ます (dipakai untuk tindakan pembicara sendiri).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('264f9e87-ec60-4735-8ae2-af6a610d0163', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Pilih bentuk Kenjougo khusus dari 言います (mengatakan / bernama): 私は桜株式会社の田中と___。', '{"options":["召し上がります","おっしゃいます","申します","ご覧になります"],"translation":"Nama saya Tanaka dari PT Sakura.","sentence_template":"私は桜株式会社の田中と[blank]。"}'::jsonb, '{"selected":"申します"}'::jsonb, NULL, NULL, '申します (moushimasu) adalah bentuk merendah dari 言います, wajib dipakai saat memperkenalkan diri secara formal.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('29d997e0-b023-4f4f-a478-50e913cd5db8', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan membawakan dokumen itu sekarang."', '{"romaji":"Ima sugu shiryou o omochi shimasu.","tokens":["資料を","します。","今すぐ","お持ちになります。","持ちます。","お持ち"],"target_translation":"Saya akan membawakan dokumen itu sekarang."}'::jsonb, '["今すぐ","資料を","お持ち","します。"]'::jsonb, NULL, NULL, 'お持ちします merendahkan tindakan pembicara yang membawa dokumen untuk atasan/tamu.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2127a762-0049-4627-9268-2653c7010719', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menelepon Anda kembali nanti."', '{"romaji":"Ato de kochira kara odenwa itashimasu.","tokens":["お電話になります。","聞きます。","いたします。","お電話","あとで","こちらから"],"target_translation":"Saya akan menelepon Anda kembali nanti."}'::jsonb, '["あとで","こちらから","お電話","いたします。"]'::jsonb, NULL, NULL, 'お電話いたします adalah bentuk Kenjougo yang sangat santun untuk ''saya akan menelepon''.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1deefe87-db0e-4648-8c2f-2ac713d43468', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan memeriksa jadwalnya terlebih dahulu."', '{"romaji":"Tadaima sukejuuru o kakunin itashimasu.","display_text":"ただいまスケジュールを確認いたします。","phonetic_breakdown":["ta-da-i-ma","su-ke-ju-u-ru","o","ka-ku-nin","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"ただいまスケジュールを確認いたします。"}'::jsonb, NULL, NULL, 'いたします adalah bentuk merendah dari します -> 確認いたします (saya akan memeriksa).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9daf4f9-acb2-4e74-87ce-6f07cccc2b5c', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 重そうな荷物ですね。私がお持ち___。', '{"options":["いらっしゃいます","します","くださいます","なります"],"translation":"Barang bawaannya tampak berat ya. Biar saya bawakan.","sentence_template":"重そうな荷物ですね。私がお持ち[blank]。"}'::jsonb, '{"selected":"します"}'::jsonb, NULL, NULL, 'Pola Kenjougo お + bentuk ます (tanpa ます) + します digunakan untuk merendahkan tindakan diri sendiri demi menghormati lawan bicara.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b3bd42ea-ffa9-4052-9508-4a7ba451abbe', '93cc9e35-8317-41f3-8a2e-ee77d414829a', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Besok pukul tiga sore saya akan berkunjung ke perusahaan Anda."', '{"romaji":"Ashita gogo sanji ni onsha e ukagaimasu.","tokens":["午後三時に","明日","うかがいます。","いらっしゃいます。","を","御社へ"],"target_translation":"Besok pukul tiga sore saya akan berkunjung ke perusahaan Anda."}'::jsonb, '["明日","午後三時に","御社へ","うかがいます。"]'::jsonb, NULL, NULL, 'うかがいます (ukagaimasu) adalah bentuk Kenjougo dari 行きます saat mengunjungi pihak yang dihormati.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('188a47fc-ad4a-4440-af80-c34eb6b1cd40', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Pilih pola yang menyatakan keadaan hasil aksi disengaja: 窓が___。換気のために誰かが開けたようです。', '{"options":["開けてあります","開けています","開けました","開けます"],"translation":"Jendela sengaja dibiarkan terbuka. Sepertinya seseorang membukanya untuk ventilasi.","sentence_template":"窓が[blank]。換気のために誰かが開けたようです。"}'::jsonb, '{"selected":"開けてあります"}'::jsonb, NULL, NULL, '開けます (verba transitif) + てあります menyatakan jendela dalam keadaan terbuka karena sengaja dibuka untuk suatu tujuan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d19eb20-83b7-4d8e-92d8-d44d0add0a64', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Pilih partikel yang tepat untuk pola ～てあります: 机の上にメモ___置いてあります。', '{"options":["まで","が","から","で"],"translation":"Di atas meja ada catatan yang sengaja diletakkan.","sentence_template":"机の上にメモ[blank]置いてあります。"}'::jsonb, '{"selected":"が"}'::jsonb, NULL, NULL, 'Dalam pola [Benda] が [Verba Transitif-TE] あります, partikel yang umum digunakan untuk menandai objek keadaan adalah が.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6ade9dba-a95e-40e7-9d3a-807c0f5ace16', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi bentuk TE verba transitif 消します (mematikan): 会議室の電気はもう___あります。', '{"options":["消えて","消って","消して","消んで"],"translation":"Lampu ruang rapat sudah dimatikan.","sentence_template":"会議室の電気はもう[blank]あります。"}'::jsonb, '{"selected":"消して"}'::jsonb, NULL, NULL, '消します (transitif: mematikan) berubah menjadi 消して + あります. 消えて adalah intransitif.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('80c4dd33-3472-48ff-86a9-e6a89fa5ccdc', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di kalender sudah dituliskan tanggal rapat."', '{"romaji":"Karendaa ni kaigi no hi ga kaite arimasu.","tokens":["あります。","会議の日が","書いています","会議の日を","カレンダーに","書いて"],"target_translation":"Di kalender sudah dituliskan tanggal rapat."}'::jsonb, '["カレンダーに","会議の日が","書いて","あります。"]'::jsonb, NULL, NULL, 'カレンダーに (di kalender) + 会議の日が (tanggal rapat) + 書いてあります (sudah tertulis).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('961e26c8-952c-4a01-bfad-af3fcf398f31', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Kursi-kursi sudah ditata rapi di aula."', '{"romaji":"Hooru ni isu ga kirei ni narabete arimasu.","tokens":["並んで","並べて","あります。","いすが","きれいに","並べます","ホールに"],"target_translation":"Kursi-kursi sudah ditata rapi di aula."}'::jsonb, '["ホールに","いすが","きれいに","並べて","あります。"]'::jsonb, NULL, NULL, '並べます adalah verba transitif (menata), sehingga 並べてあります berarti sudah ditata dengan sengaja.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f06bb2eb-e4bc-47e9-bc74-d65b4e0c8f3f', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di kotak ini sudah tertulis nama pemiliknya."', '{"romaji":"Kono hako ni mochinushi no namae ga kaite arimasu.","display_text":"この箱に持ち主の名前が書いてあります。","phonetic_breakdown":["ko-no","ha-ko","ni","mo-chi-nu-shi","no","na-ma-e","ga","ka-i-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"この箱に持ち主の名前が書いてあります。"}'::jsonb, NULL, NULL, '持ち主 (mochinushi) berarti pemilik; 書いてあります menunjukkan nama tersebut sengaja ditulis di kotak.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4fe83518-5c26-4c09-91db-d098b939693c', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 黒板に今日の予定が書いて___。', '{"options":["みせます","あります","しまいます","います"],"translation":"Jadwal hari ini sudah tertulis di papan tulis.","sentence_template":"黒板に今日の予定が書いて[blank]。"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, 'Bentuk て + あります dengan partikel が pada objek menekankan kondisi hasil tindakan yang sengaja dilakukan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2fef1c0-512d-4799-a15f-b661a234740b', '94e24275-54cb-409e-89c8-265ffe304909', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di dinding sudah tergantung sebuah kalender besar."', '{"romaji":"Kabe ni ookina karendaa ga kakete arimasu.","tokens":["を","あります。","壁に","掛かって","掛けて","大きな","カレンダーが"],"target_translation":"Di dinding sudah tergantung sebuah kalender besar."}'::jsonb, '["壁に","大きな","カレンダーが","掛けて","あります。"]'::jsonb, NULL, NULL, '掛かる (intransitif) berbeda dengan 掛ける (transitif). Pola ～てあります menggunakan kata kerja transitif 掛けて.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e00b888-e379-464f-9026-944fc1e42468', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan komentar berikut. Mengapa pembicara menggunakan 開けてあります?', '{"options":[{"id":"opt_1","text":"Jendela sengaja dibiarkan sedikit terbuka untuk ventilasi"},{"id":"opt_2","text":"Jendela ruang kelas rusak tidak bisa ditutup"},{"id":"opt_3","text":"Jendela terbuka sendiri karena angin kencang"},{"id":"opt_4","text":"Pembicara meminta lawan bicara menutup semua jendela"}],"audio_text":"窓が少し開けてありますね。換気のためですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '開けてあります (transitif) menunjukkan seseorang sengaja membuka jendela demi tujuan tertentu, misalnya ventilasi.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cfa9376a-6e7b-4980-b376-0e6955d87ada', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Peta lokasi acara sudah dicantumkan di surat undangan ini."', '{"romaji":"Kaijou no chizu wa kono annaijou ni nosete arimasu.","display_text":"会場の地図はこの案内状に載せてあります。","phonetic_breakdown":["kai-jou-no","chi-zu-wa","ko-no","an-nai-jou-ni","no-se-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"会場の地図はこの案内状に載せてあります。"}'::jsonb, NULL, NULL, '載せる (noseru) berarti mencantumkan; 載せてあります berarti sudah tercantum.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae4c194b-92f5-4d79-88e7-bdbe9804d26e', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Semua lampu sudah dimatikan, jadi mari kita keluar."', '{"romaji":"Denki wa zenbu keshite arimasu kara demashou.","tokens":["ありますから","出ましょう。","全部","消して","消えます","電気は","のに"],"target_translation":"Semua lampu sudah dimatikan, jadi mari kita keluar."}'::jsonb, '["電気は","全部","消して","ありますから","出ましょう。"]'::jsonb, NULL, NULL, '消してあります menegaskan tindakan mematikan lampu sudah dilakukan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c4894148-88fb-41b2-87c3-20279b08ce56', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 名簿に新しいメンバーの名前が___あります。', '{"options":["加える","加え","加えた","加えて"],"translation":"Nama anggota baru sudah ditambahkan ke dalam daftar nama.","sentence_template":"名簿に新しいメンバーの名前が[blank]あります。"}'::jsonb, '{"selected":"加えて"}'::jsonb, NULL, NULL, '加える (kuwaeru, menambahkan) -> bentuk て adalah 加えて.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ee2678e6-2e24-45bd-a0ff-90dc63239206', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan informasi dari rekan kerja berikut. Bagaimana status tiket dinas?', '{"options":[{"id":"opt_1","text":"Dinas ke luar kota dibatalkan karena tiket habis"},{"id":"opt_2","text":"Tiket shinkansen untuk dinas sudah dibeli dan ada di laci meja"},{"id":"opt_3","text":"Tiket shinkansen untuk dinas belum sempat dibeli"},{"id":"opt_4","text":"Pembicara meminta rekan kerja membeli tiket shinkansen"}],"audio_text":"出張の新幹線のチケットはもう買ってありますよ。机の引き出しです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '買ってあります menyatakan tiket sudah selesai dibeli sebelumnya.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5dc3befb-7346-40cf-8aad-39676fddefc0', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Data komputer sudah disimpan di cloud."', '{"romaji":"Pasokon no deeta wa kuraudo ni hozon shite arimasu.","display_text":"パソコンのデータはクラウドに保存してあります。","phonetic_breakdown":["pa-so-kon-no","dee-ta-wa","ku-ra-u-do-ni","ho-zon-shi-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"パソコンのデータはクラウドに保存してあります。"}'::jsonb, NULL, NULL, '保存してあります menunjukkan data telah diamankan sebagai langkah antisipasi.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21356ac5-0c35-41bf-9b6b-cd36348d8764', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di vas bunga sudah dihiasi bunga yang indah."', '{"romaji":"Kabin ni kirei na hana ga kazatte arimasu.","tokens":["花瓶に","飾って","飾ります。","を","きれいな","花が","あります。"],"target_translation":"Di vas bunga sudah dihiasi bunga yang indah."}'::jsonb, '["花瓶に","きれいな","花が","飾って","あります。"]'::jsonb, NULL, NULL, '飾る (kazaru, menghias/memajang) -> 飾ってあります.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95bb52bc-3b43-4c09-b3a7-41bdcca0ff51', '99a4293e-2ea5-426a-92cb-a827e322bb09', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 入り口の掲示板に試験の日程が___あります。', '{"options":["知らせる","知らせた","知らせて","知らせ"],"translation":"Di papan pengumuman pintu masuk sudah diumumkan jadwal ujian.","sentence_template":"入り口の掲示板に試験の日程が[blank]あります。"}'::jsonb, '{"selected":"知らせて"}'::jsonb, NULL, NULL, '知らせてあります menunjukkan pengumuman sudah dipasang secara sengaja.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f83506d1-59cb-41d6-9878-9be84b071609', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena di luar hujan, sebaiknya membawa payung."', '{"romaji":"Soto wa ame desu kara, kasa o motte itta hou ga ii desu yo.","display_text":"外は雨ですから、傘を持って行ったほうがいいですよ。","phonetic_breakdown":["so-to","wa","a-me","de-su","ka-ra","ka-sa","o","mot-te","it-ta","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"外は雨ですから、傘を持って行ったほうがいいですよ。"}'::jsonb, NULL, NULL, '持って行きます (membawa pergi) -> 持って行った + ほうがいいですよ.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('788b370e-3a64-494f-95c0-c120b73bfec2', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya mencatat hal penting di buku catatan."', '{"romaji":"Daiji na koto wa memo ni kaita hou ga ii desu.","display_text":"大事なことはメモに書いたほうがいいです。","phonetic_breakdown":["da-i-ji","na","ko-to","wa","me-mo","ni","ka-i-ta","ho-u","ga","i-i","de-su"]}'::jsonb, '{"expected_transcript":"大事なことはメモに書いたほうがいいです。"}'::jsonb, NULL, NULL, '書きます -> 書いた + ほうがいいです adalah nasihat kerja yang sangat umum di Jepang.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eac803cd-284d-4b3e-9f39-2d97cbadb987', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya tidak minum kopi terlalu malam."', '{"romaji":"Yoru osoku koohii o nomanai hou ga ii desu yo.","display_text":"夜遅くコーヒーを飲まないほうがいいですよ。","phonetic_breakdown":["yo-ru","o-so-ku","ko-o-hi-i","o","no-ma-na-i","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"夜遅くコーヒーを飲まないほうがいいですよ。"}'::jsonb, NULL, NULL, '飲みます -> 飲まない + ほうがいいですよ menyarankan agar tidak minum kopi larut malam.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ca30d7d3-58e0-412b-b079-95846d51a000', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya segera menghubungi atasan jika terjadi masalah."', '{"romaji":"Mondai ga attara, sugu joushi ni houkoku shita hou ga ii desu.","tokens":["報告して","報告した","ほうがいいです。","すぐ上司に","報告する","問題があったら、"],"target_translation":"Sebaiknya segera menghubungi atasan jika terjadi masalah."}'::jsonb, '["問題があったら、","すぐ上司に","報告した","ほうがいいです。"]'::jsonb, NULL, NULL, '報告します (melapor) -> Bentuk TA: 報告した + ほうがいいです.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f914710f-f04e-4765-a650-74fb546d501f', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya tidak memaksakan diri saat demam."', '{"romaji":"Netsu ga aru toki wa, muri o shinai hou ga ii desu.","tokens":["熱があるときは、","します","ほうがいいです。","無理を","しない","した"],"target_translation":"Sebaiknya tidak memaksakan diri saat demam."}'::jsonb, '["熱があるときは、","無理を","しない","ほうがいいです。"]'::jsonb, NULL, NULL, '無理をします (memaksakan diri) -> bentuk NAI: 無理をしない + ほうがいいです.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d5058efe-61fb-4c77-842f-88aa8d07ed12', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya berangkat tiga puluh menit lebih awal."', '{"romaji":"Sanjuppun hayaku shuppatsu shita hou ga ii desu yo.","tokens":["三十分","早く","出発して","出発する","ほうがいいですよ。","出発した"],"target_translation":"Sebaiknya berangkat tiga puluh menit lebih awal."}'::jsonb, '["三十分","早く","出発した","ほうがいいですよ。"]'::jsonb, NULL, NULL, '出発します (berangkat) -> 出発した + ほうがいいですよ.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92a320b3-c757-42d5-a939-c5282f95e8e8', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya setiap hari berolahraga meskipun sedikit."', '{"romaji":"Mainichi sukoshi demo undou shita hou ga ii desu yo.","display_text":"毎日少しでも運動したほうがいいですよ。","phonetic_breakdown":["mai-ni-chi","su-ko-shi-de-mo","un-dou-shi-ta","hou-ga","ii-de-su-yo"]}'::jsonb, '{"expected_transcript":"毎日少しでも運動したほうがいいですよ。"}'::jsonb, NULL, NULL, '運動したほうがいい menyatakan saran kesehatan yang hangat dan sopan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c49f0f1-c189-4867-88c1-a65017b26700', '9f641c26-498d-4e99-8846-91d915f2e53a', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Saat kondisi tubuh kurang sehat, sebaiknya tidak memaksakan diri masuk kerja."', '{"romaji":"Taichou ga warui toki wa muri ni shukkin shinai hou ga ii desu.","tokens":["体調が","いいです。","出勤した","出勤しない","へ","悪いときは","無理に","ほうが"],"target_translation":"Saat kondisi tubuh kurang sehat, sebaiknya tidak memaksakan diri masuk kerja."}'::jsonb, '["体調が","悪いときは","無理に","出勤しない","ほうが","いいです。"]'::jsonb, NULL, NULL, '出勤しないほうがいい berarti sebaiknya tidak masuk kerja.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f8819422-ed35-41fe-95ee-4aeebc298be5', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di kantor ini kita harus memakai sepatu kerja khusus."', '{"romaji":"Koko de wa senyou no sagyougutsu o hakanakereba narimasen.","display_text":"ここでは専用の作業靴を履かなければなりません。","phonetic_breakdown":["ko-ko","de","wa","sen-yo-u","no","sa-gyo-u-gu-tsu","o","ha-ka-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"ここでは専用の作業靴を履かなければなりません。"}'::jsonb, NULL, NULL, '履きます (memakai alas kaki) -> 履かない -> 履かなければなりません.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6607dea-a661-4c6a-8bf3-664cacfbd555', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum pulang, kita harus mematikan semua komputer."', '{"romaji":"Kaeru mae ni, pasokon no dengen o zenbu kiranakereba narimasen.","display_text":"帰る前に、パソコンの電源を全部切らなければなりません。","phonetic_breakdown":["ka-e-ru","ma-e","ni","pa-so-kon","no","den-gen","o","zen-bu","ki-ra-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"帰る前に、パソコンの電源を全部切らなければなりません。"}'::jsonb, NULL, NULL, '電源を切ります (mematikan daya) -> 切らない -> 切らなければなりません.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f76a4b61-7e4f-4f36-8da5-b7dfb0d050d5', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Besok pagi saya harus bangun jam lima."', '{"romaji":"Ashita no asa wa goji ni okinakereba narimasen.","display_text":"明日の朝は五時に起きなければなりません。","phonetic_breakdown":["a-shi-ta","no","a-sa","wa","go-ji","ni","o-ki-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日の朝は五時に起きなければなりません。"}'::jsonb, NULL, NULL, '起きます (Grup 2) -> 起きない -> 起きなければなりません.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('77d3d040-073a-4268-80d9-755c558b4c80', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Kita harus menulis laporan setiap hari sebelum pulang."', '{"romaji":"Mainichi kaeru mae ni nippou o kakanakereba narimasen.","tokens":["帰る前に","なりません。","毎日","書きます","書かなければ","書いて","日報を"],"target_translation":"Kita harus menulis laporan setiap hari sebelum pulang."}'::jsonb, '["毎日","帰る前に","日報を","書かなければ","なりません。"]'::jsonb, NULL, NULL, '日報 (nippou) adalah laporan harian kerja; 書きます -> 書かなければなりません.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6efe07f5-999a-4a60-918a-7dced5637354', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Di dalam kereta kita harus mematikan suara ponsel."', '{"romaji":"Densha no naka de wa keitai o manaamoodo ni shinakereba narimasen.","tokens":["マナーモードに","なりません。","しなければ","電車の中では","します","した","携帯を"],"target_translation":"Di dalam kereta kita harus mematikan suara ponsel."}'::jsonb, '["電車の中では","携帯を","マナーモードに","しなければ","なりません。"]'::jsonb, NULL, NULL, 'マナーモードにします (mengatur ke mode senyap) -> しなければなりません.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fd8f82a1-9eec-4844-9211-52d74f0ad772', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Saya harus segera menghubungi manajer."', '{"romaji":"Sugu ni buchou ni renraku shinakereba narimasen.","tokens":["部長に","すぐに","連絡します","連絡して","なりません。","連絡しなければ"],"target_translation":"Saya harus segera menghubungi manajer."}'::jsonb, '["すぐに","部長に","連絡しなければ","なりません。"]'::jsonb, NULL, NULL, 'すぐに (segera) + 部長に (kepada manajer) + 連絡しなければなりません.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbc2b995-e95b-4645-b1ab-a8fbfe104033', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sampah harus dibuang pada hari yang sudah ditentukan."', '{"romaji":"Gomi wa kimerareta youbi ni dasanakereba narimasen.","display_text":"ゴミは決められた曜日に出さなければなりません。","phonetic_breakdown":["go-mi-wa","ki-me-ra-re-ta","you-bi-ni","da-sa-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"ゴミは決められた曜日に出さなければなりません。"}'::jsonb, NULL, NULL, '出す -> 出さない -> 出さなければなりません adalah aturan penting dalam kehidupan sehari-hari di Jepang.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('496f8196-0dd6-40a4-8769-19df7788b379', 'a96727a0-c619-4298-b48e-ca2d92305e73', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Saat pergi ke rumah sakit, harus membawa kartu asuransi kesehatan."', '{"romaji":"Byouin e iku toki wa hokenshou o motte ikanakereba narimasen.","tokens":["行くときは","なりません。","へ","持って行きます。","持って行かなければ","保険証を","病院へ"],"target_translation":"Saat pergi ke rumah sakit, harus membawa kartu asuransi kesehatan."}'::jsonb, '["病院へ","行くときは","保険証を","持って行かなければ","なりません。"]'::jsonb, NULL, NULL, '保険証 (hokenshou) adalah kartu asuransi; 持って行く -> 持って行かなければなりません.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bdb843b8-69d4-43bc-8c06-348c56086e09', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会議の前に、この___をコピーします。', '{"options":["資料","趣味","天気","景色"],"translation":"Sebelum rapat, saya memfotokopi dokumen ini.","sentence_template":"会議の前に、この[blank]をコピーします。"}'::jsonb, '{"selected":"資料"}'::jsonb, NULL, NULL, '資料 (shiryou) berarti dokumen atau materi rapat. Pilihan lain berarti cuaca, pemandangan, dan hobi.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('949cceff-04e2-4430-a88d-35941f7437ad', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'reading', 'fill_blank', 'Lengkapi kata kerja kantor berikut: 先輩に新しい機械の使い方を___してもらいました。', '{"options":["運動","説明","散歩","旅行"],"translation":"Saya meminta senior menjelaskan cara menggunakan mesin baru.","sentence_template":"先輩に新しい機械の使い方を[blank]してもらいました。"}'::jsonb, '{"selected":"説明"}'::jsonb, NULL, NULL, '説明 (setsumei) berarti penjelasan; 説明する berarti menjelaskan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5afd1475-83ca-4cc3-aad1-a1d294e4ae6e', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang sedang dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Meminta menulis nama di meja resepsionis"},{"id":"opt_2","text":"Meminta membayar tagihan di kasir"},{"id":"opt_3","text":"Meminta menunggu di luar gedung"},{"id":"opt_4","text":"Meminta mengambil paket di gudang"}],"audio_text":"すみません、受付で名前を書いてください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '受付 (uketsuke) adalah meja resepsionis, dan 名前を書いてください berarti tolong tulis nama Anda.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7469c0d6-12a5-4464-a3de-d1cbc5f25a70', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Dokumen apa yang perlu diperiksa?', '{"options":[{"id":"opt_1","text":"Jadwal libur bulan depan"},{"id":"opt_2","text":"Laporan hari ini"},{"id":"opt_3","text":"Daftar hadir pelatihan"},{"id":"opt_4","text":"Kwitansi perjalanan dinas"}],"audio_text":"部長、今日の報告書を確認お願いします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '報告書 (houkokusho) berarti laporan, dan 確認 (kakunin) berarti pemeriksaan atau konfirmasi.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('12eebb17-5fb8-4b4f-ad5b-d8250e0f1062', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Saya mengirim email konfirmasi kepada pelanggan."', '{"romaji":"Okyakusama ni kakunin no meeru o okurimasu.","tokens":["お客様に","送ります。","駅で","確認の","食べます。","メールを"],"target_translation":"Saya mengirim email konfirmasi kepada pelanggan."}'::jsonb, '["お客様に","確認の","メールを","送ります。"]'::jsonb, NULL, NULL, 'お客様に (kepada pelanggan) + 確認のメールを (email konfirmasi) + 送ります (mengirim).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ce1da84-c0d8-4012-9f01-2a3f78b28491', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf mengganggu, bolehkah saya bertanya sebentar?"', '{"romaji":"Sumimasen ga, chotto shitsumon shite mo ii desu ka.","display_text":"すみませんが、ちょっと質問してもいいですか。","phonetic_breakdown":["su-mi-ma-sen","ga","chot-to","shi-tsu-mon","shi-te","mo","i-i","de-su","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、ちょっと質問してもいいですか。"}'::jsonb, NULL, NULL, 'Ungkapan すみませんが dipakai sebagai pembuka sopan sebelum mengajukan pertanyaan atau permohonan di kantor.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a6add9c-1c5e-465a-8a88-12f3fcf42b65', 'aebc0c55-8705-4c53-916b-67d0deebb95c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 会議の資料を___していただけませんか。', '{"options":["確認","見学","散歩","予約"],"translation":"Maukah Anda memeriksa materi rapat ini?","sentence_template":"会議の資料を[blank]していただけませんか。"}'::jsonb, '{"selected":"確認"}'::jsonb, NULL, NULL, '確認 (kakunin) berarti memeriksa atau mengonfirmasi, cocok untuk dokumen rapat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('69a60163-e766-4257-a509-acf17992609e', 'aebc0c55-8705-4c53-916b-67d0deebb95c', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan kalimat sopan berikut. Apa yang diminta oleh pembicara?', '{"options":[{"id":"opt_1","text":"Meminta lawan bicara menyebutkan namanya sekali lagi dengan sangat sopan"},{"id":"opt_2","text":"Menanyakan nomor telepon kantor lawan bicara"},{"id":"opt_3","text":"Memberitahukan jadwal rapat yang baru"},{"id":"opt_4","text":"Meminta lawan bicara menunggu di ruang tamu"}],"audio_text":"恐れ入りますが、お名前をもう一度お伺いしてもよろしいでしょうか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お名前をもう一度お伺いしてもよろしいでしょうか adalah ungkapan sangat sopan untuk menanyakan kembali nama seseorang.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('25ad186f-5b5d-4824-ba7b-bc318392f76d', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''pulang lebih awal (izin)'': 具合が悪いので、今日は___させていただきます。', '{"options":["早退","歓迎","旅行","出張"],"translation":"Karena badan kurang sehat, hari ini saya mohon izin pulang lebih awal.","sentence_template":"具合が悪いので、今日は[blank]させていただきます。"}'::jsonb, '{"selected":"早退"}'::jsonb, NULL, NULL, '早退 (soutai) berarti pulang lebih awal dari jam kerja atau sekolah karena suatu keperluan/sakit.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0edb0291-9ef9-4198-8f4c-a7215d97cde6', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata gangguan kereta api: 事故で電車が二十分___しています。', '{"options":["買い物","遅延","運動","料理"],"translation":"Karena kecelakaan, kereta mengalami keterlambatan dua puluh menit.","sentence_template":"事故で電車が二十分[blank]しています。"}'::jsonb, '{"selected":"遅延"}'::jsonb, NULL, NULL, '遅延 (chien) berarti keterlambatan jadwal transportasi umum.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a460e318-bcc6-46e5-b9a1-abc711e21354', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'listening', 'listening_choice', 'Dengarkan telepon karyawan ini. Mengapa ia tidak bisa hadir di kantor?', '{"options":[{"id":"opt_1","text":"Keretanya mogok di stasiun"},{"id":"opt_2","text":"Ia demam sejak pagi sehingga meminta izin tidak masuk"},{"id":"opt_3","text":"Ia lupa membawa kartu akses kantor"},{"id":"opt_4","text":"Ia harus menemani tamu dari Indonesia"}],"audio_text":"すみません、朝から熱があるので、今日は会社を休ませていただけますか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '熱があるので (karena demam) + 休ませていただけますか (bolehkah saya izin libur).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aeedefdb-64e2-4a6b-bf82-5380b3bd1c89', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di stasiun. Mengapa jalur kereta dihentikan sementara?', '{"options":[{"id":"opt_1","text":"Karena ada perbaikan rel mendadak"},{"id":"opt_2","text":"Karena listrik di stasiun padam"},{"id":"opt_3","text":"Karena topan sedang mendekat sehingga kereta ekspres sore dibatalkan"},{"id":"opt_4","text":"Karena jumlah penumpang terlalu sedikit"}],"audio_text":"台風が近づいているので、午後の特急電車は運休になります。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '台風が近づいているので (karena topan mendekat) + 運休 (dibatalkan operasinya).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c7d7b88-669b-489e-94fc-81996eba33a2', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Karena jalanan macet, busnya datang terlambat."', '{"romaji":"Michi ga konde ita node, basu ga okuremashita.","tokens":["混んでいたので、","道が","バスが","混んでいました。","早かったです。","遅れました。"],"target_translation":"Karena jalanan macet, busnya datang terlambat."}'::jsonb, '["道が","混んでいたので、","バスが","遅れました。"]'::jsonb, NULL, NULL, '混んでいたので menyatakan penyebab keterlambatan secara objektif dan sopan.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('65fe6529-2c12-4f4e-a10f-ef6dc6a9d90a', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ada urusan keluarga, besok saya mohon izin cuti."', '{"romaji":"Kazoku no youji ga aru node, ashita yasumi o itadakitai desu.","display_text":"家族の用事があるので、明日休みをいただきたいです。","phonetic_breakdown":["ka-zo-ku","no","yo-u-ji","ga","a-ru","no-de","a-shi-ta","ya-su-mi","o","i-ta-da-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"家族の用事があるので、明日休みをいただきたいです。"}'::jsonb, NULL, NULL, '用事 (youji) berarti keperluan/urusan; ～ので sangat cocok dipakai saat mengajukan izin kepada atasan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('68016c31-36e8-4e91-92fb-5b03ab7c4c3d', 'b6cc7134-fc28-4525-9d38-53467e7993da', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 電車の___がありましたので、十分ほど遅れてしまいました。', '{"options":["遅延","散歩","卒業","招待"],"translation":"Karena ada keterlambatan kereta, saya terlambat sekitar sepuluh menit.","sentence_template":"電車の[blank]がありましたので、十分ほど遅れてしまいました。"}'::jsonb, '{"selected":"遅延"}'::jsonb, NULL, NULL, '遅延 (chien) adalah kosakata resmi untuk keterlambatan transportasi umum.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('626b3093-0377-4e05-9d30-9ec5eae53b87', 'b6cc7134-fc28-4525-9d38-53467e7993da', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan permohonan izin berikut. Apa yang diminta pembicara?', '{"options":[{"id":"opt_1","text":"Meminta izin pulang lebih awal hari ini karena ada urusan mendadak"},{"id":"opt_2","text":"Menanyakan jadwal kepulangan atasan"},{"id":"opt_3","text":"Meminta izin lembur hingga malam hari"},{"id":"opt_4","text":"Melaporkan bahwa besok akan mengambil cuti tahunan"}],"audio_text":"本日は急用ができましたので、早退させていただけないでしょうか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '急用 (kyuuyou) berarti urusan mendadak; 早退 (soutai) berarti pulang lebih awal.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eee13db3-d8ed-4df3-b527-6d82a7ad9d92', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Pilih pola yang tepat saat atasan/orang yang dihormati membantu kita (bentuk halus): 部長に仕事の相談に乗って___。', '{"options":["いただきました","やりました","あげました","くれましたか"],"translation":"Saya mendapat kesempatan berkonsultasi pekerjaan dengan Pak Manajer.","sentence_template":"部長に仕事の相談に乗って[blank]。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, NULL, NULL, '～ていただきました adalah bentuk merendah/sangat sopan dari ～てもらいました saat menerima bantuan dari atasan.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9166996-79e4-4316-adf9-96979e955a23', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Bedakan subjek dengan cermat: 友達が vs 友達に: 私が道に迷ったとき、親切な人が地図を見せて___。', '{"options":["あげました","くれました","やりました","もらいました"],"translation":"Ketika saya tersesat, orang yang ramah menunjukkan peta kepada saya.","sentence_template":"私が道に迷ったとき、親切な人が地図を見せて[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, 'Subjek pemberi kebaikan adalah 親切な人が (orang ramah itu) -> 見せてくれました.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e1a5937-9c9f-4c5d-a566-497592190677', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Siapa yang memperbaiki sepeda Budi?', '{"options":[{"id":"opt_1","text":"Teman sekamarnya"},{"id":"opt_2","text":"Bengkel sepeda di dekat rumahnya"},{"id":"opt_3","text":"Budi memperbaikinya sendiri"},{"id":"opt_4","text":"Senior di tempat kerjanya"}],"audio_text":"自転車が壊れたので、近所の自転車屋さんに直してもらいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '近所の自転車屋さんに直してもらいました berarti diperbaiki oleh tukang/bengkel sepeda di dekat rumah.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3dabd97f-81cc-40a2-8193-e346b153dbad', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita ini. Mengapa pembicara merasa sangat terbantu?', '{"options":[{"id":"opt_1","text":"Guru menuliskan CV-nya dari awal"},{"id":"opt_2","text":"Guru mengantarnya ke wawancara"},{"id":"opt_3","text":"Guru memeriksa CV bahasa Jepangnya dengan teliti"},{"id":"opt_4","text":"Guru meminjamkan jas wawancara"}],"audio_text":"日本語の履歴書を書いたあと、先生が丁寧にチェックしてくれました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '履歴書 (rirekisho) adalah CV/daftar riwayat hidup; 丁寧にチェックしてくれました berarti memeriksa dengan teliti.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93c76c45-0100-452b-a561-de44da6b479d', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya dibantu kakak mendaftar rekening bank."', '{"romaji":"Ani ni ginkou kouza no tetsuzuki o tetsudatte moraimashita.","tokens":["手伝って","もらいました。","あげました。","手続きを","くれました。","兄に","銀行口座の"],"target_translation":"Saya dibantu kakak mendaftar rekening bank."}'::jsonb, '["兄に","銀行口座の","手続きを","手伝って","もらいました。"]'::jsonb, NULL, NULL, '手続き (tetsuzuki) berarti prosedur/pengurusan; 兄に...手伝ってもらいました.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2fd6c700-d529-442c-92ac-2dfb0a22b03e', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena teman sedang sibuk, saya membelikan makan siang untuknya."', '{"romaji":"Tomodachi ga isogashisou datta node, hirugohan o katte agemashita.","display_text":"友達が忙しそうだったので、昼ご飯を買ってあげました。","phonetic_breakdown":["to-mo-da-chi","ga","i-so-ga-shi-so-u","dat-ta","no-de","hi-ru-go-han","o","kat-te","a-ge-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"友達が忙しそうだったので、昼ご飯を買ってあげました。"}'::jsonb, NULL, NULL, '買ってあげました menekankan tindakan baik yang pembicara lakukan untuk temannya.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5957d2e-cd6a-40c6-a3ac-87f627f7558f', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 雨の日に傘を持っていなかったので、クラスメートが貸して___。', '{"options":["おきました","くれました","あげました","もらいました"],"translation":"Di hari hujan saya tidak membawa payung, lalu teman sekelas meminjamkannya kepada saya.","sentence_template":"雨の日に傘を持っていなかったので、クラスメートが貸して[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, 'クラスメートが sebagai subjek pemberi kebaikan kepada saya -> 貸してくれました.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9f693021-d3da-4693-8565-e0b53433be82', 'b90df921-3f6f-4e9b-bbac-da8f4d8c4064', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya meminta guru mengoreksi daftar riwayat hidup bahasa Jepang saya."', '{"romaji":"Sensei ni Nihongo no rirekisho o tensaku shite moraimashita.","display_text":"先生に日本語の履歴書を添削してもらいました。","phonetic_breakdown":["sen-sei-ni","ni-hon-go-no","ri-re-ki-sho-o","ten-sa-ku-shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先生に日本語の履歴書を添削してもらいました。"}'::jsonb, NULL, NULL, '添削する (tensaku suru) berarti mengoreksi tulisan; ～てもらいました menyatakan menerima bantuan tersebut.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8b784a4a-bcdb-44c7-8c97-9775f907647d', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Pilih bentuk potensial yang tepat untuk します (melakukan): 週末なら、残業が___。', '{"options":["しられます","せます","できます","しえます"],"translation":"Kalau akhir pekan, saya bisa lembur.","sentence_template":"週末なら、残業が[blank]。"}'::jsonb, '{"selected":"できます"}'::jsonb, NULL, NULL, 'します (Grup 3) memiliki bentuk potensial tidak beraturan: できます.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53b0ff47-e78b-404b-98f9-32e7a5e18053', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat mengenai pembelian tiket online: スマホで簡単に新幹線の切符が___。', '{"options":["買られます","買えります","買います","買えます"],"translation":"Dengan ponsel pintar kita bisa membeli tiket Shinkansen dengan mudah.","sentence_template":"スマホで簡単に新幹線の切符が[blank]。"}'::jsonb, '{"selected":"買えます"}'::jsonb, NULL, NULL, '買います (kaimasu) -> ubah i ke e -> 買えます (kaemasu).', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c923be4a-fd76-4d74-b14b-ea0ce7bc5f57', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan percakapan di restoran. Mengapa tamu tidak memesan menu itu?', '{"options":[{"id":"opt_1","text":"Karena porsinya terlalu kecil"},{"id":"opt_2","text":"Karena harganya terlalu mahal"},{"id":"opt_3","text":"Karena tamu tidak bisa makan daging babi dan memilih menu ayam"},{"id":"opt_4","text":"Karena menu daging babi sudah habis"}],"audio_text":"すみません、私は豚肉が食べられないので、鶏肉の料理にします。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '豚肉が食べられない berarti tidak bisa makan daging babi; 鶏肉の料理にします memilih masakan ayam.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a4d8732-9329-49bf-812c-60c0a09a5cf5', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Kapan karyawan bisa mengambil cuti?', '{"options":[{"id":"opt_1","text":"Langsung pada hari pertama masuk kerja"},{"id":"opt_2","text":"Setelah bekerja selama dua tahun"},{"id":"opt_3","text":"Hanya saat musim dingin"},{"id":"opt_4","text":"Setelah enam bulan bergabung di perusahaan"}],"audio_text":"入社して六か月たてば、有給休暇が取れます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '六か月たてば有給休暇が取れます berarti setelah 6 bulan bisa mengambil cuti berbayar (yuukyuu kyuuka).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('63755dfc-3b85-4b97-8be5-7256a99eaed2', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat: "Dari kantor saya bisa pulang ke asrama dengan berjalan kaki."', '{"romaji":"Kaisha kara ryou made aruite kaeremasu.","tokens":["会社から","帰れます。","寮まで","帰ります。","歩いて","泳げます。"],"target_translation":"Dari kantor saya bisa pulang ke asrama dengan berjalan kaki."}'::jsonb, '["会社から","寮まで","歩いて","帰れます。"]'::jsonb, NULL, NULL, '帰ります (Grup 1) -> 帰れます (bisa pulang).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('45c8a06e-04de-4439-9c1c-6cb94d531d1b', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sekarang saya sudah bisa membaca peta kereta Jepang sendiri."', '{"romaji":"Ima wa hitori de Nihon no rosenzu ga yomemasu.","display_text":"今は一人で日本の路線図が読めます。","phonetic_breakdown":["i-ma","wa","hi-to-ri","de","ni-hon","no","ro-sen-zu","ga","yo-me-ma-su"]}'::jsonb, '{"expected_transcript":"今は一人で日本の路線図が読めます。"}'::jsonb, NULL, NULL, '路線図 (rosenzu) berarti peta jalur kereta; 読めます berarti bisa membaca.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b84c0ed-b713-4ac4-a178-fa4d4d5bc7fc', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 辛い料理は苦手ですが、少しなら___。', '{"options":["食べました","食べます","食べられます","食べさせます"],"translation":"Saya kurang suka makanan pedas, tetapi kalau sedikit bisa makan.","sentence_template":"辛い料理は苦手ですが、少しなら[blank]。"}'::jsonb, '{"selected":"食べられます"}'::jsonb, NULL, NULL, '食べる (kelompok 2) -> 食べられる (bisa makan).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2fc8b4b9-fa1b-47f0-8d53-8ca02dafd3c8', 'bf4fb6a6-ffeb-4fdb-a4cf-e10c81b566bb', 'd1000019-0000-0000-0000-000000000001', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dari stasiun bisa pergi ke kantor dengan berjalan kaki lima menit."', '{"romaji":"Eki kara aruite gofun de kaisha ni ikemasu.","display_text":"駅から歩いて五分で会社に行けます。","phonetic_breakdown":["e-ki-ka-ra","a-ru-i-te","go-fun-de","kai-sha-ni","i-ke-ma-su"]}'::jsonb, '{"expected_transcript":"駅から歩いて五分で会社に行けます。"}'::jsonb, NULL, NULL, '行く -> 行ける menyatakan kemudahan akses menuju suatu tempat.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('08b8a6c0-e669-4f82-a192-87ea318bcbd2', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''kartu nama'': 初めて会った取引先の方と___を交換しました。', '{"options":["定期券","領収書","名刺","切手"],"translation":"Saya bertukar kartu nama dengan mitra bisnis yang baru pertama kali ditemui.","sentence_template":"初めて会った取引先の方と[blank]を交換しました。"}'::jsonb, '{"selected":"名刺"}'::jsonb, NULL, NULL, '名刺 (meishi) berarti kartu nama; 名刺を交換する adalah etika bisnis dasar di Jepang.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f4f9ba1-270b-4e57-a684-8c768ce31d10', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata staf penanggung jawab: ただいま___がまいりますので、少々お待ちください。', '{"options":["観光客","留学生","運転手","担当者"],"translation":"Staf penanggung jawab akan segera datang, mohon tunggu sebentar.","sentence_template":"ただいま[blank]がまいりますので、少々お待ちください。"}'::jsonb, '{"selected":"担当者"}'::jsonb, NULL, NULL, '担当者 (tantousha) berarti orang yang bertanggung jawab menangani urusan tersebut.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6871f6f4-293c-4dcf-a135-5798ed973277', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'listening', 'listening_choice', 'Dengarkan sapaan di meja resepsionis. Apa maksud ucapan staf ini?', '{"options":[{"id":"opt_1","text":"Menawarkan minuman kepada tamu"},{"id":"opt_2","text":"Menunjukkan arah toilet"},{"id":"opt_3","text":"Menanyakan nama pemesan secara sangat sopan"},{"id":"opt_4","text":"Meminta tamu membayar di muka"}],"audio_text":"いらっしゃいませ。ご予約のお名前を伺ってもよろしいでしょうか。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '伺う (ukagau) adalah bentuk kenjougo dari 聞く (bertanya/mendengar).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('281903c3-569e-4335-be20-42c6fc6455e4', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'listening', 'listening_choice', 'Dengarkan salam perkenalan bisnis ini. Siapa nama pembicara?', '{"options":[{"id":"opt_1","text":"Namanya Indonesia"},{"id":"opt_2","text":"Namanya Mairimashita"},{"id":"opt_3","text":"Namanya belum disebutkan"},{"id":"opt_4","text":"Namanya Ari, datang dari Indonesia"}],"audio_text":"はじめまして、インドネシアからまいりました、アリと申します。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'アリと申します (Ari to moushimasu) adalah bentuk merendah sangat sopan untuk memperkenalkan nama.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bcddadb3-9fd1-489f-ab85-4b212bee45e8', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan memandu Anda ke ruang rapat."', '{"romaji":"Kaigishitsu made go-annai itashimasu.","tokens":["ご案内","いたします。","会議室まで","行きます。","食べます。"],"target_translation":"Saya akan memandu Anda ke ruang rapat."}'::jsonb, '["会議室まで","ご案内","いたします。"]'::jsonb, NULL, NULL, 'ご + [Nomina verba] + いたします (ご案内いたします) adalah pola Kenjougo bisnis yang sangat sopan.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90ae9e68-7cc7-43bb-bc64-a82f5c4465a9', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya sudah mengerti, segera saya kerjakan."', '{"romaji":"Kashikomarimashita. Sugu ni taiou itashimasu.","display_text":"かしこまりました。すぐに対応いたします。","phonetic_breakdown":["ka-shi-ko-ma-ri-ma-shi-ta","su-gu","ni","ta-i-o-u","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"かしこまりました。すぐに対応いたします。"}'::jsonb, NULL, NULL, 'かしこまりました adalah bentuk sangat sopan dari わかりました, dan 対応いたします berarti segera saya tangani.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('244124b4-4a9e-4d82-9ed5-7b5fdf5fa228', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: はじめまして、営業部のリナと___。よろしくお願いいたします。', '{"options":["おっしゃいます","召し上がります","いらっしゃいます","申します"],"translation":"Perkenalkan, nama saya Rina dari divisi penjualan. Mohon kerja samanya.","sentence_template":"はじめまして、営業部のリナと[blank]。よろしくお願いいたします。"}'::jsonb, '{"selected":"申します"}'::jsonb, NULL, NULL, '申します (moushimasu) adalah bentuk Kenjougo (merendah) dari 言います saat memperkenalkan diri.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a8f2e19-30e2-4aaa-8c05-88258de74aa3', 'c14a8f2d-95b4-4dd6-b4d7-d5cfd1d652b7', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan sapaan resepsionis berikut. Apa yang akan dilakukan staf?', '{"options":[{"id":"opt_1","text":"Tamu diminta langsung masuk ke ruang direktur"},{"id":"opt_2","text":"Penanggung jawab sedang cuti hari ini"},{"id":"opt_3","text":"Staf akan segera memanggil penanggung jawab dan meminta tamu menunggu sebentar"},{"id":"opt_4","text":"Staf meminta tamu menelepon kembali besok"}],"audio_text":"ただいま担当の者を呼んでまいりますので、少々お待ちくださいませ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'まいります adalah bentuk Kenjougo dari 行きます/来ます.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2efb196-48c9-418a-abc5-ac572fe0f370', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya menerima bantuan dari senior untuk menerjemahkan dokumen ini."', '{"romaji":"Senpai ni kono shorui o honyaku shite moraimashita.","display_text":"先輩にこの書類を翻訳してもらいました。","phonetic_breakdown":["sen-pa-i","ni","ko-no","sho-ru-i","o","hon-ya-ku","shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先輩にこの書類を翻訳してもらいました。"}'::jsonb, NULL, NULL, '翻訳する (menerjemahkan) + てもらいました berarti dibantu menerjemahkan oleh senior.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa02b92f-d459-4b74-9573-a76ef4798d78', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ibu mengirimkan makanan Indonesia kepada saya."', '{"romaji":"Haha ga Indoneshia no tabemono o okutte kuremashita.","display_text":"母がインドネシアの食べ物を送ってくれました。","phonetic_breakdown":["ha-ha","ga","in-do-ne-shi-a","no","ta-be-mo-no","o","o-kut-te","ku-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"母がインドネシアの食べ物を送ってくれました。"}'::jsonb, NULL, NULL, '母が (ibu melakukan untuk saya) -> 送ってくれました.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a45e3b29-d89d-49b6-a8e0-2f252a991f40', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya memotretkan foto untuk wisatawan itu."', '{"romaji":"Watashi wa kankoukyaku no shashin o totte agemashita.","display_text":"私は観光客の写真を撮ってあげました。","phonetic_breakdown":["wa-ta-shi","wa","kan-ko-u-kya-ku","no","sha-shin","o","tot-te","a-ge-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"私は観光客の写真を撮ってあげました。"}'::jsonb, NULL, NULL, '観光客 (kankoukyaku) berarti wisatawan; 撮ってあげました berarti saya mengambilkan foto untuk mereka.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5e6028f-66c5-4cb0-af3a-9cc83ee90d27', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya meminta teman mencarikan apartemen yang murah."', '{"romaji":"Tomodachi ni yasui apaato o sagashite moraimashita.","tokens":["くれました。","あげました。","探して","友達に","もらいました。","安いアパートを"],"target_translation":"Saya meminta teman mencarikan apartemen yang murah."}'::jsonb, '["友達に","安いアパートを","探して","もらいました。"]'::jsonb, NULL, NULL, '友達に (dari teman) + 探してもらいました (dibantu mencarikan).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1bf46f48-f1a3-4f19-b2e1-b602d70f7644', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Rekan kerja menggantikan shift saya hari Minggu."', '{"romaji":"Douryou ga nichiyoubi no shifuto o kawatte kuremashita.","tokens":["くれました。","あげました。","日曜日のシフトを","もらいました。","同僚が","代わって"],"target_translation":"Rekan kerja menggantikan shift saya hari Minggu."}'::jsonb, '["同僚が","日曜日のシフトを","代わって","くれました。"]'::jsonb, NULL, NULL, '代わります (menggantikan) -> 代わってくれました (rekan kerja berbaik hati menggantikan untuk saya).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e634fc05-8a46-4055-951c-88401865a768', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya membacakan buku cerita untuk anak kecil."', '{"romaji":"Watashi wa kodomo ni ehon o yonde agemashita.","tokens":["私は","くれました。","あげました。","読んで","もらいました。","子供に","絵本を"],"target_translation":"Saya membacakan buku cerita untuk anak kecil."}'::jsonb, '["私は","子供に","絵本を","読んで","あげました。"]'::jsonb, NULL, NULL, '絵本 (ehon) berarti buku bergambar; 私は...あげました berarti saya melakukan untuk anak tersebut.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b5307e9-5a4a-428c-9d76-aba139f78e1c', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Teman saya mengantarkan saya sampai bandara dengan mobil."', '{"romaji":"Tomodachi ga kuukou made kuruma de okutte kuremashita.","display_text":"友達が空港まで車で送ってくれました。","phonetic_breakdown":["to-mo-da-chi-ga","kuu-kou-ma-de","ku-ru-ma-de","o-kut-te","ku-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"友達が空港まで車で送ってくれました。"}'::jsonb, NULL, NULL, '送ってくれました menekankan rasa terima kasih atas bantuan teman kepada pembicara.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3be7d5b-bb4e-4e33-8921-b79435b3ee4e', 'cab219f5-431f-4928-86cf-2bd5a4362110', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Saya dibuatkan kue ulang tahun oleh ibu."', '{"romaji":"Haha ni tanjoubi no keeki o tsukutte moraimashita.","tokens":["誕生日の","もらいました。","母に","あげました。","が","ケーキを","作って"],"target_translation":"Saya dibuatkan kue ulang tahun oleh ibu."}'::jsonb, '["母に","誕生日の","ケーキを","作って","もらいました。"]'::jsonb, NULL, NULL, '母に (oleh ibu) + 作ってもらいました (menerima kebaikan dibuatkan).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b7fa8fb-3f5b-4ca7-9d39-201dcdb49645', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Review N4: Pilih kalimat Kenjougo yang tepat saat pembicara mengunjungi kantor klien: 来週の火曜日に、御社へ___。', '{"options":["おっしゃいます","なさいます","伺います","いらっしゃいます"],"translation":"Hari Selasa minggu depan, saya akan berkunjung ke perusahaan Anda.","sentence_template":"来週の火曜日に、御社へ[blank]。"}'::jsonb, '{"selected":"伺います"}'::jsonb, NULL, NULL, '伺います (ukagaimasu) adalah Kenjougo dari 行きます/訪問します (mengunjungi pihak yang dihormati).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae147a52-c367-45d5-a287-65c4cc8ea6cc', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Review Terpadu N4: Lengkapi kalimat yang menggabungkan alasan halus dan permohonan sangat sopan: 資料に少し間違いがあるようですので、もう一度確認して___。', '{"options":["あげませんか","おきますか","あります","いただけませんか"],"translation":"Karena sepertinya ada sedikit kesalahan pada dokumen, bersediakah Anda memeriksanya sekali lagi?","sentence_template":"資料に少し間違いがあるようですので、もう一度確認して[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, 'Gabungan ～ので (alasan halus) + ～ていただけませんか (permohonan sangat sopan) adalah pola inti JLPT N4.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4760dac9-c57e-45f6-a11e-0b9fdcffeb38', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan bisnis terpadu N4 ini. Apa yang akan dilakukan staf setelah memeriksa jadwal?', '{"options":[{"id":"opt_1","text":"Menyuruh tamu datang kembali minggu depan"},{"id":"opt_2","text":"Meminta tamu menelepon nomor lain"},{"id":"opt_3","text":"Menutup kantor lebih cepat hari ini"},{"id":"opt_4","text":"Menghubungi kembali segera setelah staf penanggung jawab pulang ke kantor"}],"audio_text":"申し訳ございません、ただいま担当者が外出しておりますので、戻り次第ご連絡いたします。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '外出しております (sedang keluar kantor) + 戻り次第ご連絡いたします (akan menghubungi begitu kembali).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('71349098-44a8-4e53-98bf-f0f740413ffa', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan arahan penutup pelatihan kerja ini. Apa pesan utama instruktur?', '{"options":[{"id":"opt_1","text":"Jika ada hal yang tidak dipahami, sebaiknya segera berkonsultasi dengan senior dan tidak memikirkannya sendirian"},{"id":"opt_2","text":"Semua masalah harus diselesaikan sendiri tanpa bertanya"},{"id":"opt_3","text":"Bertanya hanya boleh dilakukan pada hari Jumat"},{"id":"opt_4","text":"Senior tidak boleh diganggu saat jam kerja"}],"audio_text":"わからないことがあったら、一人で悩まないで、すぐ先輩に相談したほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kalimat ini memadukan ～たら (jika ada) + ～たほうがいい (sebaiknya berkonsultasi).', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4073e48b-418e-4629-acde-6a375dd76af6', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Besok pukul sembilan saya akan datang ke kantor Anda."', '{"romaji":"Ashita kuji ni onsha e mairimasu.","tokens":["御社へ","いらっしゃいます。","おっしゃいます。","明日","九時に","まいります。"],"target_translation":"Besok pukul sembilan saya akan datang ke kantor Anda."}'::jsonb, '["明日","九時に","御社へ","まいります。"]'::jsonb, NULL, NULL, '御社 (onsha) berarti perusahaan lawan bicara; まいります adalah Kenjougo dari 行きます/来ます.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6840ddc5-aeab-4138-b925-149925d906c2', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas bimbingan Anda hari ini."', '{"romaji":"Honjitsu wa goshidou itadaki, makoto ni arigatou gozaimashita.","display_text":"本日はご指導いただき、誠にありがとうございました。","phonetic_breakdown":["hon-ji-tsu","wa","go-shi-do-u","i-ta-da-ki","ma-ko-to","ni","a-ri-ga-to-u","go-za-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"本日はご指導いただき、誠にありがとうございました。"}'::jsonb, NULL, NULL, 'Ungkapan penutup bisnis tingkat N4 yang memadukan 本日 (hari ini), ご指導いただき (menerima bimbingan), dan 誠にありがとうございました.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f433ada3-4762-4085-b9cc-25f8876ec01f', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 詳しい日程につきましては、後ほど私からご連絡___。', '{"options":["いたします","なさいます","おっしゃいます","召し上がります"],"translation":"Mengenai jadwal rincinya, nanti saya yang akan menghubungi Anda.","sentence_template":"詳しい日程につきましては、後ほど私からご連絡[blank]。"}'::jsonb, '{"selected":"いたします"}'::jsonb, NULL, NULL, 'ご連絡いたします adalah bentuk Kenjougo untuk menghubungi klien atau atasan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7b9cfde-0268-406e-af97-1beacd708a42', 'cbbaaf25-f745-4750-bc80-a2075386c88e', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas kehadiran Anda hari ini."', '{"romaji":"Honjitsu wa okoshi itadaki, makoto ni arigatou gozaimasu.","display_text":"本日はお越しいただき、誠にありがとうございます。","phonetic_breakdown":["hon-ji-tsu-wa","o-ko-shi","i-ta-da-ki","ma-ko-to-ni","a-ri-ga-tou","go-za-i-ma-su"]}'::jsonb, '{"expected_transcript":"本日はお越しいただき、誠にありがとうございます。"}'::jsonb, NULL, NULL, 'Ungkapan penyambutan resmi ini memadukan お越しいただく dengan 誠にありがとうございます.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42f1a880-89ce-4b5a-a396-af7508b7dbd9', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Pilih sambungan yang tepat untuk bentuk sopan dengan ので: これから会議が始まり___ので、携帯電話の電源をお切りください。', '{"options":["ます","ますな","ますだ","まして"],"translation":"Karena rapat akan segera dimulai, mohon matikan daya ponsel Anda.","sentence_template":"これから会議が始まり[blank]ので、携帯電話の電源をお切りください。"}'::jsonb, '{"selected":"ます"}'::jsonb, NULL, NULL, 'Dalam pengumuman resmi/sangat sopan, ～ますので boleh digunakan langsung tanpa な atau だ.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7333222e-cf30-4cef-a412-53e71fe40605', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Pilih kalimat yang paling tepat untuk Nomina 外国人: 私は___ので、まだ日本の習慣をよく知りません。', '{"options":["外国人の","外国人な","外国人だ","外国人に"],"translation":"Karena saya orang asing, saya belum terlalu tahu kebiasaan Jepang.","sentence_template":"私は[blank]ので、まだ日本の習慣をよく知りません。"}'::jsonb, '{"selected":"外国人な"}'::jsonb, NULL, NULL, 'Nomina 外国人 + なので adalah bentuk baku yang tepat.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f54f551-1749-4bb8-aff5-dc8f6350434f', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak bisa ikut lembur hari ini?', '{"options":[{"id":"opt_1","text":"Ia harus menemui dokter gigi"},{"id":"opt_2","text":"Ia sudah berjanji makan malam dengan teman"},{"id":"opt_3","text":"Ia harus mengurus dokumen dari balai kota sehingga pulang tepat waktu"},{"id":"opt_4","text":"Ia merasa terlalu lelah bekerja"}],"audio_text":"申し訳ありません、今夜は市役所から届いた書類の手続きがあるので、定時で失礼します。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '定時で失礼します berarti pamit pulang tepat waktu sesuai jam kerja.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a6ffb01-b0dd-46f5-98b2-50662041a62a', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan penjelasan resepsionis. Mengapa tamu diminta menunggu di lobi?', '{"options":[{"id":"opt_1","text":"Karena staf penanggung jawab sedang cuti"},{"id":"opt_2","text":"Karena ruang pertemuan sedang dibersihkan"},{"id":"opt_3","text":"Karena tamu datang terlalu cepat satu jam"},{"id":"opt_4","text":"Karena staf penanggung jawab sedang mengikuti rapat lain"}],"audio_text":"ただいま担当者が別の会議に出ておりますので、ロビーで少々お待ちください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '別の会議に出ておりますので berarti karena sedang berada di rapat lain.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3498dae-0c67-40a5-bdec-6da535d65582', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat: "Karena hujan turun dengan deras, saya pulang naik taksi."', '{"romaji":"Ame ga hidoku futte iru node, takushii de kaerimasu.","tokens":["タクシーで","降っています。","雨が","歩いて","帰ります。","ひどく降っているので、"],"target_translation":"Karena hujan turun dengan deras, saya pulang naik taksi."}'::jsonb, '["雨が","ひどく降っているので、","タクシーで","帰ります。"]'::jsonb, NULL, NULL, 'ひどく降っている (turun deras) + ので menyatakan penyebab objektif.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b1c5e1f2-0162-4799-8249-9fa462776630', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masih ada waktu, mari kita periksa dokumen ini sekali lagi."', '{"romaji":"Mada jikan ga aru node, mou ichido kono shiryou o kakunin shimashou.","display_text":"まだ時間があるので、もう一度この資料を確認しましょう。","phonetic_breakdown":["ma-da","ji-kan","ga","a-ru","no-de","mo-u","i-chi-do","ko-no","shi-ryo-u","o","ka-ku-nin","shi-ma-sho-u"]}'::jsonb, '{"expected_transcript":"まだ時間があるので、もう一度この資料を確認しましょう。"}'::jsonb, NULL, NULL, '時間があるので + 確認しましょう sangat natural dipakai saat kerja tim di kantor.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('27bc4fd3-301c-4402-b638-ea6039e54aad', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 今日はとても___ので、洗濯物がすぐ乾きそうです。', '{"options":["天気がいい","天気がいいだ","天気がよかったな","天気がいいな"],"translation":"Karena hari ini cuacanya sangat bagus, cucian tampaknya akan cepat kering.","sentence_template":"今日はとても[blank]ので、洗濯物がすぐ乾きそうです。"}'::jsonb, '{"selected":"天気がいい"}'::jsonb, NULL, NULL, 'Kata sifat い (いい) langsung disambung dengan ので.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6e1e9f4a-df2a-4e91-b3ed-552a7cbbdb83', 'd07fc343-b7e3-4732-9f82-6e9b0a1b652e', 'd1000019-0000-0000-0000-000000000004', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kondisi tubuh agak kurang baik, hari ini saya izin beristirahat."', '{"romaji":"Sukoshi taichou ga warui node, kyou wa yasumasete itadakimasu.","display_text":"少し体調が悪いので、今日は休ませていただきます。","phonetic_breakdown":["su-ko-shi","tai-chou-ga","wa-ru-i-no-de","kyou-wa","ya-su-ma-se-te","i-ta-da-ki-ma-su"]}'::jsonb, '{"expected_transcript":"少し体調が悪いので、今日は休ませていただきます。"}'::jsonb, NULL, NULL, 'Pola 体調が悪いので sangat sopan untuk menyampaikan izin sakit di tempat kerja.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d86cac9-50a4-4974-b86c-4c2ec3ae7bfa', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Pilih bentuk keharusan yang tepat untuk kata kerja 来ます (datang): 明日は九時までに駅へ___なりません。', '{"options":["来なければ","来てければ","来るければ","来いなければ"],"translation":"Besok saya harus datang ke stasiun paling lambat jam sembilan.","sentence_template":"明日は九時までに駅へ[blank]なりません。"}'::jsonb, '{"selected":"来なければ"}'::jsonb, NULL, NULL, '来ます (kimasu, Grup 3) bentuk NAI-nya adalah 来ない (konai) -> 来なければなりません (konakereba narimasen).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0690e0e4-4ed2-4208-8d3f-cab78bb7e239', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi aturan keamanan data perusahaan: 会社のパソコンのパスワードは定期的に___なりません。', '{"options":["変えてければ","変えなければ","変えるければ","変えします"],"translation":"Kata sandi komputer perusahaan harus diganti secara berkala.","sentence_template":"会社のパソコンのパスワードは定期的に[blank]なりません。"}'::jsonb, '{"selected":"変えなければ"}'::jsonb, NULL, NULL, '変えます (mengubah, Grup 2) -> 変えない -> 変えなければなりません.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e993276-e091-4d5e-b274-bb89f99ea43b', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak bisa ikut makan malam?', '{"options":[{"id":"opt_1","text":"Dia harus menjemput temannya di bandara"},{"id":"opt_2","text":"Dia sudah makan sebelumnya"},{"id":"opt_3","text":"Dia kehabisan uang tunai"},{"id":"opt_4","text":"Dia harus belajar untuk ujian besok"}],"audio_text":"すみません、今夜は明日の試験のために勉強しなければならないんです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '明日の試験のために勉強しなければならない berarti harus belajar untuk ujian besok.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9a4ee549-d94e-495d-aea8-cbc8e596809d', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan instruksi kebersihan dapur. Kapan celemek harus diganti?', '{"options":[{"id":"opt_1","text":"Segera diganti dengan yang baru begitu kotor"},{"id":"opt_2","text":"Diganti seminggu sekali"},{"id":"opt_3","text":"Diganti hanya saat ada inspeksi"},{"id":"opt_4","text":"Tidak perlu diganti sampai shift selesai"}],"audio_text":"エプロンが汚れたら、すぐに新しいものに交換しなければなりません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '汚れたらすぐに新しいものに交換しなければなりません berarti jika kotor harus segera diganti dengan yang baru.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9c657439-2afd-40a2-b06a-e756a421e92f', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Saat masuk rumah orang Jepang, kita harus melepas sepatu."', '{"romaji":"Nihon no ie ni hairu toki wa, kutsu o nuganakereba narimasen.","tokens":["脱がなければ","履かなければ","入るときは、","靴を","脱いで","日本の家に","なりません。"],"target_translation":"Saat masuk rumah orang Jepang, kita harus melepas sepatu."}'::jsonb, '["日本の家に","入るときは、","靴を","脱がなければ","なりません。"]'::jsonb, NULL, NULL, '脱ぎます (melepas sepatu/pakaian) -> 脱がない -> 脱がなければなりません.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e2229cd-ba67-4e41-9ae0-d94a41be41df', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena besok ada rapat penting, saya tidak boleh terlambat dan harus datang lebih awal."', '{"romaji":"Ashita wa daiji na kaigi ga aru node, hayaku konakereba narimasen.","display_text":"明日は大事な会議があるので、早く来なければなりません。","phonetic_breakdown":["a-shi-ta","wa","da-i-ji","na","ka-i-gi","ga","a-ru","no-de","ha-ya-ku","ko-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日は大事な会議があるので、早く来なければなりません。"}'::jsonb, NULL, NULL, '来なければなりません dibaca ''konakereba narimasen'' (bukan kinakereba).', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92d48112-7c0c-4275-a7eb-67b0433abcb8', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 自転車に乗るときも、交通ルールを守ら___。', '{"options":["てしまいます","なければなりません","てはいけません","なくてもいいです"],"translation":"Saat naik sepeda pun, kita harus mematuhi aturan lalu lintas.","sentence_template":"自転車に乗るときも、交通ルールを守ら[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, '守る -> 守らない -> 守らなければなりません berarti wajib mematuhi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95052d75-edae-4e60-b30e-08e3ae4af56e', 'd4ce6b53-ce6b-452f-ae68-13bbd3183338', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum rapat, saya harus mencetak laporan."', '{"romaji":"Kaigi no mae ni houkokusho o insatsu shinakereba narimasen.","display_text":"会議の前に報告書を印刷しなければなりません。","phonetic_breakdown":["kai-gi-no","ma-e-ni","hou-ko-ku-sho-o","in-sa-tsu","shi-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"会議の前に報告書を印刷しなければなりません。"}'::jsonb, NULL, NULL, '印刷する -> 印刷しなければなりません menyatakan tugas wajib sebelum rapat.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('47119122-afb0-4702-af30-d653c65d5b4e', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Pilih kalimat yang tepat untuk menyatakan ruangan sudah dirapikan: お客様が来るので、応接室はもう___。', '{"options":["片付きました","片付けています","片付けてあります","片付けます"],"translation":"Karena tamu akan datang, ruang tamu kantor sudah dirapikan.","sentence_template":"お客様が来るので、応接室はもう[blank]。"}'::jsonb, '{"selected":"片付けてあります"}'::jsonb, NULL, NULL, '片付けます (merapikan, transitif) + てあります menekankan kesiapan ruangan untuk tamu.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('94e0e33d-dda0-469e-aaba-14a00d7d3759', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat tentang petunjuk yang tertulis di mesin: このボタンの横に「緊急停止」と___あります。', '{"options":["話して","持って","送って","書いて"],"translation":"Di samping tombol ini tertulis ''Berhenti Darurat''.","sentence_template":"このボタンの横に「緊急停止」と[blank]あります。"}'::jsonb, '{"selected":"書いて"}'::jsonb, NULL, NULL, '「...」と書いてあります adalah pola sangat umum di Jepang untuk membaca label atau rambu.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('39b064bc-e75e-4d6c-818a-1a6e6a7ca73a', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja ini. Apa yang sudah dilakukan Tanaka?', '{"options":[{"id":"opt_1","text":"Tanaka sudah memesan sepuluh kotak bento untuk rapat besok"},{"id":"opt_2","text":"Tanaka lupa memesan makanan untuk rapat"},{"id":"opt_3","text":"Tanaka akan memesan bento besok pagi"},{"id":"opt_4","text":"Rapat besok tidak menyediakan makan siang"}],"audio_text":"田中さん、明日の会議の弁当は注文しましたか。ええ、十個注文してあります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '十個注文してあります berarti sepuluh kotak sudah dipesan sebelumnya.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0dbcfbdc-63b2-4ed8-b99b-cd76312c3fff', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang loker. Di mana helm kerja berada?', '{"options":[{"id":"opt_1","text":"Di gudang lantai satu"},{"id":"opt_2","text":"Di dalam loker masing-masing"},{"id":"opt_3","text":"Di meja kepala bagian"},{"id":"opt_4","text":"Di pintu masuk pabrik"}],"audio_text":"新しいヘルメットは、自分のロッカーの中に入れてありますので、確認してください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '自分のロッカーの中に入れてあります berarti sudah dimasukkan ke dalam loker masing-masing.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2df0535-24d6-4898-9e44-f71020c31ded', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Proyektor sudah dinyalakan di ruang rapat."', '{"romaji":"Kaigishitsu de purojekutaa ga tsukete arimasu.","tokens":["つけて","あります。","会議室で","つけます","ついて","プロジェクターが"],"target_translation":"Proyektor sudah dinyalakan di ruang rapat."}'::jsonb, '["会議室で","プロジェクターが","つけて","あります。"]'::jsonb, NULL, NULL, 'つけます (menyalakan, transitif) -> つけてあります.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82619fff-e6b6-4243-b86a-72cf9b364ed1', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semua dokumen yang diperlukan sudah dimasukkan ke dalam map."', '{"romaji":"Hitsuyou na shorui wa zenbu fairu ni irete arimasu.","display_text":"必要な書類は全部ファイルに入れてあります。","phonetic_breakdown":["hi-tsu-yo-u","na","sho-ru-i","wa","zen-bu","fa-i-ru","ni","i-re-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"必要な書類は全部ファイルに入れてあります。"}'::jsonb, NULL, NULL, '入れます (memasukkan) -> 入れてあります menyatakan semua berkas sudah rapi tersimpan di map.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('def41357-3a14-4fa0-b765-4eed24b0d3b0', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: ドアの横に非常口の案内が___あります。', '{"options":["貼って","貼った","貼る","貼り"],"translation":"Di samping pintu sudah ditempel petunjuk pintu darurat.","sentence_template":"ドアの横に非常口の案内が[blank]あります。"}'::jsonb, '{"selected":"貼って"}'::jsonb, NULL, NULL, '貼る (haru) -> bentuk て adalah 貼って, diikuti あります untuk hasil penempelan yang disengaja.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9865d40a-fd13-403b-93dc-1a53d70587b4', 'd7838805-e017-4a35-ac31-a4b509454f3b', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semua materi sudah dirangkum dalam satu folder."', '{"romaji":"Shiryou wa subete foruda ni matomete arimasu.","display_text":"資料はすべてフォルダにまとめてあります。","phonetic_breakdown":["shi-ryou-wa","su-be-te","fo-ru-da-ni","ma-to-me-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"資料はすべてフォルダにまとめてあります。"}'::jsonb, NULL, NULL, 'まとめてあります menunjukkan dokumen sudah dikumpulkan dan siap digunakan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('836ade24-80f2-4335-a313-392a14d1fe70', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat sebelum ほうがいい untuk saran positif: 熱が高いですから、早く病院へ___ほうがいいですよ。', '{"options":["行った","行きます","行く","行って"],"translation":"Karena demammu tinggi, sebaiknya segera pergi ke rumah sakit ya.","sentence_template":"熱が高いですから、早く病院へ[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"行った"}'::jsonb, NULL, NULL, 'Untuk saran positif ''sebaiknya melakukan'', gunakan [Verba Bentuk-TA] + ほうがいい -> 行ったほうがいい.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('273ee798-1035-4293-93b8-011a0cd8341f', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Pilih bentuk saran negatif ''sebaiknya tidak melakukan'': 今夜はお酒を___ほうがいいですよ。', '{"options":["飲んで","飲まない","飲みます","飲んだ"],"translation":"Malam ini sebaiknya tidak minum alkohol ya.","sentence_template":"今夜はお酒を[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"飲まない"}'::jsonb, NULL, NULL, 'Untuk saran negatif ''sebaiknya tidak'', gunakan [Verba Bentuk-NAI] + ほうがいい -> 飲まないほうがいい.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54001ffb-6902-431a-af22-3eddb252f338', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Ubah 休みます (beristirahat) ke pola saran positif: 無理をしないで、今日は家で___ほうがいいです。', '{"options":["休んで","休み","休んだ","休む"],"translation":"Jangan memaksakan diri, hari ini sebaiknya beristirahat di rumah.","sentence_template":"無理をしないで、今日は家で[blank]ほうがいいです。"}'::jsonb, '{"selected":"休んだ"}'::jsonb, NULL, NULL, '休みます -> Bentuk TA: 休んだ + ほうがいいです.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('af3f3436-13b6-410a-83c7-6116525dc2fd', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya tidur lebih cepat setiap malam."', '{"romaji":"Maiban hayaku neta hou ga ii desu.","tokens":["ほうが","寝た","寝て","いいです。","早く","寝る","毎晩"],"target_translation":"Sebaiknya tidur lebih cepat setiap malam."}'::jsonb, '["毎晩","早く","寝た","ほうが","いいです。"]'::jsonb, NULL, NULL, '寝ます (Grup 2) -> Bentuk TA: 寝た + ほうがいいです.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54fbaaf4-244e-4e1c-8257-8252dc5a3cdc', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sedang flu, sebaiknya tidak mandi berendam terlalu lama."', '{"romaji":"Kaze desu kara, nagaku ofuro ni hairanai hou ga ii desu.","tokens":["長く","入った","風邪ですから、","入らない","ほうがいいです。","入ります","お風呂に"],"target_translation":"Karena sedang flu, sebaiknya tidak mandi berendam terlalu lama."}'::jsonb, '["風邪ですから、","長く","お風呂に","入らない","ほうがいいです。"]'::jsonb, NULL, NULL, 'Saran larangan halus memakai bentuk NAI: 入らないほうがいいです.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0b73955-359e-4d82-af64-9e4ed0f49fbd', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya kamu segera minum obat ini."', '{"romaji":"Sugu ni kono kusuri o nonda hou ga ii desu yo.","display_text":"すぐにこの薬を飲んだほうがいいですよ。","phonetic_breakdown":["su-gu","ni","ko-no","ku-su-ri","o","non-da","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"すぐにこの薬を飲んだほうがいいですよ。"}'::jsonb, NULL, NULL, '飲みます -> 飲んだ + ほうがいいですよ memberikan saran yang hangat dan peduli.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('551a48f2-a9a1-4700-a8eb-b8d3c6025984', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 雨の予報が出ていますから、傘を持って___ほうがいいですよ。', '{"options":["行かない","行って","行く","行った"],"translation":"Karena prakiraan cuaca menunjukkan hujan, sebaiknya Anda membawa payung.","sentence_template":"雨の予報が出ていますから、傘を持って[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"行った"}'::jsonb, NULL, NULL, 'Saran positif memakai kata kerja bentuk た + ほうがいい (持って行く -> 持って行ったほうがいい).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b0bb3e7-6e82-4b78-ad09-05364b1728eb', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya jangan minum kopi larut malam."', '{"romaji":"Yoru osoku ni koohii o nomanai hou ga ii desu yo.","tokens":["飲まない","飲んだ","夜遅くに","いいですよ。","コーヒーを","ほうが","を"],"target_translation":"Sebaiknya jangan minum kopi larut malam."}'::jsonb, '["夜遅くに","コーヒーを","飲まない","ほうが","いいですよ。"]'::jsonb, NULL, NULL, 'Saran negatif memakai bentuk ない + ほうがいい (飲まないほうがいい).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('160f9a93-2cd4-461c-85d2-331c23e60b17', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan penjelasan staf toko. Mengapa toko tutup lebih awal hari ini?', '{"options":[{"id":"opt_1","text":"Karena sedang renovasi gedung"},{"id":"opt_2","text":"Karena listrik di area toko padam"},{"id":"opt_3","text":"Karena ada libur nasional"},{"id":"opt_4","text":"Karena ada kegiatan stok opname sehingga tutup jam enam sore"}],"audio_text":"本日は棚卸し作業があるので、午後六時に閉店いたします。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '棚卸し作業 (tanaoroshi sagyou) adalah pemeriksaan stok/inventaris, dan 閉店いたします berarti tutup toko.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f129621c-0ea1-4dea-9c1c-a2911c14a11e', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan pesan suara dari rekan kerja. Mengapa ia meminta tolong?', '{"options":[{"id":"opt_1","text":"Komputernya mendadak tidak berfungsi sehingga ia minta dipanggilkan staf IT"},{"id":"opt_2","text":"Ia lupa kata sandi email perusahaan"},{"id":"opt_3","text":"Printernya kehabisan kertas"},{"id":"opt_4","text":"Ia ingin membeli komputer baru"}],"audio_text":"パソコンが急に動かなくなったので、IT担当の方を呼んでいただけませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '動かなくなったので berarti karena mendadak tidak bisa beroperasi/macet.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6876f712-3f6f-422b-bc06-fbaaf557879b', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang tunggu. Mengapa pasien diminta menunggu?', '{"options":[{"id":"opt_1","text":"Karena dokter sedang keluar makan siang"},{"id":"opt_2","text":"Karena saat ini sedang sangat ramai sehingga diminta menunggu sekitar 30 menit"},{"id":"opt_3","text":"Karena mesin pendaftaran rusak"},{"id":"opt_4","text":"Karena klinik akan segera tutup"}],"audio_text":"ただいま大変混み合っておりますので、三十分ほどお待ちください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '混み合っておりますので adalah bentuk sangat sopan dari 混んでいるので (karena sedang ramai).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('52605816-18c8-48cf-85c3-79db82eb7abe', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Pilih bentuk sambung yang benar untuk Nomina 日曜日: 明日は___ので、銀行は閉まっています。', '{"options":["日曜だ","日曜な","日曜に","日曜の"],"translation":"Karena besok hari Minggu, bank tutup.","sentence_template":"明日は[blank]ので、銀行は閉まっています。"}'::jsonb, '{"selected":"日曜な"}'::jsonb, NULL, NULL, 'Nomina (日曜) diikuti な sebelum ので -> 日曜なので.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efe53b5e-05ca-478a-b699-9552b164f103', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi alasan sopan menggunakan bentuk lampau negatif: 説明書がよく___ので、先輩に質問しました。', '{"options":["わかりませんだ","わからないな","わからなかった","わからなくて"],"translation":"Karena saya kurang memahami buku panduan, saya bertanya kepada senior.","sentence_template":"説明書がよく[blank]ので、先輩に質問しました。"}'::jsonb, '{"selected":"わからなかった"}'::jsonb, NULL, NULL, 'Bentuk biasa lampau negatif わからなかった langsung disambung ので -> わからなかったので.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('680c864e-0013-4097-9351-219984861741', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Pilih alasan yang tepat untuk kalimat permintaan izin: 少し頭が___ので、休憩室で休んでもいいですか。', '{"options":["痛く","痛いな","痛いだ","痛い"],"translation":"Karena kepala saya agak sakit, bolehkah saya beristirahat di ruang istirahat?","sentence_template":"少し頭が[blank]ので、休憩室で休んでもいいですか。"}'::jsonb, '{"selected":"痛い"}'::jsonb, NULL, NULL, '痛い adalah Adjektiva-I, langsung menjadi 痛いので.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b385a56a-0dd9-45c4-8900-551c9cb046bf', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'listening', 'listening_choice', 'Dengarkan penjelasan agen properti berikut. Mengapa ruangan tersebut hangat?', '{"options":[{"id":"opt_1","text":"Ruangan ini sangat dingin karena tidak terkena matahari"},{"id":"opt_2","text":"Ruangan ini sangat hangat bahkan di musim dingin karena mendapat sinar matahari yang baik"},{"id":"opt_3","text":"Ruangan ini terlalu panas sehingga sulit ditinggali"},{"id":"opt_4","text":"Penghuni ruangan selalu menyalakan pemanas sepanjang tahun"}],"audio_text":"この部屋は日当たりがいいので、冬でもとても暖かいですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '日当たりがいいので menyatakan alasan objektif mengapa ruangan hangat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d1727dad-6c45-4dfe-848c-e3223b3219bc', 'df0a36ff-61c5-4f69-9381-fad00c0938fb', 'd1000019-0000-0000-0000-000000000004', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 道が___ので、バスより電車のほうが早いですよ。', '{"options":["混んでいる","混んでいに","混んでいだ","混んでいな"],"translation":"Karena jalanan sedang macet, kereta lebih cepat daripada bus.","sentence_template":"道が[blank]ので、バスより電車のほうが早いですよ。"}'::jsonb, '{"selected":"混んでいる"}'::jsonb, NULL, NULL, '混んでいる (kata kerja bentuk biasa) langsung diikuti ので.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('76811490-824d-4ff9-ac19-9615a12f84f7', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Pilih kalimat paling tepat untuk meminta tolong kepada manajer: 部長、来週のシフトについて少し___いただけませんか。', '{"options":["相談して","相談します","相談しない","相談した"],"translation":"Pak Manajer, bersediakah Bapak berdiskusi sebentar mengenai jadwal shift minggu depan?","sentence_template":"部長、来週のシフトについて少し[blank]いただけませんか。"}'::jsonb, '{"selected":"相談して"}'::jsonb, NULL, NULL, '相談します (berkonsultasi/berdiskusi) -> 相談して + いただけませんか.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('acab4276-7396-4e6b-ade4-5af821727e5d', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi permintaan izin salinan dokumen: この契約書を一部___いただけませんか。', '{"options":["コピーします","コピーして","コピーした","コピーする"],"translation":"Bersediakah Anda memfotokopi surat kontrak ini satu rangkap?","sentence_template":"この契約書を一部[blank]いただけませんか。"}'::jsonb, '{"selected":"コピーして"}'::jsonb, NULL, NULL, '一部 (ichibu) berarti satu rangkap; コピーします -> コピーして + いただけませんか.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('283609da-85da-4448-96d0-c88b413769bc', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan percakapan telepon ini. Apa yang diminta penelepon?', '{"options":[{"id":"opt_1","text":"Meminta agar Pak Yamada menelepon balik saat sudah kembali"},{"id":"opt_2","text":"Meminta bertemu Pak Yamada hari ini di stasiun"},{"id":"opt_3","text":"Meminta membatalkan pesanan minggu ini"},{"id":"opt_4","text":"Meminta alamat rumah Pak Yamada"}],"audio_text":"山田様はいらっしゃいませんか。それでは、お戻りにになったらお電話をいただけませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お電話をいただけませんか meminta agar pihak sana menghubungi balik dengan sangat sopan.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4522b52-7c9c-4743-98f3-3ccaba1b4598', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'listening', 'listening_choice', 'Dengarkan dialog di kantor pos. Apa yang ingin dilakukan pelanggan?', '{"options":[{"id":"opt_1","text":"Menanyakan jam tutup kantor pos"},{"id":"opt_2","text":"Meminta bantuan cara mengisi formulir pengiriman ke Indonesia"},{"id":"opt_3","text":"Membeli perangko edisi khusus"},{"id":"opt_4","text":"Mengambil paket yang datang dari Indonesia"}],"audio_text":"すみませんが、この荷物をインドネシアまで送りたいんですが、書き方を教えていただけませんか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '書き方を教えていただけませんか berarti meminta diajari cara mengisi formulir pengiriman.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('badf46a6-767c-4ca0-8568-a3476578fb1e', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda menunggu sampai jam tiga?"', '{"romaji":"Sanji made matte itadakemasen ka.","tokens":["待って","帰って","三時まで","いただけませんか。","待ちます"],"target_translation":"Bersediakah Anda menunggu sampai jam tiga?"}'::jsonb, '["三時まで","待って","いただけませんか。"]'::jsonb, NULL, NULL, '三時まで (sampai jam tiga) + 待って (menunggu, bentuk TE) + いただけませんか.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9278e366-5d99-402f-a524-9338a973f413', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, bersediakah Anda membantu pekerjaan ini sebentar?"', '{"romaji":"Sumimasen ga, kono shigoto o sukoshi tetsudatte itadakemasen ka.","display_text":"すみませんが、この仕事を少し手伝っていただけませんか。","phonetic_breakdown":["su-mi-ma-sen","ga","ko-no","shi-go-to","o","su-ko-shi","te-tsu-dat-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、この仕事を少し手伝っていただけませんか。"}'::jsonb, NULL, NULL, '手伝います (membantu) -> 手伝って + いただけませんか sangat praktis digunakan kepada rekan atau senior.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ae00677-239f-44e0-8046-660e44c7f411', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: エラーの原因が分からないので、少し見て___。', '{"options":["いけません","みませんか","なりません","いただけませんか"],"translation":"Karena saya tidak tahu penyebab errornya, maukah Anda melihatnya sebentar?","sentence_template":"エラーの原因が分からないので、少し見て[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, NULL, NULL, '見ていただけませんか meminta seseorang melihat atau memeriksa sesuatu dengan sopan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c54ea3b6-9409-4bdc-a2cd-b63de1cec054', 'e390e7ff-edb0-4f15-925b-71b575f40e82', 'fc7f7429-1673-4eb1-b1de-1551413056fe', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mohon maaf, maukah Anda mengantarkan saya sampai meja resepsionis?"', '{"romaji":"Osoreirimasu ga, uketsuke made go-annai shite itadakemasen ka.","display_text":"恐れ入りますが、受付までご案内していただけませんか。","phonetic_breakdown":["o-so-re-i-ri-ma-su-ga","u-ke-tsu-ke-ma-de","go-an-nai-shi-te","i-ta-da-ke-ma-sen-ka"]}'::jsonb, '{"expected_transcript":"恐れ入りますが、受付までご案内していただけませんか。"}'::jsonb, NULL, NULL, '案内する dipadukan dengan prefiks sopan ご dan ～ていただけませんか untuk permintaan sangat santun.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87493f0c-1a7a-49d8-a95b-841314cb160a', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''SIM / surat izin mengemudi'': 日本で車の___を取りました。', '{"options":["切手","住所","免許","領収書"],"translation":"Saya sudah mendapatkan SIM mobil di Jepang.","sentence_template":"日本で車の[blank]を取りました。"}'::jsonb, '{"selected":"免許"}'::jsonb, NULL, NULL, '免許 (menkyo) berarti lisensi atau SIM (運転免許).', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce0f6b96-4476-4fb0-8b34-ca63009458d8', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'reading', 'fill_blank', 'Lengkapi kosakata pembayaran di toko Jepang: このお店ではクレジットカードで___ができます。', '{"options":["洗濯","引っ越し","散歩","支払い"],"translation":"Di toko ini bisa melakukan pembayaran dengan kartu kredit.","sentence_template":"このお店ではクレジットカードで[blank]ができます。"}'::jsonb, '{"selected":"支払い"}'::jsonb, NULL, NULL, '支払い (shiharai) berarti pembayaran; 支払いができる berarti bisa membayar.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('71eda0c4-a3b0-4c01-b783-62d297346465', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'listening', 'listening_choice', 'Dengarkan perkenalan diri di wawancara kerja. Apa keahlian pelamar?', '{"options":[{"id":"opt_1","text":"Bisa memasak makanan Jepang dan Prancis"},{"id":"opt_2","text":"Bisa berbahasa Inggris, Indonesia, dan menggunakan Excel"},{"id":"opt_3","text":"Bisa mengemudikan truk besar"},{"id":"opt_4","text":"Bisa memperbaiki mesin pendingin"}],"audio_text":"私は英語とインドネシア語が話せます。エクセルも使えます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '英語とインドネシア語が話せます (bisa bicara Inggris & Indonesia) dan エクセルも使えます (bisa memakai Excel).', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be45da53-f949-4e0b-a0fd-14117f65a883', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'listening', 'listening_choice', 'Dengarkan informasi fasilitas apartemen. Apa yang tersedia gratis?', '{"options":[{"id":"opt_1","text":"Sarapan pagi setiap hari"},{"id":"opt_2","text":"Layanan antar-jemput stasiun"},{"id":"opt_3","text":"Wi-Fi berkecepatan tinggi gratis"},{"id":"opt_4","text":"Tempat parkir mobil pribadi"}],"audio_text":"このアパートでは、高速のワイファイが無料で使えます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '無料で使えます (muryou de tsukaemasu) berarti dapat digunakan secara gratis.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a9519750-49b0-4baa-9093-043e2b53fa98', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Di stasiun ini kita bisa naik kereta cepat."', '{"romaji":"Kono eki de kyuukou densha ni noremasu.","tokens":["乗ります。","急行電車に","この駅で","乗れます。","歩きます。"],"target_translation":"Di stasiun ini kita bisa naik kereta cepat."}'::jsonb, '["この駅で","急行電車に","乗れます。"]'::jsonb, NULL, NULL, '乗ります (naik kendaraan) berubah ke bentuk potensial menjadi 乗れます (bisa naik).', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3df33e6d-82dc-4ead-b4c4-4a3fdca08772', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bisa mengoperasikan komputer dengan lancar."', '{"romaji":"Watashi wa pasokon no sousa ga dekimasu.","display_text":"私はパソコンの操作ができます。","phonetic_breakdown":["wa-ta-shi","wa","pa-so-kon","no","so-u-sa","ga","de-ki-ma-su"]}'::jsonb, '{"expected_transcript":"私はパソコンの操作ができます。"}'::jsonb, NULL, NULL, '操作 (sousa) berarti pengoperasian; ～ができます menyatakan kemampuan.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7103439c-321c-4e9c-b711-2479df3c3f03', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', 'd1000019-0000-0000-0000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このカードがあれば、全国のコンビニで現金が___ます。', '{"options":["引き出す","引き出さ","引き出し","引き出せ"],"translation":"Jika punya kartu ini, uang tunai bisa ditarik di minimarket seluruh negeri.","sentence_template":"このカードがあれば、全国のコンビニで現金が[blank]ます。"}'::jsonb, '{"selected":"引き出せ"}'::jsonb, NULL, NULL, '引き出す (kelompok 1) berubah menjadi bentuk potensial 引き出せる (bisa menarik uang).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('07fecb7a-e73b-4ccf-8481-115bfb67f81d', 'e8f66fd9-706b-4a81-9a72-6a083be995ed', 'd1000019-0000-0000-0000-000000000001', 'listening', 'listening_choice', 'Dengarkan informasi fasilitas asrama berikut. Keunggulan apa yang tersedia?', '{"options":[{"id":"opt_1","text":"Internet di asrama hanya bisa dipakai di malam hari"},{"id":"opt_2","text":"Asrama ini tidak memiliki jaringan internet"},{"id":"opt_3","text":"Di asrama ini bisa menggunakan internet berkecepatan tinggi secara gratis"},{"id":"opt_4","text":"Penghuni asrama harus membayar mahal untuk internet"}],"audio_text":"この寮では、無料で高速のインターネットが使えます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '使えます adalah bentuk potensial dari 使う (bisa digunakan).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f87ea662-dc0b-4617-834e-ff769f3e6ad2', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客様のお荷物をフロントでお預かり___。', '{"options":["くださいます","いたします","になります","おります"],"translation":"Kami akan menitipkan/menjaga barang bawaan Anda di meja depan.","sentence_template":"お客様のお荷物をフロントでお預かり[blank]。"}'::jsonb, '{"selected":"いたします"}'::jsonb, NULL, NULL, 'お預かりいたします adalah Kenjougo yang sangat lazim digunakan staf hotel.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54096f3b-a98d-402d-ae50-0636fb3cbc0c', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: すみません、その件についてはまだ___おりません。', '{"options":["伺って","召し上がって","ご覧になって","おっしゃって"],"translation":"Maaf, mengenai hal tersebut saya belum mendengarnya.","sentence_template":"すみません、その件についてはまだ[blank]おりません。"}'::jsonb, '{"selected":"伺って"}'::jsonb, NULL, NULL, '伺う (ukagau) juga merupakan Kenjougo dari 聞く (mendengar/bertanya); 伺っておりません berarti ''belum mendengar''.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c9458e94-9160-4cf4-8c96-c3f737fee677', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan jawaban resepsionis berikut. Di mana Yamada sekarang?', '{"options":[{"id":"opt_1","text":"Yamada sedang menunggu di ruang tamu"},{"id":"opt_2","text":"Yamada akan segera mengangkat telepon"},{"id":"opt_3","text":"Penanggung jawab bernama Yamada saat ini sedang berada di luar kantor"},{"id":"opt_4","text":"Yamada sudah tidak bekerja di perusahaan ini"}],"audio_text":"申し訳ございません、担当の山田はただいま外出しております。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'おります adalah Kenjougo dari います; 外出しております berarti sedang keluar kantor.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8d533a2-67ad-4e4e-b177-84e7fa64c75c', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Nanti saya yang akan menelepon Anda."', '{"romaji":"Nochihodo watashi kara o-denwa itashimasu.","tokens":["いたします。","私から","お電話","お電話になります。","が","後ほど"],"target_translation":"Nanti saya yang akan menelepon Anda."}'::jsonb, '["後ほど","私から","お電話","いたします。"]'::jsonb, NULL, NULL, 'お電話いたします merendahkan aksi pembicara menelepon klien.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac604510-9b0b-490a-a037-f2f22db171fd', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: こちらの席でお待ちください。すぐ係の者が___。', '{"options":["いらっしゃいます","おっしゃいます","まいります","なさいます"],"translation":"Silakan menunggu di kursi ini. Staf petugas akan segera datang.","sentence_template":"こちらの席でお待ちください。すぐ係の者が[blank]。"}'::jsonb, '{"selected":"まいります"}'::jsonb, NULL, NULL, 'Staf termasuk pihak dalam (uchi) pembicara, sehingga menggunakan Kenjougo まいります.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67a770fb-4b3e-4654-b07a-38007b3a40de', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya telah membaca buku baru karya Bapak/Ibu Guru."', '{"romaji":"Sensei no atarashii go-hon o haiken itashimashita.","display_text":"先生の新しいご本を拝見いたしました。","phonetic_breakdown":["sen-sei-no","a-ta-ra-shii","go-hon-o","hai-ken","i-ta-shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先生の新しいご本を拝見いたしました。"}'::jsonb, NULL, NULL, '拝見いたしました adalah Kenjougo sopan untuk 読みました/見ました.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('60268b17-628d-4569-b632-f5115d62498c', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan ungkapan terima kasih berikut. Apa maksud pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara menolak menerima oleh-oleh tersebut"},{"id":"opt_2","text":"Pembicara memberikan oleh-oleh kepada keluarga lawan bicara"},{"id":"opt_3","text":"Pembicara lupa membawa oleh-oleh dari kampung halaman"},{"id":"opt_4","text":"Pembicara berterima kasih atas oleh-oleh dan akan menikmatinya bersama keluarga"}],"audio_text":"お土産をいただきまして、本当にありがとうございました。家族とありがたくいただきます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'いただきます adalah Kenjougo dari もらいます maupun 食べます.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d39edf67-7b77-4027-82ee-6b5aa570c7be', 'eef2b2f9-db0f-41ac-8799-ab29810fb8bc', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Besok pagi saya akan membawakan materinya untuk Anda."', '{"romaji":"Ashita no gozenchuu ni shiryou o o-mochi shimasu.","tokens":["明日の","します。","お持ちになります。","お持ち","が","午前中に","資料を"],"target_translation":"Besok pagi saya akan membawakan materinya untuk Anda."}'::jsonb, '["明日の","午前中に","資料を","お持ち","します。"]'::jsonb, NULL, NULL, 'お持ちします (お + bentuk ます + します) adalah Kenjougo dari 持って行きます.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d8ebfed-6b00-4577-b3f8-a749a31b9b39', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan pesan telepon berikut. Apa maksud pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara akan pulang cepat untuk memasak makan malam"},{"id":"opt_2","text":"Pembicara tidak perlu lembur hari ini"},{"id":"opt_3","text":"Pembicara harus lembur hari ini dan meminta lawan bicara makan malam duluan"},{"id":"opt_4","text":"Pembicara mengajak makan malam bersama di kantor"}],"audio_text":"今日は残業しなければならないので、夕飯は先に食べていてください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '残業しなければならない berarti harus lembur.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d656cfc-c2da-4544-9c99-0f46978f636c', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Formulir permohonan harus ditulis dengan pulpen hitam."', '{"romaji":"Shinseisho ni wa kuro no boorupen de kakanakereba narimasen.","display_text":"申請書には黒のボールペンで書かなければなりません。","phonetic_breakdown":["shin-sei-sho-ni-wa","ku-ro-no","boo-ru-pen-de","ka-ka-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"申請書には黒のボールペンで書かなければなりません。"}'::jsonb, NULL, NULL, '書く -> 書かない -> 書かなければなりません.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('69b13240-6833-4d23-857d-e463f0d9350a', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam bulan ini harus mentransfer uang sewa ke bank."', '{"romaji":"Kongetsuchuu ni yachin o ginkou e furikomanakereba narimasen.","tokens":["振り込みます。","今月中に","銀行へ","振り込まなければ","なりません。","家賃を","と"],"target_translation":"Dalam bulan ini harus mentransfer uang sewa ke bank."}'::jsonb, '["今月中に","家賃を","銀行へ","振り込まなければ","なりません。"]'::jsonb, NULL, NULL, '振り込む (furikomu, mentransfer) -> 振り込まない -> 振り込まなければなりません.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4976881-f21e-410b-84a9-e366a1f73b89', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 図書館で借りた本は二週間以内に返さ___。', '{"options":["てはいけません","たほうがいいです","なくてもいいです","なければなりません"],"translation":"Buku yang dipinjam di perpustakaan harus dikembalikan dalam dua minggu.","sentence_template":"図書館で借りた本は二週間以内に返さ[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, '返す -> 返さない -> 返さなければなりません.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d39d0168-ba59-4277-bdd9-6c9d388bcb53', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'listening', 'listening_choice', 'Dengarkan pengumuman ruang ujian berikut. Aturan apa yang berlaku untuk ponsel?', '{"options":[{"id":"opt_1","text":"Ponsel boleh digunakan untuk kamus saat ujian"},{"id":"opt_2","text":"Peserta ujian wajib membawa ponsel ke meja"},{"id":"opt_3","text":"Ponsel boleh dinyalakan dalam mode getar di ruang ujian"},{"id":"opt_4","text":"Di ruang ujian, daya ponsel harus dimatikan sepenuhnya"}],"audio_text":"試験会場では、携帯電話の電源を完全に切らなければなりません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '完全に切る berarti mematikan secara total, bukan sekadar mode senyap.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('776b6c87-fc78-4007-8d53-74fb8fbedf42', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya harus berkonsultasi dengan senior terlebih dahulu sebelum memutuskan."', '{"romaji":"Senpai ni soudan shite kara kimenakereba narimasen.","display_text":"先輩に相談してから決めなければなりません。","phonetic_breakdown":["sen-pai-ni","sou-dan-shi-te-ka-ra","ki-me-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"先輩に相談してから決めなければなりません。"}'::jsonb, NULL, NULL, '決める -> 決めない -> 決めなければなりません.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('723bf0d1-6e69-4e06-bf83-b9b527fcba0c', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat: "Di hari hujan mudah terpeleset, jadi harus berjalan dengan hati-hati."', '{"romaji":"Ame no hi wa suberiyasui node ki o tsukete arukanakereba narimasen.","tokens":["を","歩きます。","滑りやすいので","歩かなければ","なりません。","気をつけて","雨の日は"],"target_translation":"Di hari hujan mudah terpeleset, jadi harus berjalan dengan hati-hati."}'::jsonb, '["雨の日は","滑りやすいので","気をつけて","歩かなければ","なりません。"]'::jsonb, NULL, NULL, '歩く -> 歩かない -> 歩かなければなりません.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('97d4c85b-a712-4c20-9fdb-81bff88d2bd5', 'f72199e3-e1cd-4b58-bbc8-dad2cadb89f2', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 面接では丁寧な言葉を使わ___。', '{"options":["ないでください","なければなりません","てはいけません","たことがあります"],"translation":"Saat wawancara harus menggunakan bahasa yang sopan.","sentence_template":"面接では丁寧な言葉を使わ[blank]。"}'::jsonb, '{"selected":"なければなりません"}'::jsonb, NULL, NULL, '使う -> 使わない -> 使わなければなりません.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6e7e7a9f-e0c9-4829-af66-aec1389e10e8', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan tawaran di jalan berikut. Apa yang ditawarkan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara meminta lawan bicara membawakan barangnya"},{"id":"opt_2","text":"Pembicara mengeluh barangnya terlalu berat"},{"id":"opt_3","text":"Pembicara menawarkan bantuan untuk membawakan barang sampai gerbang tiket stasiun"},{"id":"opt_4","text":"Pembicara menanyakan lokasi gerbang tiket stasiun"}],"audio_text":"荷物が多そうですね。駅の改札まで持ってあげましょうか。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '持ってあげましょうか dipakai untuk menawarkan bantuan (kepada teman atau orang yang setara/lebih muda).', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c92d38d2-2196-4c64-b04e-d0bc41539365', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya dibantu pindahan oleh teman saya."', '{"romaji":"Tomodachi ni hikkoshi no tetsudai o shite moraimashita.","display_text":"友達に引っ越しの手伝いをしてもらいました。","phonetic_breakdown":["to-mo-da-chi-ni","hik-ko-shi-no","te-tsu-da-i-o","shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"友達に引っ越しの手伝いをしてもらいました。"}'::jsonb, NULL, NULL, '手伝いをする -> 手伝いをしてもらいました.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5ed2b7ad-a2d8-4b47-8989-80b0d767df2e', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Senior menjelaskan prosedur kerja kepada saya dengan teliti."', '{"romaji":"Senpai ga teinei ni shigoto no tejun o setsumei shite kuremashita.","tokens":["もらいました。","丁寧に","手順を","仕事の","先輩が","説明して","に","くれました。"],"target_translation":"Senior menjelaskan prosedur kerja kepada saya dengan teliti."}'::jsonb, '["先輩が","丁寧に","仕事の","手順を","説明して","くれました。"]'::jsonb, NULL, NULL, '手順 (tejun) adalah prosedur/langkah; 先輩が + 説明してくれました.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d0e0272b-659a-4aa6-9109-f35d91626d70', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: おばあさんが重い荷物を持っていたので、階段の上まで運んで___。', '{"options":["くれました","あげました","もらいました","みました"],"translation":"Karena seorang nenek membawa barang berat, saya membawakannya sampai atas tangga.","sentence_template":"おばあさんが重い荷物を持っていたので、階段の上まで運んで[blank]。"}'::jsonb, '{"selected":"あげました"}'::jsonb, NULL, NULL, 'Pembicara membantu orang lain -> 運んであげました.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a1796ea-55ce-4742-a781-45b15f4080e7', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'listening', 'listening_choice', 'Dengarkan cerita perjalanan berikut. Mengapa pembicara bisa menghemat biaya transportasi?', '{"options":[{"id":"opt_1","text":"Ongkos ke bandara ternyata lebih mahal dari perkiraan"},{"id":"opt_2","text":"Hayashi mengantar pembicara ke bandara secara gratis"},{"id":"opt_3","text":"Pembicara memberi tahu Hayashi rute murah ke bandara"},{"id":"opt_4","text":"Pembicara menghemat ongkos karena diberi tahu cara murah ke bandara oleh Hayashi"}],"audio_text":"林さんに空港までの安い行き方を教えてもらったので、交通費が節約できました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '教えてもらった berarti menerima informasi/pengajaran dari Hayashi-san.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ccb64b1c-adc1-4e50-9d96-f1e4572e0f57', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ibu setiap bulan mengirimkan bahan makanan Jepang untuk saya."', '{"romaji":"Haha wa maitsuki Nihon no shokuzai o okutte kuremasu.","display_text":"母は毎月日本の食材を送ってくれます。","phonetic_breakdown":["ha-ha-wa","mai-tsu-ki","ni-hon-no","sho-ku-zai-o","o-kut-te","ku-re-ma-su"]}'::jsonb, '{"expected_transcript":"母は毎月日本の食材を送ってくれます。"}'::jsonb, NULL, NULL, '送ってくれます menandakan tindakan rutin penuh kasih sayang kepada pembicara.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1128b546-5e1b-41c1-b7e8-9fac764dfd6d', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'writing', 'sentence_builder', 'Susun kalimat: "Sepeda saya diperbaiki oleh kakak laki-laki saya."', '{"romaji":"Watashi wa ani ni jitensha o shuuri shite moraimashita.","tokens":["が","もらいました。","修理して","くれました。","兄に","自転車を","私は"],"target_translation":"Sepeda saya diperbaiki oleh kakak laki-laki saya."}'::jsonb, '["私は","兄に","自転車を","修理して","もらいました。"]'::jsonb, NULL, NULL, '兄に + 修理してもらいました berarti meminta/menerima bantuan perbaikan dari kakak.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3dd7bb66-3267-47d3-978c-0534468d596a', 'f823c1a1-dbf7-4b5e-b709-675fdf2121b8', 'd1000019-0000-0000-0000-000000000002', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 日本語の発表の前に、日本人の友達が発音をチェックして___。', '{"options":["くれました","おきました","あげました","もらいました"],"translation":"Sebelum presentasi bahasa Jepang, teman orang Jepang membantu mengecek pelafalan saya.","sentence_template":"日本語の発表の前に、日本人の友達が発音をチェックして[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, '友達が sebagai subjek pemberi kebaikan -> チェックしてくれました.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d32137a-cce4-4e36-8bf4-c0065fd54b76', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan pelayanan berikut. Apa yang dilakukan staf?', '{"options":[{"id":"opt_1","text":"Staf menanyakan nama tamu dengan sangat sopan"},{"id":"opt_2","text":"Staf mengantar tamu menuju pintu keluar"},{"id":"opt_3","text":"Staf memperkenalkan namanya sendiri kepada tamu"},{"id":"opt_4","text":"Staf mengonfirmasi nomor kamar tamu"}],"audio_text":"お客様、恐れ入りますが、お名前をお伺いしてもよろしいでしょうか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お伺いする adalah Kenjougo dari 聞く (bertanya).', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ef5fa94-a786-403c-894b-58f73bab5311', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan segera membawakan kopi untuk Anda."', '{"romaji":"Tadaima koohii o o-mochi itashimasu.","display_text":"ただいまコーヒーをお持ちいたします。","phonetic_breakdown":["ta-da-i-ma","koo-hii-o","o-mo-chi","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"ただいまコーヒーをお持ちいたします。"}'::jsonb, NULL, NULL, 'お持ちいたします lazim dipakai saat menjamu tamu di kantor atau kafe.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('402a08f3-e524-41fe-8329-6d9328f228a7', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya Budi yang datang dari Indonesia."', '{"romaji":"Watashi wa Indoneshia kara mairimashita Budi to moushimasu.","tokens":["私は","申します。","を","ブディと","いらっしゃいました","インドネシアから","まいりました"],"target_translation":"Saya Budi yang datang dari Indonesia."}'::jsonb, '["私は","インドネシアから","まいりました","ブディと","申します。"]'::jsonb, NULL, NULL, 'まいりました (Kenjougo 来ました) dan 申します (Kenjougo 言います) sangat ideal untuk perkenalan formal.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5634a048-d4aa-4cc1-9e8d-7766a28f2fff', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: ご不明な点がございましたら、いつでも私に___ください。', '{"options":["お聞き","おっしゃって","ご存じ","ご覧"],"translation":"Jika ada hal yang kurang jelas, silakan tanyakan kepada saya kapan saja.","sentence_template":"ご不明な点がございましたら、いつでも私に[blank]ください。"}'::jsonb, '{"selected":"お聞き"}'::jsonb, NULL, NULL, 'お聞きください meminta lawan bicara bertanya dengan sopan.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('30ea23d5-b75e-43ec-9e46-1bd8302f3f01', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'listening', 'listening_choice', 'Dengarkan pembukaan acara berikut. Apa yang baru saja dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara mengakhiri presentasi produk baru"},{"id":"opt_2","text":"Pembicara meminta maaf karena membuat menunggu dan memulai presentasi produk baru"},{"id":"opt_3","text":"Pembicara meminta peserta keluar dari ruangan"},{"id":"opt_4","text":"Presentasi produk baru ditunda sampai besok"}],"audio_text":"お待たせいたしました。ただいまより、新製品の説明を始めさせていただきます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'お待たせいたしました (maaf membuat menunggu) dan 始めさせていただきます (izin memulai) adalah frasa bisnis standar.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e878e17e-9332-43db-849b-9fd9bd1199c0', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Besok saya akan menelepon Anda lagi."', '{"romaji":"Ashita mata o-denwa itashimasu.","display_text":"明日またお電話いたします。","phonetic_breakdown":["a-shi-ta","ma-ta","o-den-wa","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"明日またお電話いたします。"}'::jsonb, NULL, NULL, 'お電話いたします menunjukkan kesopanan terhadap klien atau atasan.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e130c3ac-52d8-4d2b-a37e-8c8594b492dd', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat: "Saya telah menyerahkan proposal proyek kepada kepala bagian."', '{"romaji":"Buchou ni kikakusho o o-watashi itashimashita.","tokens":["部長に","お渡しになりました。","いたしました。","企画書を","が","お渡し"],"target_translation":"Saya telah menyerahkan proposal proyek kepada kepala bagian."}'::jsonb, '["部長に","企画書を","お渡し","いたしました。"]'::jsonb, NULL, NULL, '渡す -> お渡しいたしました (Kenjougo menyerahkan).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1236dcaf-9e45-414d-9126-3dcf2c47f399', 'f82bf388-beb0-42cf-80cb-4fa87d892eb1', 'd1000019-0000-0000-0000-000000000007', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 昨日、東京支社へ___、新しい担当者に会ってきました。', '{"options":["召し上がりまして","まいりまして","いらっしゃいまして","なさいまして"],"translation":"Kemarin saya pergi ke kantor cabang Tokyo dan bertemu penanggung jawab baru.","sentence_template":"昨日、東京支社へ[blank]、新しい担当者に会ってきました。"}'::jsonb, '{"selected":"まいりまして"}'::jsonb, NULL, NULL, 'まいる -> まいりまして adalah bentuk sambung sopan dari 行って.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55cc6e80-6fc2-4213-96f9-bc18f9b76e53', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 明日は朝早いので、今夜は早く___ほうがいいですよ。', '{"options":["寝て","寝ます","寝た","寝る"],"translation":"Karena besok harus berangkat pagi, sebaiknya malam ini tidur lebih awal.","sentence_template":"明日は朝早いので、今夜は早く[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"寝た"}'::jsonb, NULL, NULL, '寝る -> bentuk た adalah 寝た + ほうがいい.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f38eaf8-3094-4e85-a7d7-e030a9130b86', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 胃が痛いときは、脂っこい食べ物を___ほうがいいです。', '{"options":["食べない","食べた","食べて","食べる"],"translation":"Saat sakit lambung, sebaiknya tidak makan makanan berminyak.","sentence_template":"胃が痛いときは、脂っこい食べ物を[blank]ほうがいいです。"}'::jsonb, '{"selected":"食べない"}'::jsonb, NULL, NULL, 'Saran untuk menghindari sesuatu menggunakan bentuk ない + ほうがいい (食べないほうがいい).', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21ed2fc0-0c85-41d6-947d-41da1796ba43', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan saran perjalanan berikut. Apa yang dianjurkan pembicara?', '{"options":[{"id":"opt_1","text":"Menyarankan naik bus malam daripada shinkansen"},{"id":"opt_2","text":"Melarang memesan tiket shinkansen sebelum hari keberangkatan"},{"id":"opt_3","text":"Menyarankan memesan kursi reservasi shinkansen lebih awal karena ramai saat libur panjang"},{"id":"opt_4","text":"Mengatakan bahwa shinkansen selalu sepi saat libur panjang"}],"audio_text":"新幹線は連休中とても混みますから、指定席を早めに予約したほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '指定席を早めに予約したほうがいい berarti sebaiknya memesan kursi reservasi lebih awal.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8640b03d-a16c-4eeb-a57c-0e8277b25e55', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau ada hal yang tidak dipahami, sebaiknya segera bertanya."', '{"romaji":"Wakaranai koto ga attara sugu shitsumon shita hou ga ii desu yo.","tokens":["ほうが","あったら","を","質問した","分からない","いいですよ。","ことが","質問する","すぐ"],"target_translation":"Kalau ada hal yang tidak dipahami, sebaiknya segera bertanya."}'::jsonb, '["分からない","ことが","あったら","すぐ","質問した","ほうが","いいですよ。"]'::jsonb, NULL, NULL, '質問する -> 質問したほうがいい.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('97fada8e-20de-4135-b8ff-bb1d0e6b7f78', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 暗い部屋で本を読むと目が悪くなるので、電気を___ほうがいいです。', '{"options":["つけた","つける","つけない","つけて"],"translation":"Membaca buku di ruangan gelap merusak mata, jadi sebaiknya menyalakan lampu.","sentence_template":"暗い部屋で本を読むと目が悪くなるので、電気を[blank]ほうがいいです。"}'::jsonb, '{"selected":"つけた"}'::jsonb, NULL, NULL, 'つける -> つけたほうがいい.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0e88a58-2aa4-42f0-a339-4cee2c496758', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di musim panas, sebaiknya sering-sering minum air."', '{"romaji":"Natsu wa komame ni suibun o totta hou ga ii desu yo.","display_text":"夏はこまめに水分を取ったほうがいいですよ。","phonetic_breakdown":["na-tsu-wa","ko-ma-me-ni","su-i-bun-o","tot-ta","hou-ga","ii-de-su-yo"]}'::jsonb, '{"expected_transcript":"夏はこまめに水分を取ったほうがいいですよ。"}'::jsonb, NULL, NULL, '水分を取る (suibun o toru) berarti mengonsumsi cairan/air minum.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf2abf2b-69cc-4d24-b26e-95b6b6541e8f', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'listening', 'listening_choice', 'Dengarkan pesan apoteker berikut. Apa larangan atau saran pentingnya?', '{"options":[{"id":"opt_1","text":"Pasien disarankan menyetir sendiri pulang dari klinik"},{"id":"opt_2","text":"Obat ini tidak menimbulkan efek samping sama sekali"},{"id":"opt_3","text":"Obat ini harus diminum tepat sebelum menyetir mobil"},{"id":"opt_4","text":"Setelah minum obat ini sebaiknya tidak menyetir mobil karena menimbulkan kantuk"}],"audio_text":"この薬を飲んだ後は眠くなりますから、車の運転はしないほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '運転はしないほうがいい memperingatkan agar tidak mengemudi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c665bae1-873b-4535-ae8b-111a2683989f', 'fd76ea7c-1983-41ba-a3a9-425cb4c37f34', 'd1000019-0000-0000-0000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat: "Kata sandi sebaiknya tidak diberitahukan kepada orang lain."', '{"romaji":"Pasuwaado wa tanin ni oshienai hou ga ii desu yo.","tokens":["他人に","教えない","が","いいですよ。","パスワードは","教えた","ほうが"],"target_translation":"Kata sandi sebaiknya tidak diberitahukan kepada orang lain."}'::jsonb, '["パスワードは","他人に","教えない","ほうが","いいですよ。"]'::jsonb, NULL, NULL, '教えないほうがいい berarti sebaiknya tidak memberitahukan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ca83d7d-97c9-409d-8744-6dc411ca2fde', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di depan pintu masuk sudah diletakkan bunga yang indah."', '{"romaji":"Genkan no mae ni kirei na hana ga kazatte arimasu.","display_text":"玄関の前にきれいな花が飾ってあります。","phonetic_breakdown":["gen-kan","no","ma-e","ni","ki-re-i","na","ha-na","ga","ka-zat-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"玄関の前にきれいな花が飾ってあります。"}'::jsonb, NULL, NULL, '飾ります (menghias/memajang) -> 飾ってあります berarti sudah dipajang dengan sengaja.', 1, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95bb2c58-6d7d-4bcb-84b0-dd8b24377b0f', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tiket kereta sudah saya beli kemarin."', '{"romaji":"Densha no kippu wa kinou mou katte arimasu.","display_text":"電車の切符は昨日もう買ってあります。","phonetic_breakdown":["den-sha","no","kip-pu","wa","ki-no-u","mo-u","kat-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"電車の切符は昨日もう買ってあります。"}'::jsonb, NULL, NULL, '買ってあります menunjukkan tiket sudah dibeli sebelumnya sebagai persiapan perjalanan.', 2, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eddf4f3e-45af-4b0b-8d27-ee9d973f009c', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di meja resepsionis sudah disiapkan peta gedung."', '{"romaji":"Uketsuke ni tatemono no chizu ga oite arimasu.","display_text":"受付に建物の地図が置いてあります。","phonetic_breakdown":["u-ke-tsu-ke","ni","ta-te-mo-no","no","chi-zu","ga","o-i-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"受付に建物の地図が置いてあります。"}'::jsonb, NULL, NULL, '置きます (meletakkan) -> 置いてあります berarti sudah diletakkan agar tamu bisa mengambilnya.', 3, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('194c385f-0b47-4dbb-b75c-2c86e190fbef', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di dalam kulkas sudah didinginkan minuman."', '{"romaji":"Reizouko ni nomimono ga hiyashite arimasu.","tokens":["冷えて","飲みます","冷蔵庫に","冷やして","あります。","飲み物が"],"target_translation":"Di dalam kulkas sudah didinginkan minuman."}'::jsonb, '["冷蔵庫に","飲み物が","冷やして","あります。"]'::jsonb, NULL, NULL, '冷やします (mendinginkan, transitif) -> 冷やしてあります.', 4, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a38cf90c-2493-474a-92f9-73ed626873d8', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Di pintu sudah ditempel pengumuman hari libur."', '{"romaji":"Doa ni yasumi no oshirase ga hatte arimasu.","tokens":["お知らせを","お知らせが","貼って","あります。","休みの","ドアに","貼ります"],"target_translation":"Di pintu sudah ditempel pengumuman hari libur."}'::jsonb, '["ドアに","休みの","お知らせが","貼って","あります。"]'::jsonb, NULL, NULL, '貼ります (menempelkan) -> 貼ってあります, dengan subjek keadaan お知らせが.', 5, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b347065e-62da-495a-9465-0df3ccac2abd', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Meja makan sudah dibersihkan sebelum tamu datang."', '{"romaji":"Okyakusama ga kuru mae ni, teeburu ga kirei ni fuite arimasu.","tokens":["拭きます","拭いて","きれいに","テーブルが","汚れて","あります。","お客様が来る前に、"],"target_translation":"Meja makan sudah dibersihkan sebelum tamu datang."}'::jsonb, '["お客様が来る前に、","テーブルが","きれいに","拭いて","あります。"]'::jsonb, NULL, NULL, '拭きます (mengelap) -> 拭いてあります menyatakan meja sudah dalam kondisi bersih terlap.', 6, '2026-11-25T18:49:03.043024+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('edd3dc21-fb36-4255-b6a1-bfec1917623f', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di atas meja, piring dan gelas sudah ditata."', '{"romaji":"Teeburu no ue ni osara to koppu ga narabete arimasu.","display_text":"テーブルの上にお皿とコップが並べてあります。","phonetic_breakdown":["tee-bu-ru-no","u-e-ni","o-sa-ra-to","kop-pu-ga","na-ra-be-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"テーブルの上にお皿とコップが並べてあります。"}'::jsonb, NULL, NULL, '並べてあります menjelaskan bahwa piring dan gelas telah disiapkan untuk keperluan makan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('60d80723-833e-4f67-8ae4-18565d11c5de', 'ff114aac-30bb-431e-ae56-0767dd581036', '6cda8b61-f64d-4483-bc37-d0ab70789858', 'writing', 'sentence_builder', 'Susun kalimat: "Hotelnya sudah dipesan sebelumnya, jadi tenang saja."', '{"romaji":"Hoteru wa sudeni yoyaku shite arimasu kara anshin shite kudasai.","tokens":["予約します","のに","ホテルは","安心してください。","予約して","すでに","ありますから"],"target_translation":"Hotelnya sudah dipesan sebelumnya, jadi tenang saja."}'::jsonb, '["ホテルは","すでに","予約して","ありますから","安心してください。"]'::jsonb, NULL, NULL, '予約してあります menegaskan bahwa pemesanan sudah beres dilakukan sebelum berangkat.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
